} DoublyLinkedList;

void initSession(UESession** session) {
    *session = (UESession*)malloc(sizeof(UESession));
    (*session)->rrcCmacIdentityList = (RrcCmacIdentityList_t*)malloc(sizeof(RrcCmacIdentityList_t));
