}

void deinitSession(UESession** session) {
    free((*session)->rrcCmacIdentityList);
    (*session)->rrcCmacIdentityList = NULL;

    free(*session);
    *session = NULL;
}

DoublyLinkedList* initDoublyLinkedList() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));

    if(pthread_mutex_init(&list->lock, NULL) != 0){
        free(list);
        return NULL;
    }

    list->head = NULL;
    list->tail = NULL;
    return list;
}

void deinitDoublyLinkedList(DoublyLinkedList** list) {
    UESession* session = (*list)->head;
    while (session != NULL){
        UESession* temp = session;
        session = session->next;
        deinitSession(&temp);
    }

    pthread_mutex_destroy(&(*list)->lock);
    free(*list);
    *list = NULL;
}
```

