```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

void allocate_and_initialize(long **offsets, int **keys, Record **records, size_t count) {
    srand(time(NULL)); // seed the random number generator

    *offsets = malloc(count * sizeof(**offsets));
    if (*offsets == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    *keys = malloc(count * sizeof(**keys));
    if (*keys == NULL) {
        free(*offsets); // clean up previously allocated memory
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    *records = malloc(count * sizeof(**records));
    if (*records == NULL) {
        free(*offsets); // clean up offsets allocation
        free(*keys); // clean up keys allocation
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; i++) {
        (*records)[i].value = rand(); // set random value to the record's int field
    }
}
```
This function takes three pointers, which it will use to initialize and allocate memory for. After allocation, it populates each 'Record' in the records array with a random integer using the `rand` function. If any of the memory allocations fail, the program prints an error message, frees previously allocated memory (if any), and exits.

