['Implementing such a complex system would require multiple files and a significant amount of code. Here is an example of how you might start implementing this system in C, using POSIX threads for thread synchronization and a simple linked list to manage semaphores. Please note that writing production-quality code requires more extensive testing, error handling, and configuration management.

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

typedef struct Semaphore {
    sem_t* sem;
    int id;
    struct Semaphore* next;
} Semaphore;

Semaphore* head = NULL;
pthread_mutex_t lock;

void createSemaphore(int value, int id) {
    pthread_mutex_lock(&lock);
    Semaphore* semaphore = malloc(sizeof(Semaphore));
    semaphore->sem = malloc(sizeof(sem_t));

    if (sem_init(semaphore->sem, 0, value) == -1) {
        perror("Error initializing semaphore");
        exit(EXIT_FAILURE);
    }

    semaphore->id = id;
    semaphore->next = head;
    head = semaphore;

    pthread_mutex_unlock(&lock);
}

void deleteSemaphore(int id) {
    pthread_mutex_lock(&lock);
    Semaphore* curr = head;
    Semaphore* prev = NULL;

    while (curr != NULL && curr->id != id) {
        prev = curr;
        curr = curr->next;
    }

    if (curr == NULL) {
        printf("Semaphore with ID %d not found.\n", id);
    } else {
        if (prev != NULL) {
            prev->next = curr->next;
        } else {
            head = curr->next;
        }

        sem_destroy(curr->sem);
        free(curr->sem);
        free(curr);
    }

    pthread_mutex_unlock(&lock);
}

void waitSemaphore(int id) {
    Semaphore* curr = head;

    while (curr != NULL && curr->id != id) {
        curr = curr->next;
    }

    if (curr == NULL) {
        printf("Semaphore with ID %d not found.\n", id);
    } else {
        if (sem_wait(curr->sem) == -1) {
            perror("Error waiting on semaphore");
        }
    }
}

void signalSemaphore(int id) {
    Semaphore* curr = head;

    while (curr != NULL && curr->id != id) {
        curr = curr->next;
    }

    if (curr == NULL) {
        printf("Semaphore with ID %d not found.\n", id);
    } else {
        if (sem_post(curr->sem) == -1) {
            perror("Error signaling semaphore");
        }
    }
