public:
    explicit LoadTester(int numThreads) : numThreads_(numThreads), requests_() {}

    void addRequest(const RequestInfo& request) {
        requests_.push_back(request);
    }

    // Start load testing
    void startTesting() {
        std::vector<std::thread> threads;

        for (int i = 0; i < numThreads_; ++i) {
            threads.emplace_back([this]() { this->worker(); });
        }

        // Wait for all threads to finish
        for(auto& t : threads){
            if(t.joinable()) 
                t.join();
        }
