using System;
using System.Collections.Generic;
using System.Data;
using System.Threading.Tasks;
using System.Linq;
using RabbitMQ.Client;
using RabbitMQ.Client.Events;
using System.Text;

public class DataProcessor
{
    private IConnection _connection;
    private IModel _channel;
    private string _queueName;

    public DataProcessor(string queueName, string hostname)
    {
        var factory = new ConnectionFactory() { HostName = hostname };
        this._connection = factory.CreateConnection();
        this._channel = this._connection.CreateModel();
        this._queueName = queueName;

        // Declare a queue to ensure it exists before we try to use it
        _channel.QueueDeclare(queue: _queueName, durable: false, exclusive: false, autoDelete: false, arguments: null);
    }

    public async Task ProcessRecordsAsync(List<DataRecord> records, IDbConnection dbConn, string sqlCommand)
    {
        try
        {
            // Open DB Connection and begin transaction
            dbConn.Open();
            using (var trans = dbConn.BeginTransaction())
            {
                foreach (var batch in records.Batch(100))  // Process in batches of 100
                {
                    foreach (var record in batch)
                    {
                        var properties = _channel.CreateBasicProperties();
                        var body = Encoding.UTF8.GetBytes(record.ToString());
                        _channel.BasicPublish(exchange: "", routingKey: _queueName, basicProperties: properties, body: body);

                        // Alternatively, you could insert directly into the DB if RabbitMQ is not required for decoupling
                        using (var command = dbConn.CreateCommand())
                        {
                            command.CommandText = sqlCommand;
                            // Populate parameters here...

                            await command.ExecuteNonQueryAsync(); 
                        }
                    }

                    // Commit after each batch to preserve data integrity in case of errors
                    trans.Commit();  
                }
            }
        }
        catch (Exception e)
        {
            Console.WriteLine(e);
            throw;
        }
    }
}

public static class ListExtensions
{
    public static IEnumerable<IEnumerable<T>> Batch<T>(this IEnumerable<T> source, int size)
    {
        T[] bucket = null;
        var count = 0;

        foreach (var item in source)
        {
            if (bucket == null)
                bucket = new T[size];

            bucket[count++] = item;

            if (count != size)
                continue;

            yield return bucket.Select(x => x);

            bucket = null;
            count = 0;
        }

        // Return the last batch if it has fewer elements than 'size'
        if (bucket != null && count > 0)
            yield return bucket.Take(count);
    }
}
```
Note: This code assumes that `DataRecord` is a class or struct you define to hold your data, and that it correctly implements `ToString()` for serialization. 

Also, this simple example does not cover the full range of possible edge cases, such as handling network failures, message queue failures, transaction rollbacks, etc. In a production environment, you would want to have more robust error-handling mechanisms in place.
