```python
from flask import Flask, request
from pymongo import MongoClient
import logging
import jsonschema  # Used to validate schema
from functools import wraps
from datetime import datetime
from redis import Redis  # In-memory data store
import requests  # To handle external notification service

app = Flask(__name__)
client = MongoClient('mongodb://localhost:27017')  # Connect to MongoDB server
db = client['database_name']  # Specify the database name
collection = db['collection_name']  # Specify collection name
cache = Redis(host='localhost', port=6379)  # Connect to Redis instance
notification_url = 'http://external-service.com/notify'  # External service endpoint
logging.basicConfig(filename='logs.txt')

# Define schema for validation
schema = {
    "type": "object",
    "properties": {
        "field1": {"type": "string"},
        "field2": {"type": "number"}
    },
    "required": ["field1"]
}

def validate_resource(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        resource = request.json
        try:
            jsonschema.validate(instance=resource, schema=schema)
        except jsonschema.exceptions.ValidationError as err:
            return str(err), 400
        return f(*args, **kwargs)
    return decorated

@app.route('/api/resources/<id>', methods=['PUT', 'DELETE'])
@validate_resource
def update_or_delete(id):
    if request.method == 'PUT':  # Update resource
        updated_data = request.json or {}

        # Partial updates using $set operator
        result = collection.update_one({"_id": id}, {"$set": updated_data})

        if result.modified_count:
            cache.delete(id)  # Delete from cache as data has changed

            # Notify external service of the update
            try:
                requests.post(notification_url, json=updated_data, timeout=5)
            except requests.exceptions.RequestException:
                logging.warning('External service unavailable')

        return '', 204 if result.modified_count else 404  # Return 204 if modified or 404 otherwise
    elif request.method == 'DELETE':  # Delete resource
        collection.delete_one({"_id": id})
        cache.delete(id)  # Delete from cache as data has changed

        # Notify external service of the deletion
        try:
            requests.post(notification_url, json={"deleted": True}, timeout=5)
        except requests.exceptions.RequestException:
            logging.warning('External service unavailable')

        return '', 204
```
