public class XmlParserAndEnvVarHandler
{
    private string xmlDir = Environment.GetEnvironmentVariable("XML_DIR");

    public void ParseWithXpath(string fileName, string elementName)
    {
        try
        {
            var docNav = new XPathDocument(XmlDocument.Load(fileName)).CreateNavigator();
            var expression = $"//{elementName}";
            var iterator = docNav.Select(expression);

            if (iterator.MoveNext())
            {
                Console.WriteLine($"First Element Found: {iterator.Current?.Value}");

                if (iterator.MoveNext())
                    Console.WriteLine("Warning: Multiple elements found with the same name.");
            }
            else
                Console.WriteLine("Warning: No element found with the given name.");
        }
        catch(Exception ex)
        {
            Console.WriteLine($"Error occurred while parsing XML: {ex.Message}");
        }
    }

    public void CreateAndSetEnvVarIfNotExists()
    {
        if (string.IsNullOrEmpty(xmlDir)) 
        {
            xmlDir = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "XML_DIR");

            try
            {
                Directory.CreateDirectory(xmlDir);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error creating directory: {ex.Message}");
            }

            Environment.SetEnvironmentVariable("XML_DIR", xmlDir, EnvironmentVariableTarget.Machine);
        } 
        else if (!Directory.Exists(xmlDir)) 
        {
            try
            {
                xmlDir = Path.GetFullPath(xmlDir);

                if (Directory.Exists(xmlDir))
                    Environment.SetEnvironmentVariable("XML_DIR", xmlDir, EnvironmentVariableTarget.Machine);
                else 
                    Console.WriteLine("Error: Specified directory path is invalid and cannot be corrected.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error getting full path for specified directory: {ex.Message}");
            }
        }
    }
}
