['```java
import java.security.*;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;
import org.slf4j.*;

public class StringHasher {
    private static final Logger logger = LoggerFactory.getLogger(StringHasher.class);
    private static final Map<List<String>, String> cache = Collections.synchronizedMap(new HashMap<>());

    // Expiration policy and size limits are subject to requirements
    private static int expiryMinutes = 60; 
    private static int maxCacheSize = 1_000_000; 

    public String getConcatenatedHash(String... strings) {
        long startTime = System.currentTimeMillis();

        List<String> keyList = Arrays.asList(strings);
        if (cache.containsKey(keyList)) {
            logger.info("Cache hit for hash of {}", keyList);

            // Extract cached value and its timestamp
            Map.Entry<String, Long> cacheValue = cache.get(keyList);
            long ageInMinutes = (System.currentTimeMillis() - cacheValue.getValue()) / 60_000;

            if (ageInMinutes < expiryMinutes) {
                logger.info("Cache entry is valid");
                return cacheValue.getKey();
            } else {
                logger.info("Cache entry has expired, removing from cache");
                cache.remove(keyList);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (String str : strings) {
            sb.append(str);
        }

        String md5Hex = DigestUtils.md5Hex(sb.toString());
        logger.info("Computed MD5 hash in {} ms", System.currentTimeMillis() - startTime);

        if (cache.size() >= maxCacheSize) {
            // Remove oldest entry when cache is at capacity
            Map.Entry<List<String>, String> oldest = cache.entrySet().iterator().next();
            logger.info("Removing oldest entry from cache: {}", oldest);
            cache.remove(oldest.getKey());
        }

        // Add new computed hash to the cache
        cache.put(keyList, new AbstractMap.SimpleEntry<>(md5Hex, System.currentTimeMillis()));
        logger.info("Cached MD5 hash for {}", keyList);
        return md5Hex;
    }

    public void setExpiryMinutes(int minutes) {
        expiryMinutes = minutes;
    }

    public void setMaxCacheSize(int size) {
        maxCacheSize = size;
    }
}
```
In this code, the `StringHasher` class maintains a synchronized cache of computed MD5 hashes. It checks for cached results before computing the hash to avoid unnecessary computation. When the cache is at its maximum size, it removes the oldest entry before adding new ones. 

The expiration policy and cache size can be adjusted by calling `setExpiryMinutes()` and `setMaxCacheSize()` respectively. Note that this implementation uses a simple LRU (Least Recently Used) eviction strategy for cached items, which might not be optimal in all use cases. A more sophisticated strategy might be necessary depending on the specific requirements of your application.
']

