['Here is a basic implementation in C# using async/await for HTTP requests, and caching with `MemoryCache` class:

```csharp
using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using System.Runtime.Caching;
using Newtonsoft.Json;

public class ContentManagementSystem
{
    private const string CacheKeyFormat = "PageSection_{0}_Element_{1}";
    private readonly HttpClient _httpClient = new();
    private readonly MemoryCache _cache = MemoryCache.Default;

    public async Task UpdateContent(int pageSectionId, int elementId, string htmlContent)
    {
        if (pageSectionId <= 0 || elementId <= 0) throw new ArgumentException("Invalid IDs");
        if (string.IsNullOrWhiteSpace(htmlContent)) throw new ArgumentException("HTML content cannot be null or empty");

        var cacheKey = string.Format(CacheKeyFormat, pageSectionId, elementId);
        // Try to get the cached value first
        var cachedContent = _cache[cacheKey] as string;
        if (cachedContent != htmlContent)
        {
            if (htmlContent.Length > ContentLimits.MaxContentLength) 
                throw new ArgumentException($"HTML content exceeds limit of {ContentLimits.MaxContentLength} characters");

            // You might need to add HTML validation and sanitization here based on your CMS's specifications

            var content = new StringContent(htmlContent, Encoding.UTF8, "application/json");
            var response = await _httpClient.PostAsync($"https://your-cms-api/{pageSectionId}/{elementId}", content);

            if (response.IsSuccessStatusCode)
            {
                // Cache the new value and set a policy for when to remove it from cache
                var cacheItemPolicy = new CacheItemPolicy { SlidingExpiration = TimeSpan.FromHours(1) };
                _cache.Set(cacheKey, htmlContent, cacheItemPolicy);
            }
            else
            {
                // Rollback or handle the error appropriately here
            }
        }
    }
