["Here's a simple, high-level implementation of what you requested in JavaScript using Node.js's `fs` and `async` libraries.

```javascript
const fs = require('fs');
const path = require('path');
const async = require('async');

class FileProcessor {
  constructor(directoryPath, concurrencyLimit = 10, memoryLimitMB = 500) {
    this.directoryPath = directoryPath;
    this.concurrencyLimit = concurrencyLimit;
    this.memoryLimitBytes = memoryLimitMB * 1024 * 1024;
    this.queue = async.queue(this.processFile.bind(this), this.concurrencyLimit);
    this.files = [];
    this.results = {};
    this.readFiles();
  }

  readFiles() {
    fs.readdirSync(this.directoryPath).forEach((file) => {
      const filePath = path.join(this.directoryPath, file);
      if (fs.lstatSync(filePath).isFile()) this.files.push(filePath);
    });
  }

  processFiles() {
    this.files.forEach((file) => {
      const stats = fs.statSync(file);
      if (stats['size'] > this.memoryLimitBytes / this.concurrencyLimit) {
        throw new Error('File too large for current configuration');
      } else {
        this.queue.push(file, function(err, result){
          // handle err and use result
          if(!err) this.results[file] = result;
        });
      }
    });
  }

  processFile(filePath, callback) {
    fs.readFile(filePath, 'utf8', (err, data) => {
      if (err) return callback(err);

      // Process file content here...
      const processedData = this.processContent(data);

      process.memoryUsage().heapUsed > this.memoryLimitBytes ? 
        setTimeout(() => callback(null, processedData), 0) :
        callback(null, processedData);
    });
  }

  processContent(content) {
    // Implement your content processing logic here...
    return processedContent;
  }
}
```
This code reads a directory of files and processes each file in parallel (up to the `concurrencyLimit`). Each file's memory usage is checked after its read operation, if it exceeds available memory limit per process then it will be deferred until resources become available. If an error occurs during processing, that error will be passed to the callback function and can be handled accordingly.

Please note: This is a high-level implementation and might not cover all possible edge cases or use-cases depending on your specific requirements. It also doesn't handle file dependencies as it would require more complex logic to determine which files are dependent upon others, how they should be processed relative to each other, and how errors should be handled across those files. You may want to consider using an existing library that provides this functionality or building a more sophisticated system for handling these cases.
