["```javascript
const BlueSlip = require('blueslip');
const MonitoringServiceClient = require('monitoring-service-client');

let summary = { total: 0, passed: 0, failed: 0, skipped: [] };

async function executeTests(modulePath, testSuite) {
    try {
        const module = require(modulePath);
        let testsRan = 0;

        for (const test of testSuite) {
            if (test.skip && summary.skipped.includes(test.name)) {
                continue;
            }

            try {
                await test(module, BlueSlip);
                summary.passed++;
            } catch (err) {
                console.error(`Test ${test.name} failed with: ${err}`);
                summary.failed++;

                if (!summary.skipped.includes(test.name)) {
                    summary.skipped.push(test.name);
                }
            } finally {
                BlueSlip.reset();
                testsRan++;
                summary.total = Math.max(testsRan, summary.total);

                MonitoringServiceClient.reportTestResult({
                    name: test.name,
                    passed: !summary.skipped.includes(test.name) && testsRan <= summary.passed,
                });
            }
        }
    } catch (err) {
        console.error(`Failed to load module ${modulePath} for testing: ${err}`);
        MonitoringServiceClient.reportTestResult({
            name: 'Module loading failed',
            passed: false,
        });
    }

    return summary;
}
