class StreamManager {
  constructor() {
    this.dataSource = null;
    this.dataProcessor = null;
    this.monitoringSystem = null;
    this.isStreaming = false;
    this.streamIntervalId = null;
  }

  switchDataSource(newSource) {
    if (this.isStreaming) {
      throw new Error("Cannot switch data source while streaming is in progress");
    }
    this.dataSource = newSource;
  }

  switchDataProcessor(newProcessor) {
    if (this.isStreaming) {
      throw new Error("Cannot switch processor while streaming is in progress");
    }
    this.dataProcessor = newProcessor;
  }

  switchMonitoringSystem(newSystem) {
    this.monitoringSystem = newSystem;
  }

  startStream() {
    if (this.isStreaming || !this.dataSource || !this.dataProcessor) {
      throw new Error("Cannot start stream");
    }

    console.log('Start streaming data...');
    this.streamIntervalId = setInterval(async () => {
      try {
        const data = await this.dataSource.fetchData();
        this.dataProcessor.processData(data);
      } catch (err) {
        console.error("Error processing data:", err);
      }
    }, 1000); // delay of 1 second between each fetch and process operation

    this.isStreaming = true;
  }

  stopStream() {
    if (!this.isStreaming) {
      throw new Error("Cannot stop stream, as it is not currently active");
    }

    clearInterval(this.streamIntervalId);
    this.isStreaming = false;

    console.log('Stopped streaming data...');
    if (this.monitoringSystem) {
      this.monitoringSystem.notifyStatusChange("Stream stopped");
    }
  }
}

