["Here's a Java implementation of such a function using priority queue to keep track of ongoing requests, logging service for recording processing times and batching entries to avoid exceeding throughput limit. It also checks if the request is still in progress before adding it into PriorityQueue. This way we don't process overlapping requests multiple times:

```java
import java.util.*;

public class NetworkRequest {
    private long startTime;
    private long endTime;

    public NetworkRequest(long start, long end) {
        this.startTime = start;
        this.endTime = end;
    }

    // getters and setters...
}

public class ProcessNetworkStream {
    private static final int LOGGING_THROUGHPUT = 100;

    public long processRequests(List<NetworkRequest> networkRequests) throws InterruptedException {
        PriorityQueue<Long> ongoingRequestEndTimes = new PriorityQueue<>();

        for (NetworkRequest request : networkRequests) {
            // Remove finished requests from the queue.
            while (!ongoingRequestEndTimes.isEmpty() && ongoingRequestEndTimes.peek() < System.currentTimeMillis()) {
                ongoingRequestEndTimes.poll();
            }

            ongoingRequestEndTimes.offer(request.getEndTime());
        }

        long maxConcurrency = Integer.MIN_VALUE;
        List<Long> processingTimes = new ArrayList<>();
        while (!ongoingRequestEndTimes.isEmpty()) {
            if (ongoingRequestEndTimes.peek() >= System.currentTimeMillis()) {
                // Record the time of each request being processed and batch log entries to avoid exceeding capacity.
                long currentTime = System.currentTimeMillis();
                processingTimes.add(currentTime - ongoingRequestEndTimes.poll());

                maxConcurrency = Math.max(maxConcurrency, ongoingRequestEndTimes.size());
            } else {
                // Sleep until next request is ready to process.
                Thread.sleep(ongoingRequestEndTimes.peek() - System.currentTimeMillis());
            }

            // Batch log entries if we hit the logging throughput limit.
            if (processingTimes.size() >= LOGGING_THROUGHPUT) {
                batchLogEntries(processingTimes);
                processingTimes.clear();
            }
        }

        return maxConcurrency;
    }

    private void batchLogEntries(List<Long> entries) {
        // Dummy function to represent logging service interaction.
    }
}
```
