use std::time::Duration;
use futures::executor::block_on;
use reqwest::Url;

pub struct HttpClient {
    client: reqwest::Client,
}

impl HttpClient {
    pub fn new(disable_certificate_validation: bool) -> Self {
        let client = if disable_certificate_validation {
            reqwest::ClientBuilder::new().danger_accept_invalid_certs(true).build().unwrap()
        } else {
            reqwest::Client::new()
        };

        HttpClient { client }
    }

    pub async fn get(&self, url: Url) -> Result<String, Box<dyn std::error::Error>> {
        let response = self.client.get(url).send().await?;
        let body = response.text().await?;
        Ok(body)
    }

    pub async fn post(&self, url: Url, data: &str) -> Result<(), Box<dyn std::error::Error>> {
        self.client.post(url).body(data).send().await?;
        Ok(())
    }
}

#[tokio::main]
async fn main() {
    let client = HttpClient::new(false); // Disable certificate validation
    let url = Url::parse("https://example.com").unwrap();

    block_on(client.get(url)).unwrap();
}
```
