["Here's a potential implementation in JavaScript using async/await syntax and Node.js streams for efficient memory management and error handling with try-catch blocks. This function also uses the 'axios' library to handle HTTP requests. 

```javascript
const fs = require('fs');
const axios = require('axios');
const { pipeline } = require('stream/promises');
const config = require('./config'); // Import your configuration file

async function fetchAndSaveCertificate(oAuthRequest) {
    const { privateKeyPath, certificatePath, fallbackPath, environmentConfigs } = oAuthRequest;
    let pemData = '';

    try {
        // Fetch the PEM data from the specified paths. If any fail, log an error and continue
        for (let path of [privateKeyPath, certificatePath]) {
            const response = await axios.get(path);
            pemData += `${response.data}\n`;
        }
    } catch (err) {
        console.error('Error fetching PEM data:', err);

        // Try to fetch from fallback path if specified
        const fallbackResponse = await axios.get(fallbackPath).catch(() => {});
        if (fallbackResponse) pemData += `${fallbackResponse.data}\n`;
    }

    try {
        // Save the combined PEM data to a file, potentially handling throttling and resuming
        const writeStream = fs.createWriteStream('combinedPEM.pem');
        let totalBytes = 0;

        while (totalBytes < pemData.length) {
            const nextBatchSize = Math.min(config.throttleLimit, pemData.length - totalBytes);
            await pipeline(fs.createReadStream('combinedPEM.pem', { start: totalBytes }), writeStream);
            totalBytes += nextBatchSize;

            // Resume after a delay to avoid overwhelming the system
            if (totalBytes < pemData.length) await new Promise(resolve => setTimeout(resolve, config.resumeDelay));
        }

        return 'Successfully saved combined PEM data';
    } catch (err) {
        console.error('Error saving PEM data:', err);
        throw err; // Rethrow the error to be handled by calling function
    }
}
```
This code assumes you have a config file with properties 'throttleLimit' and 'resumeDelay' that control how much data is fetched at once, and the delay after which it resumes. The combined PEM data will be saved to a file named 'combinedPEM.pem'. You can customize this function according to your specific requirements.
"]

