class UserPasswordService {
    private $db;
    private $authSystem;

    public function __construct(DatabaseInterface $db, AuthenticationInterface $authSystem) {
        $this->db = $db;
        $this->authSystem = $authSystem;
    }

    public function updatePassword(string $userId, string $newPassword): bool {
        // Validate password strength
        if (!$this->isStrongEnough($newPassword)) {
            throw new Exception('Password does not meet requirements.');
        }

        $previousPasswords = $this->authSystem->getPreviousPasswords($userId);

        // Check password history for uniqueness
        if (in_array($newPassword, $previousPasswords)) {
            throw new Exception('Cannot reuse previous passwords.');
        }

        $lastUpdated = $this->authSystem->getLastUpdateTime($userId);
        $timeSinceLastChange = time() - strtotime($lastUpdated);

        // Check if the last update was less than a certain threshold (e.g., 1 day)
        if ($timeSinceLastChange < PASSWORD_CHANGE_THRESHOLD) {
            throw new Exception('Please wait before updating your password again.');
        }

        $this->db->beginTransaction();

        try {
            $retries = 0;

            do {
                try {
                    // Update user's password in the database
                    $this->authSystem->updateUserPassword($userId, $newPassword);

                    // Commit transaction on successful update
                    $this->db->commit();
                    return true;
                } catch (DatabaseException | NetworkException $e) {
                    $retries++;
                    sleep(RETRY_WAIT_TIME); // Wait before retrying
                }
            } while ($retries < MAX_RETRIES);
        } catch (Throwable $t) {
            $this->db->rollback(); // Roll back transaction on unsuccessful update

            throw new Exception('Unable to update password after multiple attempts.');
        }
    }

    private function isStrongEnough(string $password): bool {
        return preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!]).*$/', $password) && strlen($password) >= MINIMUM_PASSWORD_LENGTH;
    }
}
