["```cpp
#include <vector>
#include <mutex>
#include <atomic>

struct OctreeNode {
    std::vector<OctreeNode*> children;
    float featureData[8];
};

class Octree {
private:
    OctreeNode *root;
    size_t maxLeafNodes, depthLimit, currentLeafNodes;
    double featureSize;
    std::mutex insertMutex; // Mutex for concurrent access during inserts

public:
    Octree(size_t leafCapacity, double fs, size_t dl) : maxLeafNodes(leafCapacity), depthLimit(dl), featureSize(fs), currentLeafNodes(0) {
        root = new OctreeNode();
    }

    ~Octree() { 
       deleteTree(root);
    }

    void deleteTree(OctreeNode* node){
      for (auto child : node->children) {
          if (child != nullptr) {
              deleteTree(child);
          }
      }
      delete node;
    }

    bool insertFeatureData(double feature[8]) {
        std::lock_guard<std::mutex> lock(insertMutex); // Locking for thread safety

        if (currentLeafNodes >= maxLeafNodes) {
            return false; // Handle overflow, you might want to implement a fallback mechanism here.
        }

        OctreeNode* current = root;
        int depth = 0;
        while(depth < depthLimit){
            if (current->children.size() < 8) {
                break;
            } else {
                ++depth;
                // Here we are using a simple hashing function to distribute children across different nodes, 
                // you might want to implement your own distribution strategy considering spatial locality and speed trade-off
                int hash = std::hash<double>{}(feature[0]) % 8; 
                if (current->children[hash] == nullptr) {
                    current->children[hash] = new OctreeNode();
                    ++depth;
                } else {
                    current = current->children[hash];
                }
            }
        }

        for(int i = 0; i < 8; ++i){
            current->featureData[i] = feature[i];
        }
        ++currentLeafNodes;
        return true;
    }

    double* getFeatureForNode(OctreeNode* node) {
       if (node == nullptr || node->children.size() != 0) {
          return nullptr; // Invalid node or not a leaf node, you might want to throw an exception here instead
       } else {
           return node->featureData;
       }
    }
};
``` 
The code above is just a basic implementation and does not include many features that would be necessary in a production setting. It also doesn't handle memory fragmentation optimally, concurrency issues, or fallback mechanisms when the tree gets too large. Please note that this is a simple example and it may need to be adjusted according to your specific requirements.
