function aggregate(dataArray, initialValue = {}, config) {
    return new Promise((resolve, reject) => {
        let result = initialValue;

        const processElement = (element) => {
            if (typeof element === 'number') {
                result[config.numbers] += element;
            } else if (typeof element === 'string' && 
                       config.strings.length + element.length <= config.maxStringLength) {
                result[config.strings] += element;
            } else if (typeof element === 'object') {
                for(let key in element){
                    // Check for unique keys only and non-conflicting keys
                    if(!result.hasOwnProperty(key)){
                        result[key] = element[key];
                    } 
                }
            } else{
                reject('Data anomaly detected');
            }
        };

        try {
            for (let i = 0; i < dataArray.length; i++) {
                processElement(dataArray[i]);
            }
            resolve(result);
        } catch (err) {
            reject(err);
        }
    });
}
```

