['Sure, here's a basic C implementation using error handling and dynamic memory management (with `malloc` and `free`). Please note that this code doesn't include specific validation or thread safety features like locks or atomic operations. For those advanced topics you would typically have to use operating system-specific API calls or language-specific libraries, which are beyond the scope of this example.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct ConfigNode {
    char* key;
    char* value;
    struct ConfigNode* next;
} ConfigNode;

ConfigNode* load_config(const char* path) {
    FILE *file = fopen(path, "r");

    if (file == NULL) {
        printf("Failed to open file.\n");
        return NULL;
    }

    ConfigNode* head = NULL;
    ConfigNode** tail_ptr = &head;

    char buffer[256];
    while(fgets(buffer, sizeof(buffer), file)) {
        // Skip comments and empty lines
        if (buffer[0] == '#' || buffer[0] == '\n') continue;

        // Assuming key-value pairs for simplicity
        char* equal_sign = strchr(buffer, '=');
        if (equal_sign == NULL) {
            printf("Invalid config line.\n");
            fclose(file);

            while(*tail_ptr != NULL) {
                ConfigNode* temp = *tail_ptr;
                *tail_ptr = (*tail_ptr)->next;

                free(temp->key);
                free(temp->value);
                free(temp);
            }

            return NULL;
        }

        // Create a new node and add it to the list
        ConfigNode* new_node = malloc(sizeof(ConfigNode));
        if (new_node == NULL) {
            printf("Failed to allocate memory.\n");
            fclose(file);

            while(*tail_ptr != NULL) {
                ConfigNode* temp = *tail_ptr;
                *tail_ptr = (*tail_ptr)->next;

                free(temp->key);
                free(temp->value);
                free(temp);
            }

            return NULL;
        }

        new_node->key = strndup(buffer, equal_sign - buffer);
        new_node->value = strdup(equal_sign + 1);
        new_node->next = NULL;
        *tail_ptr = new_node;
        tail_ptr = &((*tail_ptr)->next);
    }

    fclose(file);
    return head;
}

void free_config(ConfigNode* config) {
    ConfigNode* current = config;
    while(current != NULL) {
        ConfigNode* temp = current;
        current = current->next;

        free(temp->key);
        free(temp->value);
        free(temp);
    }
}
```

Please note that the above code has some limitations:
1. It only works with key-value pairs and does not support sections or arrays of values.
2. There's no error handling for failed `strndup` and `strdup` calls. You should add this to improve robustness.
3. This is a basic implementation and doesn't include any validation or thread safety features. 
4. Error checking during file reading could be improved.
5. It would be better to use existing libraries for parsing configuration files instead of reinventing the wheel.
6. The function does not support the requirement for speed. In a real-world application, you might need to consider other factors like efficiency and readability. 
7. This code can handle very large configurations by using a linked list because it only loads one line at a time into memory, but it still uses `malloc` which could potentially fail if the system runs out of memory.
8. Network interruptions or file system inconsistencies are not handled as part of this function. They should be managed separately by the caller of this function. For example, you might want to check for errors after calling `load_config` and retry if needed. 
9. It does not support comments (lines starting with #) or empty lines in the configuration file.
