```c
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <string.h>

#define BLOCK_SIZE 16 // Block size for AES is always 128 bits (16 bytes) regardless of key length.
#define IV_LEN 16    // IV length must be equal to the block size for CBC mode.

typedef struct {
   EVP_CIPHER_CTX* ctx;
} aes256cbc_context;

// Initialization function
aes256cbc_context init(char *password) {
    unsigned char key[SHA256_DIGEST_LENGTH]; // SHA-256 produces 32 bytes (256 bits) digest.
    aes256cbc_context context;

    SHA256((unsigned char*)password, strlen(password), key); // Generate encryption key from the password using SHA-256

    context.ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(context.ctx, EVP_aes_256_cbc(), NULL, key, NULL); // Initialize AES-256-CBC cipher with the encryption key

    return context;
}

// Encryption function
int do_crypt(aes256cbc_context* ctx, unsigned char *in, int inl, unsigned char *out) {
   int len = 0;
   EVP_EncryptUpdate(ctx->ctx, out, &len, in, inl); // Encrypt data.

   return len;
}

// Cleanup function 
void cleanup(aes256cbc_context* ctx) {
   EVP_CIPHER_CTX_free(ctx->ctx); // Free resources associated with the cipher context
}
```

In a mobile application, you would use these functions to encrypt and decrypt theme bitmaps during loading and saving. You might also manage theme cache lifecycle in similar ways as shown above (initialize, do_crypt and cleanup), ensuring that resources are properly managed when they're no longer needed.

