bool validateSession(const char* jsonStr) {
    json_error_t error;
    json_t *root = json_loads(jsonStr, 0, &error);

    if(!root) {
        // Malformed JSON
        return false;
    }

    json_t *sessionIdJson = json_object_get(root, "session_id");
    json_t *expirationTimeJson = json_object_get(root, "expiration_time");
    json_t *userIdJson = json_object_get(root, "user_id");
    json_t *lastActiveTimeJson = json_object_get(root, "last_active_time");

    // Check if all required fields are present and of correct type
    if(!json_is_string(sessionIdJson) || !json_is_integer(expirationTimeJson) || 
       !json_is_string(userIdJson)) {
        return false;
    }

    // Check for non-empty string userId
    if(strlen(json_string_value(userIdJson)) == 0){
        return false;
    }

    time_t currentTime = time(NULL);
    time_t expirationTime = (time_t) json_integer_value(expirationTimeJson);

    // Check for valid timestamps
    if(currentTime > expirationTime) {
        return false;
    }

    // Check for replay attack condition
    time_t sessionStartTime = expirationTime - SESSION_TIMEOUT;
    if(lastActiveTimeJson && json_is_integer(lastActiveTimeJson)) {
        time_t lastActiveTime = (time_t) json_integer_value(lastActiveTimeJson);

        // Check for valid timestamps
        if(currentTime < sessionStartTime || currentTime < lastActiveTime || lastActiveTime > expirationTime) {
            return false;
        }
    }

    // Additional checks here...

    json_decref(root);
    return true;
}
