        var hashResults = new ConcurrentDictionary<string, string>();

        using (var reader = File.OpenText(filePath))
        {
            string line = null;
            while ((line = await reader.ReadLineAsync()) != null)
            {
                // Validate with remote dictionary service
                if (await _remoteDictService.IsUniqueAsync(line))
                {
                    var hashResult = ComputeMD5Hash(line);
                    hashResults.TryAdd(line, hashResult);
