['Here is an implementation of a C# function that decrypts AES-CBC ciphertext using provided encryption key, IV, HMAC-SHA256 for message authentication, and log errors without exposing sensitive information. Note that this code makes use of the System.Security.Cryptography namespace to perform cryptographic operations.

```csharp
using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using NLog; // Assuming a logger is used, replace with your actual logging library

public class DecryptionService 
{
    private static readonly Logger _logger = LogManager.GetCurrentClassLogger();

    public byte[] Decrypt(byte[] cipherText, byte[] key, byte[] iv, byte[] hmacKey)
    {
        try
        {
            using (var aesCbc = new AesCryptoServiceProvider())
            {
                aesCbc.Mode = CipherMode.CBC;
                aesCbc.Padding = PaddingMode.PKCS7;
                aesCbc.Key = key;
                aesCbc.IV = iv;

                var hmac = new HMACSHA256(hmacKey);

                // Validate the HMAC
                var hashSizeInBytes = hmac.HashSize / 8;
                var cipherTextHmac = cipherText.TakeLast(hashSizeInBytes).ToArray();
                var dataForValidation = cipherText.Take(cipherText.Length - hashSizeInBytes).ToArray();

                if (!hmac.ComputeHash(dataForValidation).SequenceEqual(cipherTextHmac)) 
                {
                    throw new CryptographicException("The message HMAC did not match the decrypted message HMAC.");
                }

                // Decrypt and return plaintext
                using (var decryptor = aesCbc.CreateDecryptor())
                {
                    using (MemoryStream msDecrypt = new MemoryStream(dataForValidation))
                    {
                        using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                        {                            
                            byte[] fromEncrypt = new byte[dataForValidation.Length];
                            var bytesRead = csDecrypt.Read(fromEncrypt, 0, fromEncrypt.Length);
                            return fromEncrypt;
                        }
                    }
                }
            }
        } 
        catch (Exception ex)
        {
            // Log the error without exposing sensitive information
            _logger.Error("An error occurred during decryption: " + ex.Message);
            throw new CryptographicException($"Decryption failed due to an unexpected exception: {ex.Message}");
        }
    }
}
```
This code is designed with performance and resource management in mind, such as the use of the `using` statement for proper disposal of IDisposable objects. It also includes basic error handling, logging of errors without exposing sensitive information, and a HMAC integrity check on the ciphertext before decryption. 

