['```java
import java.io.*;
import java.lang.reflect.Constructor;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class DeserializationUtility {
    private static final Map<String, ClassLoader> cachedClassLoaders = new ConcurrentHashMap<>();

    public static Object deserialize(byte[] data, String className) throws Exception {
        Class<?> clazz = getOrCreateClassloader(className).loadClass(className);

        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return ois.readObject();
        } catch (IOException | ClassNotFoundException ex) {
            throw new DeserializationFailedException("Deserialization failed for class: " + className, ex);
        }
    }

    private static ClassLoader getOrCreateClassloader(String className) throws Exception {
        int dotIndex = className.lastIndexOf('.');

        if (dotIndex == -1) {
            throw new ClassNotFoundException("Invalid class name: " + className);
        }

        String packageName = className.substring(0, dotIndex);
        return cachedClassLoaders.computeIfAbsent(packageName, pkg -> createNewClassLoader(pkg));
    }

    private static ClassLoader createNewClassLoader(String packageName) throws Exception {
        File file = new File(packageName.replace('.', '/'));

        if (!file.exists()) {
            throw new FileNotFoundException("Package does not exist: " + packageName);
        }

        URL[] urls = {file.toURI().toURL()};
        ClassLoader parent = DeserializationUtility.class.getClassLoader();
        return new URLClassLoader(urls, parent);
    }

    public static class DeserializationFailedException extends Exception {
        public DeserializationFailedException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
```
