#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

#define MAX_POOL_SIZE 1024*1024 // Predefined limit for memory pool size

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool createAndInitialize(size_t offsetSize, size_t keySize, size_t recordSize) {
    assert(offsetSize + keySize + recordSize * sizeof(Record) <= MAX_POOL_SIZE); // Ensure the pool is not exceeding its limit

    MemoryPool memory;
    memory.offsets = malloc(offsetSize);
    if (memory.offsets == NULL) exit(1); // Handle allocation failure immediately
    memset(memory.offsets, 0, offsetSize);

    memory.keys = malloc(keySize);
    if (memory.keys == NULL) { free(memory.offsets); exit(2); } // Free partially allocated resources in case of failure
    memset(memory.keys, 0, keySize);

    memory.records = malloc(recordSize * sizeof(Record));
    if (memory.records == NULL) { free(memory.offsets); free(memory.keys); exit(3); } // Free partially allocated resources in case of failure
    memset(memory.records, 0, recordSize * sizeof(Record));

    pthread_mutex_init(&memory.lock, NULL); // Initialize mutex for thread-safe operations

    return memory;
}

void populateWithRandomValues(MemoryPool* memory, size_t recordSize, int lowerBound, int upperBound) {
    assert(memory != NULL);

    pthread_mutex_lock(&memory->lock); // Ensure thread-safe operations
    for (size_t i = 0; i < recordSize; ++i) {
        memory->records[i].value = rand() % (upperBound - lowerBound + 1) + lowerBound; // Thread-safe random number generation
    }
    pthread_mutex_unlock(&memory->lock);
}
```
