    array->capacity = initialCapacity;
    array->sessions = malloc(sizeof(UserSession_t*) * initialCapacity);
    if (array->sessions == NULL) {
        free(array);
        return NULL;
    }

    for (int i = 0; i < array->capacity; ++i) {
        array->sessions[i] = NULL;
    }

    array->size = 0;

    return array;
}

void destroyDynamicArray(DynamicArray_t* array) {
    for (int i = 0; i < array->capacity; ++i) {
        if (array->sessions[i] != NULL) {
            free(array->sessions[i]->sessionCtx);
