#include "external_source.h" // hypothetical library to get initialization data

typedef struct {
    int value;
} Record;

typedef struct Node {
    long offset;
    int key;
    struct Node* next;
} HashNode;

HashNode** hashTable = NULL; 
long TABLE_SIZE = 10007; // a prime number for less collisions 

Record* records = NULL;
long* offsets = NULL;
int* keys = NULL;

// Function to handle initialization from external source 
void initExternalSource() {
    int success = getInitializationData();

    if (success != 0) {
        printf("Failed to initialize from external source\n");
        exit(1); // terminate program if initialization fails
    }
}

// Function to handle memory allocation and error checking 
void allocateAndCheckMemory(void** ptr, size_t size) {
    *ptr = malloc(size);

    if (*ptr == NULL) {
        printf("Failed to allocate memory\n");
        exit(1); // terminate program if allocation fails
    }
}

// Function for hash function 
long getHashKey(int key) {
    return abs(key % TABLE_SIZE);
}

// Function for inserting nodes into the hash table 
void insertIntoHashTable(int key, long offset) {
    HashNode* node = (HashNode*) malloc(sizeof(HashNode));

    assert(node != NULL); // ensure allocation was successful

    node->key = key;
    node->offset = offset;
    node->next = hashTable[getHashKey(key)]; 

    hashTable[getHashKey(key)] = node;
}

// Main function 
void setupAndInitializeRecords(int num_records, int value_range, unsigned int seed) {
    srand(seed); // initialize random number generator with given seed

    initExternalSource();

    // Allocate memory for arrays and structures 
    records = (Record*) malloc(num_records * sizeof(Record));
    offsets = (long*) malloc(num_records * sizeof(long));
    keys = (int*) malloc(num_records * sizeof(int));

    allocateAndCheckMemory((void**) &hashTable, TABLE_SIZE * sizeof(HashNode*)); 

    for (int i = 0; i < num_records; ++i) {
        // Randomly generate 'int' keys within the range 
        keys[i] = rand() % value_range;

        // Generate offsets based on index of records
        offsets[i] = (long) &records[i];

        // Initialize record values with random number from specified range 
        records[i].value = rand() % value_range;

        insertIntoHashTable(keys[i], offsets[i]);
    }
}
```
