['Here is an example solution in C programming language using mutex for locking mechanism and resizing of hash table when load factor exceeds a specific threshold. Please note that this is just a basic outline and should be adapted according to the specific requirements of your use case. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define INITIAL_SIZE 1024
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct Record {
    int key;
    long offset;
    char metadata[64];  // Replace with actual metadata type
} Record;

typedef struct HashTable {
    pthread_mutex_t *locks;
    Record **table;
    size_t capacity, count;
    double loadFactor;
} HashTable;

HashTable* hashTableCreate() {
    HashTable *ht = malloc(sizeof(*ht));
    ht->capacity = INITIAL_SIZE;
    ht->count = 0;
    ht->loadFactor = 0.0;
    ht->table = calloc(INITIAL_SIZE, sizeof(*ht->table));
    ht->locks = malloc(sizeof(*ht->locks) * INITIAL_SIZE);

    for (int i = 0; i < INITIAL_SIZE; ++i) {
        pthread_mutex_init(&ht->locks[i], NULL);
    }

    return ht;
}

size_t hash(int key, size_t capacity) {
    // Simple hash function for demonstration purposes. Replace with a better one in production code.
    return (key % capacity + capacity) % capacity;
}

void resizeHashTableIfNeeded(HashTable *ht) {
    if (ht->loadFactor > LOAD_FACTOR_THRESHOLD) {
        size_t newCapacity = ht->capacity * 2;
        Record **newTable = calloc(newCapacity, sizeof(*newTable));

        // Rehash all records into the new table
        for (size_t i = 0; i < ht->capacity; ++i) {
            pthread_mutex_lock(&ht->locks[i]);

            if (ht->table[i] != NULL) {
                Record *record = ht->table[i];
                size_t newIndex = hash(record->key, newCapacity);

                while (newTable[newIndex] != NULL) {
                    newIndex = (newIndex + 1) % newCapacity;  // Linear probing for collision resolution
                }

                newTable[newIndex] = record;
            }

            pthread_mutex_unlock(&ht->locks[i]);
        }

        free(ht->table);
        ht->table = newTable;
        ht->capacity = newCapacity;
    }
}

void hashTablePut(HashTable *ht, Record *record) {
    size_t index = hash(record->key, ht->capacity);

    pthread_mutex_lock(&ht->locks[index]);

    // Linear probing for collision resolution
    while (ht->table[index] != NULL) {
        index = (index + 1) % ht->capacity;  
    }

    ht->table[index] = record;
    ht->count++;
    ht->loadFactor = ((double)ht->count) / ht->capacity;

    pthread_mutex_unlock(&ht->locks[index]);

    resizeHashTableIfNeeded(ht);  // Resize the table if necessary after insertion
}

Record* hashTableGet(HashTable *ht, int key) {
    size_t index = hash(key, ht->capacity);

    pthread_mutex_lock(&ht->locks[index]);

    while (ht->table[index] != NULL && ht->table[index]->key != key) {
        index = (index + 1) % ht->capacity;  // Linear probing for collision resolution
    }

    Record *record = ht->table[index];

    pthread_mutex_unlock(&ht->locks[index]);

    return record;
}

void hashTableDestroy(HashTable *ht) {
    // Lock all the mutexes before freeing memory to prevent data race conditions
    for (size_t i = 0; i < ht->capacity; ++i) {
        pthread_mutex_lock(&ht->locks[i]);

        if(ht->table[i] != NULL){
            free(ht->table[i]);  // Free the record
        }
    }

    for (size_t i = 0; i < ht->capacity; ++i) {
        pthread_mutex_unlock(&ht->locks[i]);
        pthread_mutex_destroy(&ht->locks[i]);  // Destroy the mutexes
    }

    free(ht->table);  
    free(ht->locks); 
    free(ht);  
}
```
In this solution, a hash table with separate locks for each slot of the table is used to prevent lock contention during concurrent read and write operations. This allows multiple threads to operate on different slots in parallel while still ensuring thread safety for accessing individual records. Resizing of the hash table is handled when the load factor exceeds a certain threshold, which prevents performance degradation due to frequent rehashing. 

Please note that this code snippet does not include proper error handling and assumes valid input parameters. It should be adapted according to your specific needs in terms of thread safety, memory management, resizing mechanism, data skew handling, performance constraints, resource cleanup, edge cases handling etc.
']

