void manage_memory(long **offsets, int **keys, record **records, int num_records, int min_value, int max_value, bool unique) {
    srand(time(NULL));

    *offsets = malloc(num_records * sizeof(long));
    if (*offsets == NULL) {
        return;
    }

    *keys = malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return;
    }

    *records = malloc(num_records * sizeof(record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return;
    }

    for (int i = 0; i < num_records; i++) {
        int val = min_value + rand() % (max_value - min_value + 1);

        if(unique){
            while(contains(*keys, val, i)){
                val = min_value + rand() % (max_value - min_value + 1);
            }
        }

        (*keys)[i] = val;
        (*records)[i].value = val;
    }
}

bool contains(int *array, int value, int size){
