typedef struct node {
    char *str;
    int num;
    struct node *next;
} Node;

// Create an array of long integers and a linked list of nodes
long* long_array;
Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int array_size = 0;

// Function to add node at the end of the linked list in a thread-safe way
void insert_node(char* str, int num) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->str = strdup(str);
    newNode->num = num;
    newNode->next = NULL;

    if (head == NULL) {
        head = newNode;
    } else {
        Node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}

// Function to delete node from a linked list in a thread-safe way
void delete_node(char* str) {
    pthread_mutex_lock(&lock);

    Node *temp = head, *prev;

    if (temp != NULL && strcmp(temp->str, str) == 0) {
        head = temp->next;  
        free(temp->str);
        free(temp);            
        return;
    }

    while (temp != NULL && strcmp(temp->str, str) != 0) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // Node not found

    prev->next = temp->next;
    free(temp->str);
    free(temp); 

    pthread_mutex_unlock(&lock);
}
```

