#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Your UserIdentifier_t definition goes here...
} UserIdentifier_t;

typedef struct {
    // Your SessionContext_t definition goes here...
} SessionContext_t;

typedef struct {
    UserIdentifier_t userId;
    SessionContext_t sessionCtx;
} UserSession;

// An Array of UserSessions and its size
UserSession* sessions = NULL;
size_t sessionSize = 0, sessionCapacity = 0;
pthread_mutex_t mutex;

int initArray() {
    pthread_mutex_init(&mutex, NULL);
    return 0; // Returns 0 on success. Error handling not implemented for simplicity.
}

// Assuming UserIdentifier_t and SessionContext_t are structs with known size.
void addSession(UserIdentifier_t userId, SessionContext_t sessionCtx) {
    pthread_mutex_lock(&mutex);
    if (sessionSize >= sessionCapacity) {
        // If array is full, reallocate a new one with double the capacity.
        sessionCapacity = sessionCapacity ? 2 * sessionCapacity : 1;
        sessions = realloc(sessions, sizeof(*sessions) * sessionCapacity);
    }

    // Add the session at the end of array and increment size.
    sessions[sessionSize].userId = userId;
    sessions[sessionSize].sessionCtx = sessionCtx;
    sessionSize++;

    pthread_mutex_unlock(&mutex);
}

// Remove a session using its index. Assumes valid index and no other threads are modifying the array concurrently.
void removeSession(size_t index) {
    // To protect against potential race conditions, lock the mutex before proceeding with removal.
    pthread_mutex_lock(&mutex);

    if (index < sessionSize - 1) {
        // Move last element to current position.
        sessions[index] = sessions[sessionSize - 1];
    }

    // Decrement the size.
    sessionSize--;

    pthread_mutex_unlock(&mutex);
}

// Update a session using its index and new userId and sessionCtx. Assumes valid index and no other threads are modifying the array concurrently.
void updateSession(size_t index, UserIdentifier_t userId, SessionContext_t sessionCtx) {
    pthread_mutex_lock(&mutex);

    if (index < sessionSize) {
        // Update the session at given index.
        sessions[index].userId = userId;
        sessions[index].sessionCtx = sessionCtx;
    }

    pthread_mutex_unlock(&mutex);
}
```

