typedef struct {
    int value;
    char* buffer;
} Record;

void init_memory(long* offsets, long num_offsets, long offset_base, long max_offset, 
                 int* keys, long key_multiplier, 
                 Record** records, size_t num_records, size_t buffer_size, 
                 int min_value, int max_value) {
    srand(time(0)); // seed the random number generator

    offsets = malloc(num_offsets * sizeof(*offsets));
    if (offsets == NULL) exit(-1);

    for (long i = 0; i < num_offsets && offset_base <= max_offset; ++i, ++offset_base) {
        offsets[i] = offset_base;
    }

    keys = malloc(num_offsets * sizeof(*keys));
    if (keys == NULL) exit(-1);

    for (long i = 0; i < num_offsets; ++i) {
        long tmp = offsets[i] * key_multiplier;
        // check for overflow
        if (tmp > INT_MAX || tmp < INT_MIN) exit(-1);

        keys[i] = (int) tmp;
    }

    records = malloc(num_records * sizeof(*records));
    if (records == NULL) exit(-1);

    for (size_t i = 0; i < num_records; ++i) {
        Record* record = malloc(sizeof(*record));
        if (record == NULL) exit(-1);

        // allocate buffer + 1 char for \0
        record->buffer = malloc((buffer_size+1)* sizeof(*(record->buffer)));
