Please note that this is just a simplified example, actual implementation would be more complex depending on the requirements such as handling network latency, managing multiple logging backends, unit testing, etc.

```cpp
#include <boost/log/trivial.hpp>
#include <boost/log/sources/severity_logger.hpp>
#include <boost/log/utility/setup/file.hpp>
#include <memory>
#include <mutex>

namespace LoggingFramework {
    class LogManager;
    std::shared_ptr<LogManager> getInstance(); // Singleton accessor

    class LogManager {
        private:
            boost::log::sources::severity_logger<boost::log::trivial::severity_level> logger_;

            // Private constructor, destructor and copy/move operators to prevent copying and moving instances.
            LogManager() { /* Initialize Boost.Log here */ } 
            ~LogManager() { /* Clean up resources */ }
            LogManager(const LogManager&) = delete;
            LogManager(LogManager&&) = delete;
            LogManager& operator=(const LogManager&) = delete;
            LogManager& operator=(LogManager&&) = delete;

            // Thread-safe access to logger_
            void logInfo(std::string message);
            void logWarning(std::string message);
            void logError(std::string message);

        friend std::shared_ptr<LogManager> getInstance();
    };

    // Singleton instance of LogManager.
    inline static std::weak_ptr<LogManager> g_pLogManager;
    inline static std::mutex mtx_; 

    std::shared_ptr<LogManager> getInstance() {
        auto p = g_pLogManager.lock();

        if (!p) {
            std::lock_guard<std::mutex> lock(mtx_);

            // Recheck after acquiring the mutex to ensure another thread didn't create an instance before we did.
            p = g_pLogManager.lock(); 

            if (!p) {
                // Create a new instance and store it in a shared_ptr that is held by the weak_ptr.
                p.reset(new LogManager());
                g_pLogManager = p;
            }
        }

        return p; 
    }
}
```

This code creates a `LoggingFramework::LogManager` class with three logging levels: info, warning and error. The logger is managed as a singleton to ensure that only one instance of it exists across the application. When the `getInstance()` function is called for the first time, it will create an instance of `LogManager`; all subsequent calls will return this same instance.
"]

