record_entry* init_data(unsigned long num_records, double min_value, 
                        double max_value, size_t buffer_size, unsigned long identifier_base) {

    srand((unsigned int) time(NULL)); // for random generation of values

    record_entry* records = (record_entry*) malloc(num_records * sizeof(record_entry));
    if (!records) return NULL;

    unsigned long* identifiers = (unsigned long*) malloc(num_records * sizeof(unsigned long));
    if (!identifiers) {
        free(records);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {

        identifiers[i] = identifier_base + i;

        double randValue = ((double)rand() / RAND_MAX) * (max_value - min_value) + min_value;

        records[i].type = i; // considering level as index for now, can be modified based on use case
        records[i].value = randValue;

        char* descriptionBuffer = malloc(buffer_size);
        if (!descriptionBuffer) {
            free(identifiers);
            free(records);
            return NULL; // not enough memory for a single record's description
        } 

        size_t descLength = rand() % (buffer_size - 1); // generate random length less than buffer_size
        for (size_t j = 0; j < descLength; ++j) {
            descriptionBuffer[j] = 'a' + rand() % 26; // generating a-z characters
        }

        descriptionBuffer[descLength] = '\0'; // null terminator is not required, so not included in length calculation

        records[i].description = descriptionBuffer;
        records[i].identifier = identifiers[i];
    }

    free(identifiers);

