void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJK...";
    if (length > 0) {
        --length;
        for (size_t n = 0; n < length; ++n) {
            int key = rand() % (int) (sizeof charset - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    }
}

void generate_secure_random(int *num, int min, int max) {
    if (min < max) {
        *num = min + rand() % ((max + 1) - min);
    } else {
        fprintf(stderr, "Invalid secure random range\n");
        exit(EXIT_FAILURE);
    }
}

void manage_memory_allocation(size_t length) {
    long *offsets = safe_malloc(length * sizeof(*offsets));
    int *keys = safe_malloc(length * sizeof(*keys));
    record *records = safe_malloc(length * sizeof(*records));

    srand((unsigned int) time(NULL)); // Seed the random number generator

    char str[256];
    generate_random_string(str, 10);

    for (size_t i = 0; i < length; ++i) {
        offsets[i] = rand();
        keys[i] = rand();
        generate_secure_random(&records[i].value, 0, 100);
    }

    // Free memory
    free(offsets);
    free(keys);
    free(records);
}
