```java
import java.io.*;
import java.security.*;
import java.util.*;

class Record {
    int value;
    double timestamp;
    String content;
}

public class Main {

    public static void main(String[] args) {
        // Test with example values
        initializeAndHashRecords(5, "test.txt", 10, true);
    }

    public static Object[] initializeAndHashRecords(int numOfRecords, String filename, int range, boolean optimizeSpeed) {

        List<Record> records = new ArrayList<>();
        MessageDigest md;
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e1) {
            System.out.println("Failed to create MD5 instance.");
            return null; // Handle error gracefully
        }

        File file = new File(filename);
        try (Scanner scanner = new Scanner(file)) {

            Random rand = new Random();
            for(int i=0; i<numOfRecords; i++) {
                Record record = new Record();

                if(!optimizeSpeed && i % 100 == 0) { // only read from file every 100 records to save memory
                    while (scanner.hasNextLine()) {
                        String data = scanner.nextLine();
                        md.update(data.getBytes());

                        record.content = data;
                        break;
                    }
                } else { // read from file for every record to save time
                    while (scanner.hasNextLine()) {
                        String data = scanner.nextLine();
                        md.update(data.getBytes());

                        record.content = data;
                        break;
                    }
                }

                record.value = rand.nextInt(range);
                record.timestamp = System.currentTimeMillis();
                records.add(record);
            }

        } catch (FileNotFoundException e) {
            System.out.println("File not found: " + filename);
            return null; // Handle error gracefully
        }

        byte[] digest = md.digest();
        StringBuilder sb = new StringBuilder();
        for(byte b : digest) {
           sb.append(String.format("%02x", b & 0xff));
        }

        return new Object[]{records, sb.toString()};
    }
}
```
In the code above:
- `Record` is a class representing a record as per your requirement.
- The function tries to read each line from the file for every 100 records when optimization for speed is requested, otherwise it reads from the file for every record to save time.
- It computes an MD5 hash of the input string (which was supposed to be contents of a file in your description) and stores the result as `digest`.
- Finally, it returns both the list of records and the computed MD5 hash.
