int get_ip(char* hostname, int af) { //af = AF_INET for IPv4 and AF_INET6 for IPv6 
    struct in6_addr addr6;
    struct in_addr addr;
    u_char *buffer = malloc(sizeof(u_char)*256);

    if (inet_pton(af, hostname, &addr) == 1) { //ipv4
        buffer = inet_ntop(AF_INET, &addr, buffer, 256);
    } else if (inet_pton(af, hostname, &addr6) == 1) { //ipv6
        buffer = inet_ntop(AF_INET6, &addr6, buffer, 256);
    } else {
