```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void processFileLineByLine() {
    FILE *file = fopen("data.txt", "r");
    if (file == NULL) {
        printf("Could not open file\n");
        return;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        line[strcspn(line, "\r\n")] = 0; // Remove newlines

        char *token = strtok(line, ",");
        int sum = 0, count = 0;

        while (token != NULL) {
            sum += atoi(token);
            token = strtok(NULL, ",");
            count++;
        }

        double average = (double)sum / (double)(count == 0 ? 1 : count);
        printf("Average of line: %f\n", average);
    }

    free(line);
    fclose(file);
}
```
