#include <stdlib.h>
#include <stdatomic.h>
#include <openssl/rand.h>
#include <string.h>
#include <assert.h>

typedef struct record {
    int value;
} Record;

typedef struct array {
    _Atomic size_t size;
    _Atomic size_t capacity;
    long* offsets;
    int* keys;
    Record* records;
} Array;

void resize(Array *array, size_t newCapacity) {
    // Resize operation is not thread-safe in this example.
    // Consider using lock-free data structures for a real world application
    long* newOffsets = malloc(sizeof(long) * newCapacity);
    int* newKeys = calloc(newCapacity, sizeof(int));
    Record* newRecords = calloc(newCapacity, sizeof(Record));

    memcpy(newOffsets, array->offsets, array->capacity * sizeof(long));
    memcpy(newKeys, array->keys, array->capacity * sizeof(int));
    memcpy(newRecords, array->records, array->capacity * sizeof(Record));

    free(array->offsets);
    free(array->keys);
    free(array->records);

    array->offsets = newOffsets;
    array->keys = newKeys;
    array->records = newRecords;
    atomic_store(&array->capacity, newCapacity);
}

int generateRandom(int lowerBound, int upperBound) {
    unsigned char randomValue[sizeof(int)];
    RAND_bytes(randomValue, sizeof(int));

    // Map the random bytes to the desired range
    int value = *((int*)randomValue);
    if (value < 0) 
        value = -value;

    return lowerBound + (value % (upperBound - lowerBound + 1));
}

void allocateAndInit(Array* array, size_t initialCapacity) {
    atomic_init(&array->size, 0);
    atomic_init(&array->capacity, initialCapacity);

    array->offsets = malloc(sizeof(long) * initialCapacity);
    if (array->offsets == NULL) {
        perror("Failed to allocate offsets");
        exit(EXIT_FAILURE);
    }

    array->keys = calloc(initialCapacity, sizeof(int));
    if (array->keys == NULL) {
        free(array->offsets);
        perror("Failed to allocate keys");
        exit(EXIT_FAILURE);
    }

    array->records = calloc(initialCapacity, sizeof(Record));
    if (array->records == NULL) {
        free(array->offsets);
        free(array->keys);
        perror("Failed to allocate records");
        exit(EXIT_FAILURE);
    }
}
