    InventoryNode* newNode = malloc(sizeof(InventoryNode));  // Allocate memory for a new node.
    newNode->product.id = id;                               // Set the product details.
    newNode->product.quantity = quantity;
    newNode->product.supplierInfo = supplierInfo;          // Copy the supplier info pointer.
    newNode->next = invList->head;                          // Link this node to the current head of the list.

    invList->head = newNode;                                 // Set the head of the list to the new node.

    pthread_mutex_unlock(&invList->lock);  // Release the lock.
}
