int validateMacAddress(const char* mac) {
    if (strlen(mac) != 17) { return 0; }

    for(int i = 0; i < 17; i++) {
        if ((i+1)%3 == 0 && mac[i] != ':') { return 0; }
        else if ((i+1)%3 != 0 && (mac[i] < '0' || mac[i] > '9')) { return 0; }
    }

    return 1;
}

// Populate a MAC_PDU with fake data for simplicity.
