    pdu.pdu.data = malloc(sizeof(char) * 20);
    strcpy(pdu.pdu.data, "Fake Data");
    // ... other fields...

    return pdu;
}

// Initialize and populate a list of MAC_PDU structures.
NetworkData init_and_populate() {
    int count = 10;  // Change as needed for the actual number of networks
    NetworkData data;
    data.networks = malloc(sizeof(MAC_PDU*) * count);

    clock_t start, end;
    double cpu_time_used;

    start = clock();
    for (int i = 0; i < count; i++) {
        data.networks[i] = malloc(sizeof(MAC_PDU));
        *data.networks[i] = initMacPdu();

        // Validate MAC address, assuming each network has a unique MAC address for simplicity.
        if (!validateMacAddress((*data.networks[i]).bssid)) { 
            printf("Invalid MAC Address\n"); 
            continue;
        }
    }
    end = clock();

    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken: %f seconds\n", cpu_time_used);

    data.count = count;  // Update as needed for actual number of validated networks

    return data;
}
