typedef struct {
    double d;
    int i;
    char *str;
} DataStruct;

DataStruct* read_data(const char *filename, size_t count, int min, int max) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    // Allocate memory for the struct array and initialize each struct element.
    DataStruct* data = malloc(count * sizeof(DataStruct));
    if (!data) {
        perror("Memory allocation error");
        fclose(file);
        return NULL;
    }

    srand((unsigned int) time(NULL));

    char buffer[1024]; // Assuming the longest string is less than 1024 characters.

    for (size_t i = 0; i < count; ++i) {
        if (!fgets(buffer, sizeof(buffer), file)) {
            perror("Failed to read from file");
            // Free previously allocated memory in case of failure.
            for (size_t j = 0; j < i; ++j)
                free(data[j].str);
            free(data);
            fclose(file);
            return NULL;
        }

        data[i].d = ((double)rand() / RAND_MAX) * (max - min) + min; // Random double value.
        data[i].i = rand() % (max - min + 1) + min; // Random int value.

        size_t strlen = strlen(buffer);
        if (buffer[strlen - 1] == '\n') // Remove the newline character, if present.
            buffer[--strlen] = '\0';

        data[i].str = malloc((strlen + 1) * sizeof(char)); // Allocate memory for string and copy it.
        if (!data[i].str) {
            perror("Memory allocation error");
            // Free previously allocated memory in case of failure.
            for (size_t j = 0; j < i; ++j)
                free(data[j].str);
            free(data);
            fclose(file);
            return NULL;
        }

        strcpy(data[i].str, buffer);
    }

    fclose(file);
    return data;
}
``` 
