IntStream* createStream() {
    IntStream* stream = malloc(sizeof(IntStream));
    if (stream == NULL) {
        return NULL;
    }

    stream->len = 0;
    stream->capacity = 16;
    stream->data = malloc(stream->capacity * sizeof(int));
    if (stream->data == NULL) {
        free(stream);
        return NULL;
    }

    return stream;
}

void destroyStream(IntStream* stream) {
    pthread_mutex_lock(&lock);
    free(stream->data);
    free(stream);
    pthread_mutex_unlock(&lock);
}

int pushToStream(IntStream* stream, int value) {
    pthread_mutex_lock(&lock);

    if (stream->len == stream->capacity) {
        size_t newCapacity = stream->capacity * 2;
        int* newData = realloc(stream->data, newCapacity * sizeof(int));
        if (newData == NULL) {
            pthread_mutex_unlock(&lock);
            return -ENOMEM;
        }

        stream->capacity = newCapacity;
        stream->data = newData;
    }

    stream->data[stream->len++] = value;

    pthread_mutex_unlock(&lock);
    return 0;
}

int findMax(IntStream* stream, int *result) {
    if (pthread_mutex_trylock(&lock) != 0) {
        return -EBUSY;
    }

    if (stream->len == 0) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    *result = stream->data[0];
    for(size_t i = 1; i < stream->len; ++i) {
        if (stream->data[i] > *result) {
            *result = stream->data[i];
        }
    }

    pthread_mutex_unlock(&lock);
    return 0;
}
```
