```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char MAC[17];
} MAC_PDU;

typedef struct Node{
    MAC_PDU data;
    int count;
    struct Node* next;
}Node;

// Cache structure
Node *head = NULL, *tail = NULL;
pthread_mutex_t lock;
int maxCacheSize = 1000;  // adjust this according to your needs

void addToCache(MAC_PDU data){
    if(maxCacheSize == 0) return;

    pthread_mutex_lock(&lock);
    Node* temp = (Node*)malloc(sizeof(Node));
    temp->data = data;
    temp->count = 1;
    temp->next = NULL;

    if(!head) head = tail = temp;
    else{
        tail->next = temp;
        tail = temp;

        // If cache is full, remove the oldest node (FIFO style)
        if(tail->count > maxCacheSize){
            Node* toRemove = head;
            head = head->next;
            free(toRemove);
        }
    }
    pthread_mutex_unlock(&lock);
}

int checkInCache(MAC_PDU data){
    if(!head) return -1;

    Node* temp = head;
    while(temp){
        if(strcmp(temp->data.MAC, data.MAC) == 0) 
            return temp->count;

        temp = temp->next;
    }
    return -1;
}

// Function to validate MAC and add it into cache or update its count
void processAndCache(MAC_PDU pdu){
    int timesSeen = checkInCache(pdu);

    if(timesSeen != -1) {  // Already exists in cache, just increment the counter
        Node* temp = head;

        while(temp){
            if(strcmp(temp->data.MAC, pdu.MAC) == 0){
                temp->count++;
                break;
            }
            temp = temp->next;
        }
    } else {  // Not in cache yet, add it
        addToCache(pdu);
    }
}

void *populate_MACs(){
    MAC_PDU mac_data;

    clock_t begin = clock();

    // Populating the list with valid MAC addresses here (simplified example)
    for(int i = 0; i < 100000; i++){
        sprintf(mac_data.MAC, "%x:%x:%x:%x:%x:%x", rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        processAndCache(mac_data);
    }

    clock_t end = clock();
    double timeSpent = (double)(end - begin) / CLOCKS_PER_SEC;
    printf("Time taken: %.3f seconds\n", timeSpent);
}
```
