void manageArray(int numStructures) {
    pthread_mutex_lock(&lock);

    if (numStructures > arraySize) {
        // Extend the array
        NFAPI_CRC_INDICATION_PDU_T **newArray = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * numStructures);
        if (newArray == NULL) {
            // Log and handle error here
            pthread_mutex_unlock(&lock);
            return;
        }

        array = newArray;
        for (size_t i = arraySize; i < numStructures; ++i) {
            array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            // Randomly set CRCFLAG
            srand(time(NULL));
            array[i]->crcTag.CRCFLAG = rand() % 2;
        }

        arraySize = numStructures;
    } else if (numStructures < arraySize) {
        // Shrink the array
        for (size_t i = numStructures; i < arraySize; ++i) {
            free(array[i]);
        }

        NFAPI_CRC_INDICATION_PDU_T **newArray = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * numStructures);
        if (newArray == NULL) {
            // Log and handle error here
            pthread_mutex_unlock(&lock);
            return;
        }

        array = newArray;
        arraySize = numStructures;
    }

