    if(head == NULL) {
        head = newNode;   // If the linked list is empty, make this node as first node.
    } else {
        Node *temp = head;  // Iterate through the list and add new node at end.
        while(temp->next != NULL) {
            temp = temp->next;  
        }
        temp->next = newNode;
    }

    pthread_mutex_unlock(&lock);  // Unlocking mutex after operation is done.
