    double *vectorDouble;
    char **vectorChar;
    Node **vectorNode;
} VectorData;

VectorData allocateAndInitialize(int sizeVecDouble, int sizeVecChar, int sizeVecNode) {
    // Allocating memory and initializing three vectors
    VectorData data = malloc(sizeof(VectorData));

    if (!data) {
        printf("Memory allocation failed for vector of doubles");
        exit(-1);
    }
    data->vectorDouble = calloc(sizeVecDouble, sizeof(double));
    data->vectorChar = malloc(sizeof(char*) * sizeVecChar);
    if (!data->vectorChar) {
        printf("Memory allocation failed for vector of char*");
        free(data->vectorDouble);
        free(data);
        exit(-1);
    }

    data->vectorNode = malloc(sizeof(Node*) * sizeVecNode);
    if (!data->vectorNode) {
        printf("Memory allocation failed for vector of Node*");
        free(data->vectorDouble);
        free(data->vectorChar);
        free(data);
        exit(-1);
    }

    // Initialize linked list in the node pointer vector
    int i;
    for (i = 0; i < sizeVecNode - 1; ++i) {
        data->vectorNode[i] = malloc(sizeof(Node));
        if (!data->vectorNode[i]) {
            printf("Memory allocation failed for Node");

            // Free allocated nodes in vectorNode
            int j;
            for (j = 0; j < i; ++j) {
                free(data->vectorNode[j]);
            }

            // Clean up and exit
            free(data->vectorDouble);
            free(data->vectorChar);
            free(data->vectorNode);
            free(data);
            exit(-1);
        }

        data->vectorNode[i]->next = data->vectorNode[i+1];
    }

    // Make the last node point to null
    data->vectorNode[sizeVecNode - 1] = NULL;

    return data;
}
```
This function allocates memory for and initializes three vectors: a vector of double precision floating-point numbers, a vector of character strings, and a vector of struct Node pointers. The last two vectors are initialized as linked list structures where each node points to the next one and the end is marked with a null pointer.
