    int key;
    Record record;
    struct hash_node_t *next;
} HashNode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
HashNode **hashTable;
int size; // Size of hash table

// Initializes a record with a random value within a range.
void initRecord(Record *record, int min, int max) {
    srand(time(NULL));
    record->value = rand() % (max - min + 1) + min;
}

// Hashing function for keys. Simple and not perfect but good enough for demonstration purposes.
int hashFunction(int key) {
    return abs(key) % size;
}

// Inserts a node into the hash table, with locking to ensure thread-safety.
void insertNode(long offset, int key, Record record) {
    HashNode *node = malloc(sizeof(HashNode));
    node->offset = offset;
    node->key = key;
    node->record = record;

    pthread_mutex_lock(&lock);
    int index = hashFunction(key);
    node->next = hashTable[index];
    hashTable[index] = node;
    pthread_mutex_unlock(&lock);
}

// Searches for a node in the hash table, with locking to ensure thread-safety.
HashNode* searchNode(int key) {
    pthread_mutex_lock(&lock);
    int index = hashFunction(key);
    HashNode *node = hashTable[index];

    while (node != NULL && node->key != key) {
        node = node->next;
    }

    pthread_mutex_unlock(&lock);
    return node;
}
