        return -1;
    }

    return 0;
}

Record* createRecords(size_t recordSize, int lowerLimit, int upperLimit) {
    Record *records = (Record*)malloc(sizeof(Record) * recordSize);

    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        return NULL;
    }

    for (size_t i = 0; i < recordSize; ++i) {
        records[i].integer = lowerLimit + rand() % ((upperLimit + 1) - lowerLimit);  // Set random integer value

        snprintf(records[i].string, MAX_STRING, "Record #%zu", i + 1);  // Set custom string

        records[i].decimal = (double*)malloc(sizeof(double));  // Dynamically allocate memory for decimal value
        *(records[i].decimal) = 0.0;  // Initialize double value
