["Here's a basic implementation that should accomplish most requirements in Node.js environment using async/await for asynchronous programming. Note this is not a complete solution but just an example to give you an idea of how to approach such task:

```javascript
const fs = require('fs').promises;
const path = require('path');
let stats = {
    filesProcessed: 0,
    validUsers: 0,
    invalidUsers: 0,
    warnings: [],
};

async function processFiles(dir) {
    const files = await fs.readdir(dir);

    for (let file of files) {
        if (!file.endsWith('.json')) {
            console.warn('Skipping file with non-JSON extension:', file);
            continue;
        }

        stats.filesProcessed++;
        let data = await fs.readFile(path.join(dir, file), 'utf8');
        try {
            const user = JSON.parse(data);

            // Validate required fields and handle missing ones
            if (!user.name || !user.age || !user.email) {
                console.warn('Invalid user object in', file, ': Missing one or more fields');
                stats.invalidUsers++;

                // Assign default values here (or as per your requirements)
                if(!user.name) user.name = 'default name';
                if(!user.age) user.age = 0;
                if(!user.email) user.email = 'example@domain.com';

            } else {
                stats.validUsers++;
            }

            users.push(user);
        } catch (error) {
            console.warn('Error parsing JSON object in', file, ':', error);
            stats.invalidUsers++;
        }
    }

    users.sort((a, b) => a.age - b.age); // Sort by age

    return {users, stats};
}
```
This script reads all the files in a directory and processes each one with JSON content. It skips files without `.json` extension, logs warnings for invalid user objects and missing fields, assigns default values where necessary, sorts users by age and returns an object containing processed users and statistics of processing. 

