void initRecords(Record*** records, long** offsets, int* keys, size_t num_records) {
    srand(time(NULL));

    *records = malloc(num_records * sizeof(Record*));
    *offsets = malloc((num_records + 1) * sizeof(long));

    int totalStrLen = 0;

    for (int i = 0; i < num_records; i++) {
        (*records)[i] = malloc(sizeof(Record));
        (*offsets)[i] = totalStrLen;

        if ((totalStrLen += keys[i]) > 5000) {
            freeRecords(*records, *offsets);
            return initRecords(records, offsets, keys, num_records);  // retry allocation
        }

        (*records)[i]->value = rand() % INT_MAX;

        (*records)[i]->str = malloc((keys[i] + 1) * sizeof(char));
        memset((*records)[i]->str, 'a', keys[i]);  // fill with dummy data
