        // Initialize mutex for thread safety
        pthread_mutex_init(&collection[i].mutex, NULL);
    }

    return collection;
}

// Function to update a record's value based on index and new value
void update_record(CollectionRecord* collection, size_t index, int newValue) {
    if (index >= sizeof(collection)/sizeof(CollectionRecord)) {
        // Handle error: Index out of bounds
        return;
