    long offset;
    struct Entry* next; // handle collisions with separate chaining
} Entry;

Entry** hashTable = NULL; // global hash table
pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER; // reader/writer lock
long* offsets;
int* keys;
Record* records;
extern void writeToDisk(void* data, size_t len); 
extern void readFromDisk(void* data, size_t len);
extern int hash(int key);

void initHashTable() {
    srand((unsigned)time(NULL));
    offsets = malloc(SIZE * sizeof(long));
    keys = malloc(SIZE * sizeof(int));
    records = malloc(SIZE * sizeof(Record));

    // Initialize hash table and entries
    hashTable = calloc(SIZE, sizeof(Entry*)); 

    for (int i = 0; i < SIZE; ++i) {
        offsets[i] = rand() % RANGE_END + RANGE_START;
        keys[i] = rand(); // random key

        // Initialize records and hash table
        records[i].value = rand(); 
        int index = hash(keys[i]); 

        pthread_rwlock_wrlock(&lock); // acquire writer lock to safely write to shared data
        Entry* entry = malloc(sizeof(Entry));
        entry->offset = offsets[i];
        entry->next = hashTable[index]; // add at beginning of linked list
        hashTable[index] = entry;
        pthread_rwlock_unlock(&lock); // release writer lock
    }
}

void freeMemory() {
    for (int i = 0; i < SIZE; ++i) {
        Entry* current = hashTable[i];

        while(current != NULL) {
            Entry* temp = current->next;
            free(current);
            current = temp;
        }
    }

    free(hashTable); 
    free(offsets); 
    free(keys); 
    free(records);
}
```
Please note that this is a simplified code snippet and would require more complete implementation to handle intermittent network failures, logging, memory management optimizations for large datasets and concurrent access, among other things. This code also uses a naive hash function which may not provide optimal performance with real-world data.
