```c
#include <stdio.h>
#include <string.h>
#include <json-c/json.h>
#include <sys/resource.h>

typedef struct {
    int buffer_size;
    int thread_pool_size;
    double cpu_threshold;
    double memory_threshold;
} Config;

Config parseJson(char* jsonStr) {
    Config config = {0};

    json_object *jobj = json_tokener_parse(jsonStr);
    json_object *jbuffer, *jthreads, *jcpu, *jmemory; 

    json_object_object_get_ex(jobj, "buffer_size", &jbuffer);
    json_object_object_get_ex(jobj, "thread_pool_size", &jthreads);
    json_object_object_get_ex(jobj, "cpu_threshold", &jcpu);
    json_object_object_get_ex(jobj, "memory_threshold", &jmemory);

    config.buffer_size = json_object_get_int(jbuffer);
    config.thread_pool_size = json_object_get_int(jthreads);
    config.cpu_threshold = json_object_get_double(jcpu);
    config.memory_threshold = json_object_get_double(jmemory);

    return config;
}

void adjustConfig(Config* config) {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);

    double cpuUsage = 100 - (usage.ru_idle / (double)(usage.ru_idle + usage.ru_utime));
    double memoryUsage = (usage.ru_maxrss / (double)1024/1024); // convert to MB

    if(cpuUsage > config->cpu_threshold) {
        config->buffer_size *= 2;
    }

    if(memoryUsage > config->memory_threshold) {
        config->thread_pool_size++;
    }
}

int main() {
    // Load JSON from a file, server or wherever you get it.
    char* jsonStr = "{...}"; 

    Config config = parseJson(jsonStr);
    adjustConfig(&config);

    printf("Buffer size: %d\n", config.buffer_size);
    printf("Thread pool size: %d\n", config.thread_pool_size);
}
```
This is a very simplified example and doesn't include many of the considerations you asked for, such as network programming, error handling, thread synchronization etc. Developers are encouraged to study C and JSON parsing libraries in depth before attempting this or similar projects.
