UserProfile** profiles = NULL; // Hash table for profiles
int profileCount = 0; // Number of profiles in the table
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

unsigned long hash(char* str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % MAX_PROFILES; // Modulus to fit into table
}

UserProfile* get_profile(char* user) {
    unsigned long index = hash(user);

    while (profiles[index] != NULL && strcmp(profiles[index]->user, "") != 0) {
        if (strcmp(profiles[index]->user, user) == 0) 
            return profiles[index]; // If user found, return profile
        ++index;
        index %= MAX_PROFILES; // Wrap around to start of array if necessary
    }

    return NULL; // User not in table
}

void add_profile(UserProfile* profile) {
    unsigned long index = hash(profile->user);

    while (profiles[index] != NULL && strcmp(profiles[index]->user, "") != 0) {
        if (strcmp(profiles[index]->user, profile->user) == 0) 
            return; // User already in table
        ++index;
        index %= MAX_PROFILES; // Wrap around to start of array if necessary
    }

    profiles[index] = profile;
}

void remove_profile(UserProfile* profile) {
    unsigned long index = hash(profile->user);

    while (profiles[index] != NULL) {
        if (strcmp(profiles[index]->user, profile->user) == 0) {
            free(profiles[index]); // Free memory for the profile
            profiles[index] = NULL;
            return;
        }
        ++index;
        index %= MAX_PROFILES; // Wrap around to start of array if necessary
    }
}
