```java
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.math.BigInteger;
import java.security.NoSuchAlgorithmException;
import org.apache.commons.lang3.StringUtils;

public class StreamProcessor {
    private static final String DEFAULT_HASHING_ALGORITHM = "MD5";
    private ExecutorService executorService;

    public StreamProcessor(int threadCount) {
        this.executorService = Executors.newFixedThreadPool(threadCount);
    }

    public void processStream(Iterable<String> stream, String salt) {
        for (String str : stream) {
            executorService.execute(() -> 
                    System.out.println(createHashWithSalt(str, DEFAULT_HASHING_ALGORITHM, salt)));
        }
    }

    private String createHashWithSalt(String originalString, String algorithm, String salt) {
        try {
            MessageDigest md = MessageDigest.getInstance(algorithm);
            byte[] digest = md.digest((originalString + salt).getBytes(StandardCharsets.UTF_8));
            return String.format("%032x", new BigInteger(1, digest));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalArgumentException("Invalid hashing algorithm: " + algorithm);
        }
    }

    public void close() {
        executorService.shutdown();
    }
}
```
This code creates a simple stream processor that processes an input string and prints out the MD5 hash for each one. It uses an ExecutorService to handle concurrency, which is appropriate when dealing with large amounts of data.

