    }
    arr->items[arr->used++] = element;
}

void freeArray(DynamicArray* arr) {
    for (size_t i = 0; i < arr->used; ++i) {
        free(arr->items[i].description);
    }
    free(arr->items);
    arr->items = NULL;
}
```
In the above code, `init` function is used to initialize a dynamic array with a certain initial size. The `insert` function inserts an element into the dynamic array. It resizes the array if there's no space available. The `freeArray` function frees memory allocated for the dynamic array.
