```c
#include <tiffio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint16 bitsPerSample;
    uint16 samplesPerPixel;
    char* compressionType;
    uint16 orientation;
    char* softwareUsed;
} ImageInfo;

ImageInfo parseTIFF(const char *filename) {
    TIFF* tiff = TIFFOpen(filename, "r");
    if (tiff == NULL) {
        fprintf(stderr, "Could not open TIFF file: %s\n", filename);
        exit(1);
    }

    ImageInfo info;
    info.compressionType = malloc(sizeof(char)*256);  // Assuming no compression type is longer than this
    info.softwareUsed = malloc(sizeof(char)*256);  // Same here

    TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &info.bitsPerSample);
    if (info.bitsPerSample != 1 && info.bitsPerSample != 2 && info.bitsPerSample != 4 && 
        info.bitsPerSample != 8 && info.bitsPerSample != 16) {

        fprintf(stderr, "Unsupported bits per sample: %d\n", info.bitsPerSample);
        exit(2);
    }

    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &info.samplesPerPixel);

    char* compression;
    if (TIFFGetField(tiff, TIFFTAG_COMPRESSION, &compression) == 1) {
        switch(compression) {
            case COMPRESSION_LZW: strcpy(info.compressionType, "LZW"); break;
            case COMPRESSION_JPEG: strcpy(info.compressionType, "JPEG"); break;
            default: strcpy(info.compressionType, "Unknown");  // Could be other types too
        }
    } else {
        strcpy(info.compressionType, "None");
    }

    TIFFGetField(tiff, TIFFTAG_ORIENTATION, &info.orientation);

    char* software;
    if (TIFFGetField(tiff, TIFFTAG_SOFTWARE, &software) == 1) {
        strncpy(info.softwareUsed, software, 256);  // Prevent overflow
    } else {
        strcpy(info.softwareUsed, "Unknown");
    }

    TIFFClose(tiff);
    return info;
}
```

This code simply extracts and returns the information you asked for in a struct. It assumes that each field has a unique tag in the TIFF format, which is not always true, but it's a good starting point. For more complex cases or additional functionality, this basic structure can be expanded upon. Please note that memory management needs to be handled correctly when using this code.
