```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#define MAX_FILENAME_LEN 256

typedef struct File {
    char* name;
    void* content; // this can be a buffer or any other type of data you'd like to store in the file
} File;

typedef struct Directory {
    int maxFiles;
    int currentFileIndex;
    File** files;
    pthread_mutex_t lock; 
} Directory;

Directory* createDirectory(int initialSize) {
    Directory* dir = malloc(sizeof(Directory));
    dir->maxFiles = initialSize;
    dir->currentFileIndex = 0;
    dir->files = malloc(initialSize * sizeof(File*));
    pthread_mutex_init(&dir->lock, NULL); 
    return dir;
}

void addFileToDirectory(Directory* dir, char* filename) {
    if (pthread_mutex_lock(&dir->lock)) {
        // handle error here...
        return;
    }

    if (dir->currentFileIndex >= dir->maxFiles) { 
        dir->files = realloc(dir->files, sizeof(File*) * dir->maxFiles * 2);
        dir->maxFiles *= 2;
    }

    File* file = malloc(sizeof(File));
    file->name = malloc(MAX_FILENAME_LEN);
    strcpy(file->name, filename);

    dir->files[dir->currentFileIndex] = file;
    dir->currentFileIndex++; 

    pthread_mutex_unlock(&dir->lock); 
}
```
In this code, a Directory struct is used to store the maximum size of the directory and the current number of files. The array of File pointers in each Directory is dynamically allocated with realloc when it's full, ensuring efficient memory usage while minimizing fragmentation. A mutex lock is used for thread-safe file addition operation by the multiple services.
"]

