['Here is a C code that implements your requirements using dynamic memory allocation and error handling:

```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} Record;

int populateRecords(Record **records, int m, int k, int minValue, int maxValue) {
    srand((unsigned int) time(NULL)); // initialize random seed with current time

    if (maxValue - minValue + 1 < k) return 1; // range is smaller than number of records

    int *usedKeys = calloc(m, sizeof(int));
    if (!usedKeys) return 2; // allocation error for used keys array

    for (int i = 0; i < k; ++i) {
        int value;
        do {
            value = rand() % (maxValue - minValue + 1) + minValue;
        } while (usedKeys[value - minValue] == 1); // regenerate if duplicate value found

        usedKeys[value - minValue] = 1; // mark key as used

        (*records)[i].key = value; 
    }

    free(usedKeys);
    return 0;
}

int createRecords(Record **records, int n, int m, int k, int minValue, int maxValue) {
    if (m < k || n < 1 || m < 1 || k < 0) return 2; // invalid input values

    *records = calloc(k, sizeof(Record));
    if (!(*records)) return 3; // allocation error for records array

    int status = populateRecords(records, m, k, minValue, maxValue);
    if (status != 0) {
        free(*records);
        return status + 2; // pass on allocation errors to caller
    }

    long *offsets = calloc(n, sizeof(long));
    if (!offsets) { 
        free(*records);
        return 3; // allocation error for offsets array
    }
    free(offsets);

    return 0; // successful creation
}
```

The `createRecords` function allocates memory for a collection of records and initializes them with random values. The function uses dynamic memory allocation, which is efficient and scales well with larger inputs. It also implements error handling to ensure that invalid input values or failed memory allocations are handled gracefully. Note that this code assumes that the system has enough available memory to fulfill its requests.
