    if (head == NULL) {
        head = newNode;
        peak = 1;
    } else {
        Node* current = head;
        int count = 0;
        while(current != NULL && current->event.timestamp <= timestamp + 500) { // Assuming events within 500ms are concurrent. Adjust as needed.
            count++;
            if (count > peak) peak = count;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&lock);
}

