#define MAX_RANDOM 1000000

typedef struct {
    int value;
} record;

record* allocate(int n, int m, int k) {
    if (n < 0 || m < 0 || k < 0 || m > MAX_RANDOM || k > MAX_RANDOM || k > m * n) {
        return NULL; // Invalid input values
    }

    long* offsets = calloc(n, sizeof(long));
    if (!offsets) {
        return NULL; // Memory allocation failure for offsets
    }

    int* keys = calloc(m, sizeof(int));
    if (!keys) {
        free(offsets); // Memory allocation failure for keys
        return NULL;
    }

    srand((unsigned int)time(NULL));
    record *records = malloc(k * sizeof(record));

    if(!records){
        free(keys); 
        free(offsets); // Memory allocation failure for records
        return NULL;
    }

    int i, j = 0;
    while (j < k) {
        i = rand() % MAX_RANDOM + 1; // Generate a random value between 1 and MAX_RANDOM

        // Check for collisions
        for(int x=0; x<j; ++x){
            if(records[x].value == i) {
                --j;
                break;
            }
        }

        records[j++].value = i; 
    }

    free(offsets);
    free(keys);
    return records; // Return pointer to the array of record structures after initialization
}
