Record* generate_records(size_t count, int min, int max) {
    srand(time(NULL)); // seed the random number generator with current time

    Record *records = malloc(count * sizeof(Record)); 
    if (records == NULL) {
        log_error("Failed to allocate memory for records");
        return NULL;
    }

    int* keys = malloc(count * sizeof(int));
    if (keys == NULL) {
        log_error("Failed to allocate memory for keys");
        free(records);
        return NULL;
    }

    int* offsets = malloc(count * sizeof(int));
    if (offsets == NULL) {
        log_error("Failed to allocate memory for offsets");
        free(records);
        free(keys);
        return NULL;
    }

    // generate unique keys and offsets in specified range
    for (size_t i = 0; i < count; ++i) {
        int key, offset;

        do {
            key = get_external_key(); 
        } while (!(min <= key && key <= max));

        do {
            offset = get_external_offset(); 
        } while (!(min <= offset && offset <= max));

        // check for uniqueness
        int j;
        for (j = 0; j < i; ++j) {
            if (keys[j] == key || offsets[j] == offset) {
                break;
            }
        }

        if (j != i) { 
            --i; // retry if not unique
            continue;
        }

        keys[i] = key;
        offsets[i] = offset;
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    free(keys);
    free(offsets);

    return records;
}

void cleanup_records(Record* records) {
    assert(records != NULL); 
    free(records);
}
