Here's a simplified version:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    char *key;
    void *value;
} Entry;

typedef struct {
    int size, count;
    Entry **table;
    pthread_mutex_t lock;
} HashTable;

HashTable* createTable(int size) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->size = size;
    ht->count = 0;
    ht->table = malloc(sizeof(Entry*) * size);
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned long hashCode(char *key) {
    unsigned long code = 5381;
    int c;
    while ((c = *key++))
        code = ((code << 5) + code) + c; /* hash * 33 + c */
    return code;
}

void* get(HashTable *ht, char *key) {
    unsigned long index = hashCode(key) % ht->size;
    pthread_mutex_lock(&ht->lock);
    while (ht->table[index] != NULL && ht->table[index]->key != NULL 
           && strcmp(ht->table[index]->key, key) != 0) {
        index = (index + 1) % ht->size;
    }
    pthread_mutex_unlock(&ht->lock);
    if (ht->table[index] == NULL || ht->table[index]->key == NULL)
        return NULL;
    else
        return ht->table[index]->value;
}
```
This code creates a basic hash table, and provides the ability to get entries by key. It locks the entire table while accessing it to avoid race conditions. 

In a real implementation you would need error handling, parameter validation, logic for resizing the hash table when it gets too full, support for deleting entries, data persistence etc., which would take considerably more code and time than this simple example shows. The actual solution would also depend on the specific requirements of your application.
