['Below is C code snippet which implements above-mentioned requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#define INITIAL_SIZE 1000
#define MAX_LOAD 0.75

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    pthread_mutex_t lock;
} hashTable;

hashTable table;
int size = INITIAL_SIZE, count = 0;

// Helper functions 
long customHash(int key) {
    return ((long)(key * 2654435761)) % size;
}

void resize() {
    long* oldOffsets = table.offsets;
    int* oldKeys = table.keys;
    record** oldRecords = table.records;

    size *= 2;  // Doubling the size of the hash table
    count = 0;

    table.offsets = (long*)calloc(size, sizeof(long));
    table.keys = (int*)calloc(size, sizeof(int));
    table.records = (record**)calloc(size, sizeof(record*));

    for(int i = 0; i < size/2; i++){  // Repopulating hash table with old data
        if(oldKeys[i] != 0){
            insertToTable(oldOffsets[i], oldRecords[i]);
        }
    }

    free(oldOffsets);
    free(oldKeys);
    for(int i = 0; i < size/2; i++)
        if(oldRecords[i])
            free(oldRecords[i]);
    free(oldRecords);
}

void insertToTable(long offset, record* rec) {
    pthread_mutex_lock(&table.lock);  // Locking for thread safety

    long hash = customHash(rec->value);
    while(table.keys[hash] != 0){
        if (count / size > MAX_LOAD)  // Check load factor and resize if needed
            resize();

        hash = (hash + 1) % size;  // Quadratic probing for collision resolution
    }

    table.offsets[hash] = offset;
    table.keys[hash] = rec->value;
    table.records[hash] = rec;
    ++count;

    pthread_mutex_unlock(&table.lock);  // Unlocking after operation is done
}

void initTable() {
    srand(time(0));

    table.offsets = (long*)calloc(size, sizeof(long));
    table.keys = (int*)calloc(size, sizeof(int));
    table.records = (record**)calloc(size, sizeof(record*));
    pthread_mutex_init(&table.lock, NULL);  // Initializing mutex for thread safety
}

void freeTable() {
    for(int i = 0; i < size; i++){  // Freeing records
        if(table.records[i])
            free(table.records[i]);
    }

    free(table.offsets);  // Freeing rest of the table
    free(table.keys);
    free(table.records);
}

void insertData() {
    FILE *file = fopen("data.txt", "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        exit(1);
    }

    int data;
    long offset = 0;
    while(fscanf(file, "%d", &data) != EOF){
        record* rec = (record*)malloc(sizeof(record));
        rec->value = rand() % 10 + 1;  // Setting random value within specified range

        insertToTable(offset, rec);  // Inserting data to the hash table
        offset += sizeof(record);  // Calculating offset for next record
    }

    fclose(file);
}
```

