// Structure for the hash table entry
typedef struct entry_t {
    int key;
    long offset;
    struct entry_t *next;
} entry_t;

entry_t **hash_table = NULL;
pthread_mutex_t hash_lock[8];
int TABLE_SIZE = 256; // Assuming a small table size for simplicity

void init() {
    srand(time(NULL)); 
    int i;

    // Allocate memory for the arrays
    long *offsets = malloc(sizeof(long) * TABLE_SIZE);
    int *keys = malloc(sizeof(int) * TABLE_SIZE);
    record_t *records = malloc(sizeof(record_t) * TABLE_SIZE);

    // Initialize the arrays with random values
    for (i = 0; i < TABLE_SIZE; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % 100;
        records[i].value = rand() % 100;
    }

    // Initialize the hash table and locks
    for (i = 0; i < 8; ++i) {
        pthread_mutex_init(&hash_lock[i], NULL);
    }
    hash_table = malloc(sizeof(entry_t *) * TABLE_SIZE);
    for (i = 0; i < TABLE_SIZE; ++i) {
        entry_t *newEntry = malloc(sizeof(entry_t));
        newEntry->key = keys[i];
        newEntry->offset = offsets[i];
        newEntry->next = NULL;

        // Add to the hash table
        int index = abs(newEntry->key % TABLE_SIZE); 
        pthread_mutex_lock(&hash_lock[index]);
        if (hash_table[index] == NULL) {
            hash_table[index] = newEntry;
        } else {
            entry_t *currentEntry = hash_table[index];
            while(currentEntry->next != NULL) {
                currentEntry = currentEntry->next;
            }
            currentEntry->next = newEntry;
        }
        pthread_mutex_unlock(&hash_lock[index]);
    }
}
```
This code initializes the long offsets array, int keys array, and record struct arrays with random values. It also creates a hash table using separate chaining to handle collisions. Each thread has its own mutex for concurrent access to different parts of the hash table. 

2) Free allocated memory:
```C
void cleanup() {
    int i;

    // Clean up the arrays
    free(offsets);
    free(keys);
    free(records);

    // Clean up the hash table and locks
    for (i = 0; i < TABLE_SIZE; ++i) {
        while (hash_table[i] != NULL) {
            entry_t *next = hash_table[i]->next;
            free(hash_table[i]);
            hash_table[i] = next;
        }
    }
    for (i = 0; i < 8; ++i) {
        pthread_mutex_destroy(&hash_lock[i]);
    }
}
```
This code frees the memory allocated for the arrays and the hash table. It also cleans up the mutex locks used to control concurrent access to different parts of the hash table. 

