['Here is a basic implementation in C using `pthread` library for threading mechanism, `unordered_map` from the STL for hash table and atomic operations for maintaining thread safety. 

```C++
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <atomic>
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <unordered_map>

typedef struct resource {
    int id;
} Resource;

std::atomic<int*> resBundle(nullptr);  // Atomic pointer to bundle of resources
pthread_rwlock_t rwLock = PTHREAD_RWLOCK_INITIALIZER;

Resource * loadResBundleFromFile(const char* filePath, int &itemCount) {
    std::ifstream inStream(filePath, std::ios::binary);

    if (!inStream) {
        printf("Error opening the file.\n");
        return nullptr;
    }

    // Read number of items and allocate memory for bundle
    inStream.read((char*)&itemCount, sizeof(int));
    Resource *bundle = new Resource[itemCount];  // Dynamically allocate memory

    for (int i = 0; i < itemCount; ++i) {
        inStream.read((char*)&bundle[i].id, sizeof(int));
    }

    inStream.close();
    return bundle;
}

void* threadedLoadResBundleFromFile(void *filePath) {
    int itemCount = 0;
    Resource *loadedBundle = loadResBundleFromFile((const char*) filePath, itemCount);

    pthread_rwlock_wrlock(&rwLock);  // Acquire a write lock
    delete[] resBundle.load();  // Delete previous bundle and free memory

    resBundle.store(loadedBundle);  // Store the new loaded bundle
    pthread_rwlock_unlock(&rwLock);  // Release the lock

    return NULL;
}
```
Please note, this is a basic solution. You may need to expand it with your specific needs like exception handling or memory management depending on the use case and context of your larger system. Also, you might need to adapt it to work in different environments (e.g., real-time systems) according to the constraints and requirements of your project.
