typedef struct hash_table {
    pthread_mutex_t lock;
    long* offsets;
    int* keys;
    Record** records;
    size_t capacity;
    size_t count;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = malloc(sizeof(*table));
    pthread_mutex_init(&table->lock, NULL);
    table->offsets = calloc(initial_capacity, sizeof(*table->offsets));
    table->keys = calloc(initial_capacity, sizeof(*table->keys));
    table->records = calloc(initial_capacity, sizeof(*table->records));
    table->capacity = initial_capacity;
    table->count = 0;

    return table;
}

void resize_hash_table(HashTable* table) {
    pthread_mutex_lock(&table->lock);

    size_t new_capacity = table->capacity * 2;
    long* new_offsets = calloc(new_capacity, sizeof(*new_offsets));
    int* new_keys = calloc(new_capacity, sizeof(*new_keys));
    Record** new_records = calloc(new_capacity, sizeof(*new_records));

    for (size_t i = 0; i < table->count; ++i) {
        size_t hash = table->keys[i] % new_capacity;

        while (new_keys[hash] != 0) {
            hash = (hash + 1) % new_capacity;
        }

        new_offsets[hash] = table->offsets[i];
        new_keys[hash] = table->keys[i];
        new_records[hash] = table->records[i];
    }

    free(table->offsets);
    free(table->keys);
    free(table->records);

    table->offsets = new_offsets;
    table->keys = new_keys;
    table->records = new_records;
    table->capacity = new_capacity;

    pthread_mutex_unlock(&table->lock);
}

void insert(HashTable* table, int key, Record* record) {
    if (table->count >= table->capacity / 2) {
        resize_hash_table(table);
    }

    pthread_mutex_lock(&table->lock);

    size_t hash = key % table->capacity;

    while (table->keys[hash] != 0) {
        hash = (hash + 1) % table->capacity;
    }

    table->offsets[hash] = /* calculate offset */;
    table->keys[hash] = key;
    table->records[hash] = record;
    table->count++;

    pthread_mutex_unlock(&table->lock);
}
```

