// A node for our linked list that stores the data stream.
struct Node {
    double dblVal;
    char* strKey;
    StructData *sdata;
};

typedef struct Cache {
    int size;
    struct Node **nodes;
} Cache;

// For simplicity, we'll use a simple round-robin strategy for eviction. 
int currentEvictIndex = 0;
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;

Cache* createCache(int size) {
    Cache *cache = malloc(sizeof(Cache));
    cache->size = size;
    cache->nodes = calloc(size, sizeof(struct Node*));

    for (int i = 0; i < size; ++i) 
        cache->nodes[i] = NULL;

    return cache;
}

void destroyCache(Cache *cache) {
    pthread_mutex_lock(&cacheMutex);

    for (int i = 0; i < cache->size; ++i) 
        if (cache->nodes[i] != NULL)
            free(cache->nodes[i]);

    free(cache->nodes);
    pthread_mutex_unlock(&cacheMutex);

    free(cache);
}

void insertCache(Cache *cache, double dblVal, char* strKey, StructData* sdata) {
    struct Node *node = malloc(sizeof(struct Node));
    node->dblVal = dblVal;

    if (strKey != NULL) {
        node->strKey = malloc((strlen(strKey) + 1) * sizeof(char));
        strcpy(node->strKey, strKey);
    } else 
        node->strKey = NULL;

    node->sdata = sdata;

    pthread_mutex_lock(&cacheMutex);
    cache->nodes[currentEvictIndex] = node;
    currentEvictIndex = (currentEvictIndex + 1) % cache->size;
    pthread_mutex_unlock(&cacheMutex);
}

double retrieveCache(Cache *cache, char* strKey) {
    double result = 0.0;

    pthread_mutex_lock(&cacheMutex);
    for (int i = 0; i < cache->size; ++i) 
        if ((cache->nodes[i] != NULL) && (!strcmp(cache->nodes[i]->strKey, strKey))) {
            result = cache->nodes[i]->dblVal;
            break;
        }

    pthread_mutex_unlock(&cacheMutex);

    return result;
}
```
