['Here's a simplified version using pthread mutex for thread safety, error checking using assert(), logging with printf(), and dynamic memory management:

```c
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    int value;
} record_t;

typedef struct {
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    record_t* records;
} dynamic_array_t;

void init(dynamic_array_t* arr) {
    assert(pthread_mutex_init(&arr->lock, NULL) == 0);
    arr->size = 0;
    arr->capacity = 1024;
    arr->records = malloc(arr->capacity * sizeof(record_t));
}

void push_back(dynamic_array_t* arr, record_t rec) {
    assert(pthread_mutex_lock(&arr->lock) == 0);

    if (arr->size == arr->capacity) {
        printf("Resizing array\n");
        arr->records = realloc(arr->records, 2 * arr->capacity * sizeof(record_t));
        assert(arr->records != NULL); // Reallocation failure check.
    }

    arr->records[arr->size] = rec;
    arr->size++;

    assert(pthread_mutex_unlock(&arr->lock) == 0);
}

record_t get(dynamic_array_t* arr, size_t index) {
    assert(index < arr->size); // Index out of bounds check.

    record_t rec;

    assert(pthread_mutex_lock(&arr->lock) == 0);
    rec = arr->records[index];
    assert(pthread_mutex_unlock(&arr->lock) == 0);

    return rec;
}
```
This code creates a dynamic array of records, which can be expanded if it is full. The `push_back` function will automatically resize the array when there's not enough space for a new record and the `get` function checks whether the requested index exists in the array before retrieving the record. 

