int get_hostname_ip(const char *hostname, struct addrinfo **addr) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; ++i) {
        if (!strcmp(cache[i].hostname, hostname)) {
            *addr = cache[i].addr;
            pthread_mutex_unlock(&cache_lock);
            return 0;
        }
    }

    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int ret = getaddrinfo(hostname, NULL, &hints, addr);
    if (ret != 0) {
        pthread_mutex_unlock(&cache_lock);
        return -1;
    }

    if (cache_size < MAX_CACHE_SIZE) {
        strncpy(cache[cache_size].hostname, hostname, sizeof(cache[cache_size].hostname));
        cache[cache_size].addr = *addr;
        ++cache_size;
    }

    pthread_mutex_unlock(&cache_lock);
    return 0;
}

