    int retries = 0;
    while ((retries < MAX_RETRIES) && authenticate_user(username, password, &usr)) {
        ++retries;
        sleep(1); // Backoff before reattempting operation
    }

    if (retries == MAX_RETRIES) return -3; // Max retries exceeded

    pthread_mutex_lock(&session_lock);
    int session_id = num_sessions++;
    memcpy(sessions[session_id].token, usr.token, sizeof(usr.token));
    pthread_mutex_unlock(&session_lock);

    return 0; // Success
}
