        for ($i = 0; $i < $this->maxRetries; $i++) {
            try {
                $response = file_get_contents("{$this->authServiceUrl}/validateAndCheckDuplicate/{$newEmail}");
                if ($response === FALSE) {
                    throw new Exception('External auth service is down');
                }

                // Assuming the response from external service is in JSON format
                $responseData = json_decode($response, true);
                if (!isset($responseData['success'])) {
                    throw new Exception('Invalid response from external auth service');
                }

                if ($responseData['success']) {
                    $this->updateUserEmailInDB($userId, $newEmail);
                    return true;
                } else {
                    throw new Exception('Failed to validate and check for duplicates.');
                }
            } catch (Exception $e) {
                if ($i < $this->maxRetries - 1) { // Exponential backoff
                    usleep(pow(2, $i) * $this->backoffTime);
                } else {
                    throw $e; // If final attempt failed, rethrow the exception
                }
            }
        }
    }

