public class DataProcessingPipeline
{
    public async Task<IDataReader> ExecuteCommand(int[] values, SqlConnection connection, string command)
    {
        if (values == null || connection == null || !connection.State.HasFlag(ConnectionState.Open)) 
            throw new ArgumentException("Invalid argument");

        var parameters = new DynamicParameters();
        for (var i = 0; i < values.Length; i++)
            parameters.Add($"param{i}", values[i]);

