    int key;
    atomic_int value;
    pthread_mutex_t mutex; // Mutex for each entry
} Entry;

// Hash table to manage keys and records efficiently 
typedef struct {
    size_t size;
    Entry* entries;
} Table;

// Create a pool of memory buffers. It can be used by multiple threads simultaneously without locking.
#define MAX_BUFFERS 1024
char bufferPool[MAX_BUFFERS][1 << 16]; // Each buffer is 64KB
atomic_int nextBuffer;

// Lock for allocating memory from the pool
pthread_mutex_t bufferMutex = PTHREAD_MUTEX_INITIALIZER;

Table* createTable(size_t size) {
    Table* table = malloc(sizeof(Table));
    if (table == NULL) {
        // Log error and return NULL
    } else {
        table->size = size;
        table->entries = calloc(size, sizeof(Entry));
        if (table->entries == NULL) {
            free(table);
            // Log error and return NULL
        }
    }
}

void* allocateFromPool() {
    pthread_mutex_lock(&bufferMutex);
    int index = atomic_fetch_add(&nextBuffer, 1) % MAX_BUFFERS;
    pthread_mutex_unlock(&bufferMutex);

    return bufferPool[index];
}

// The actual function for creating the records and managing memory allocation
Record* createRecords(long* offsets, int* keys, size_t count) {
    Table* table = createTable(count);
    if (table == NULL) {
        // Log error and return NULL
    } else {
        for (size_t i = 0; i < count; ++i) {
            Entry* entry = &table->entries[i];
            entry->key = keys[i];
            pthread_mutex_init(&entry->mutex, NULL); // Initialize mutex for each entry
        }

        Record* records = allocateFromPool(sizeof(Record) * count);
        if (records == NULL) {
            free(table);
            // Log error and return NULL
        } else {
            for (size_t i = 0; i < count; ++i) {
                int value;
                RAND_bytes((unsigned char*)&value, sizeof(int)); // Generate cryptographically secure random number

                Entry* entry = &table->entries[i];
                atomic_store(&entry->value, value); // Store the value atomically to prevent race conditions

                Record* record = &records[i];
                pthread_mutex_lock(&entry->mutex); // Lock entry mutex before accessing its value
                record->value = atomic_load(&entry->value); // Load the value atomically to prevent race conditions
                pthread_mutex_unlock(&entry->mutex); // Unlock the entry mutex after access is complete
            }
        }
    }
}
