#include <vector>
#include <atomic>
#include <mutex>
#include <thread>
#include <cstdint>

constexpr size_t MAXIMUM_DEPTH = 20;
constexpr size_t ALLOCATION_CHUNK = 16 * 1024 * 1024; // 16MB
constexpr size_t CACHELINE_SIZE = 64;

struct OctreeNode {
    std::atomic<OctreeNode*> children[8];
};

class Allocator : public std::allocator<OctreeNode> {
public:
    using std::allocator<OctreeNode>::size_type;
    using std::allocator<OctreeNode>::pointer;
    using std::allocator<OctreeNode>::value_type;

    template <class U> struct rebind {typedef Allocator<U> other;};
    Allocator() noexcept {}
    template <class U> Allocator(const Allocator<U>&) noexcept {}
    ~Allocator() {}

    pointer allocate(size_type n, const void* hint = 0) {
        if (n > ALLOCATION_CHUNK) throw std::bad_alloc();

        // Allocate memory aligned to cache line boundary
        void *p = ::operator new[](n + CACHELINE_SIZE - 1);
        return static_cast<pointer>((reinterpret_cast<uintptr_t>(p) & ~(CACHELINE_SIZE-1))+CACHELINE_SIZE);
    }

    void deallocate(pointer p, size_type n) {
        ::operator delete[](reinterpret_cast<char*>(p)- CACHELINE_SIZE);
    }
};

class Octree {
public:
    Octree() : root(new (Allocator().allocate(1)) OctreeNode()) {}
    ~Octree() { Allocator().deallocate(root, 1); }

    void insert(uint32_t feature) {
