        temp->value = key;
        temp->point = point;
        temp->state = state;
        temp->left = temp->right = NULL;
        return temp;
    }

    if (key < node->value) {
        node->left  = insert(node->left, key, point, state);
    } else if (key > node->value) {
        node->right = insert(node->right, key, point, state);
    }

    // Unlock after operations
    pthread_mutex_unlock(&lock);

    return node;
}

// Memory deallocation and cleanup function
void cleanUp(Node *node) {
    if (node != NULL) {
        cleanUp(node->left);
        cleanUp(node->right); 
        free(node);
    }
}
```
