// Validation schema with Joi
const resourceValidationSchema = Joi.object({
  name: Joi.string().required(),
  description: Joi.string().required(),
});

// Create a new resource
app.post('/resource', async (req, res) => {
  const { error } = resourceValidationSchema.validate(req.body);
  if (error) return res.status(400).send(error.details[0].message);

  let resource = new ResourceModel({
    name: req.body.name,
    description: req.body.description,
  });

  resource = await resource.save();
  res.send(resource);
});

// Update a resource
app.put('/resource/:id', async (req, res) => {
  const { error } = resourceValidationSchema.validate(req.body);
  if (error) return res.status(400).send(error.details[0].message);

  // Update the resource
  const resource = await ResourceModel.findByIdAndUpdate(req.params.id, {
    name: req.body.name,
    description: req.body.description,
  }, { new: true });

  if (!resource) return res.status(404).send('The resource with the given ID was not found.');

  res.send(resource);
});

// Delete a resource
app.delete('/resource/:id', async (req, res) => {
  const resource = await ResourceModel.findByIdAndRemove(req.params.id);

  if (!resource) return res.status(404).send('The resource with the given ID was not found.');

  res.send(resource);
});

const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Listening on port ${port}...`));
