bstNode_t* minValueNode(bstNode_t* node) {
    bstNode_t* current = node;

    while (current && current->left != NULL) {
        current = current->left;
    }

    return current;
}

bstNode_t* deleteNode(bstNode_t* root, double key) {
    if (root == NULL) {
        return root;
    }

    if (key < root->key) {
        root->left = deleteNode(root->left, key);
    } else if(key > root->key) {
        root->right = deleteNode(root->right, key);
    } else {
        if (root->left == NULL) {
            bstNode_t* temp = root->right;
            free(root);
            return temp;
        } else if (root->right == NULL) {
            bstNode_t* temp = root->left;
            free(root);
            return temp;
        }

        bstNode_t* temp = minValueNode(root->right);
        root->key = temp->key;
        root->right = deleteNode(root->right, temp->key);
    }

    return root;
}
