    size_t refCount;
} Record;

typedef struct DataStructure {
    Record *records;
    size_t numRecords;
    size_t capacity;
} DataStructure;

DataStructure* init() {
    srand(time(NULL));  // seed the random number generator
    const int initialCapacity = 10000;

    DataStructure *ds = malloc(sizeof(DataStructure));
    ds->records = calloc(initialCapacity, sizeof(Record));
    ds->numRecords = 0;
    ds->capacity = initialCapacity;

    for (int i = 0; i < initialCapacity; i++) {
        ds->records[i].key = rand();  // generate a unique key
        ds->records[i].offset = rand();  // generate a corresponding offset
        ds->records[i].refCount = 0;
    }

    return ds;
}

size_t getRandomIndex(const DataStructure *ds) {
    assert(ds != NULL);
    return rand() % ds->numRecords;
}

void incrementRefCount(DataStructure *ds, int key) {
    assert(ds != NULL);

    for (size_t i = 0; i < ds->numRecords; i++) {
        if (ds->records[i].key == key) {
            ds->records[i].refCount++;
            return;
        }
    }

    // handle invalid or non-existent key
}

Record* getRecord(const DataStructure *ds, int key) {
    assert(ds != NULL);

    for (size_t i = 0; i < ds->numRecords; i++) {
        if (ds->records[i].key == key) {
            return &(ds->records[i]);
        }
    }

    // handle invalid or non-existent key
    return NULL;
}

void deallocate(DataStructure *ds) {
    free(ds->records);
    free(ds);
}
