#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#define MAX_ENTRIES 50000

typedef struct {
    unsigned int id;
    double *value;
    time_t *accessTime;
} item;

typedef struct {
    pthread_mutex_t lock;
    size_t count;
    item entries[MAX_ENTRIES];
} dynamicStructure;

dynamicStructure* createDynamicStructure() {
    dynamicStructure *ds = malloc(sizeof(*ds));
    if (pthread_mutex_init(&ds->lock, NULL) != 0) {
        printf("Mutex init failed\n");
        return NULL;
    }
    ds->count = 0;
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        ds->entries[i].id = -1;  // uninitialized id
        ds->entries[i].value = malloc(sizeof(double));
        *ds->entries[i].value = 0.0;  // initialize value to zero
        ds->entries[i].accessTime = NULL;
    }
    return ds;
}

void accessEntry(dynamicStructure* ds, unsigned int id) {
    if (pthread_mutex_lock(&ds->lock) != 0) {
        printf("Lock failed\n");
        return;
    }

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (ds->entries[i].id == id) {
            time(&ds->entries[i].accessTime);  // record access time
            break;
        }
    }

    if (pthread_mutex_unlock(&ds->lock) != 0) {
        printf("Unlock failed\n");
    }
}

void updateEntry(dynamicStructure* ds, unsigned int id, double value) {
    if (pthread_mutex_lock(&ds->lock) != 0) {
        printf("Lock failed\n");
        return;
    }

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (ds->entries[i].id == id) {
            *ds->entries[i].value = value;  // update value
            time(&ds->entries[i].accessTime);  // record access time
            break;
        }
    }

    if (pthread_mutex_unlock(&ds->lock) != 0) {
        printf("Unlock failed\n");
    }
}

void destroyDynamicStructure(dynamicStructure* ds) {
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        free(ds->entries[i].value);
    }
    if (pthread_mutex_destroy(&ds->lock) != 0) {
        printf("Mutex destroy failed\n");
    }
    free(ds);
}
