['Below is a simplified C++ code snippet that fulfills the requirements using the `rand()` function to simulate success rates and cooldown timers for attacks A, B, C, D. The game loop updates every frame at 60 frames per second, which simulates real-time gameplay.

```cpp
#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>

struct Attack {
    int successRate; // in percentage
    int cooldownTime; 
    bool isReady = true;
};

class GameCharacter {
public:
    GameCharacter() : attacks{{70,10},{50,15},{80,8},{60,12}}, successfulAttacks(0), totalSuccessfulAttacks(0) {}

    void updateCooldowns() {
        for (auto &attack : attacks) {
            if (!attack.isReady && cooldownTimers[&attack] <= 0) {
                attack.isReady = true;
            }
            else {
                cooldownTimers[&attack]--;
            }
        }
    }

    int selectAttack() {
        updateCooldowns();

        std::vector<int> availableAttacks;
        for (size_t i = 0; i < attacks.size(); ++i) {
            if(attacks[i].isReady){
                availableAttacks.push_back(i);
            }
        }

        if(availableAttacks.empty()){
            std::cout << "All attacks are on cooldown.";
            return -1;
        }

        int randomIndex = rand() % availableAttacks.size();
        int selectedAttackNumber = availableAttacks[randomIndex];

        if (rand() % 100 < attacks[selectedAttackNumber].successRate) {
            successfulAttacks++;
            totalSuccessfulAttacks++;

            // reset power boost after every 5 successful attacks
            if (successfulAttacks == 5){
                resetPowerBoost();
            }
        }

        cooldownTimers[&attacks[selectedAttackNumber]] = attacks[selectedAttackNumber].cooldownTime;
        attacks[selectedAttackNumber].isReady = false;

        std::cout << "Selected Attack: " << selectedAttackNumber << "\n";

        return selectedAttackNumber;
    }

    void resetPowerBoost(){
        successfulAttacks = 0;
    }

private:
    std::vector<Attack> attacks;
    int successfulAttacks;
    std::map<Attack*, int> cooldownTimers; // stores remaining time for each attack's cooldown
    int totalSuccessfulAttacks;
};

int main() {
    srand(static_cast<unsigned>(time(0)));

    GameCharacter character;
    while (true) {
        character.selectAttack();
        // sleep for 1/60 seconds to simulate a game loop update rate of 60 fps
        std::this_thread::sleep_for(std::chrono::milliseconds(1000 / 60));
    }

    return 0;
}
```
