    if (manager->connections == NULL){
        free(manager);
        return NULL;
    }

    pthread_rwlock_init(&(manager->rwlock), NULL);

    for(int i = 0; i < count; i++) {
        Connection* conn = malloc(sizeof(Connection));
        if (conn == NULL){  // handle allocation failure gracefully
            free(manager->connections); 
            return NULL;
        }

        conn->socketDescriptor = rand() % (maxSocketDesc - minSocketDesc + 1) + minSocketDesc;
        conn->status = DISCONNECTED;
        pthread_mutex_init(&(conn->lock), NULL);
        manager->connections[i] = conn;
    }

    return manager;
}
``` 
