#include <pthread.h>

typedef struct Element {
    double f_value;
    char *str_value;
    _Bool bool_flag;
} Element;

typedef struct Node {
    char *id;
    Element *element;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* createElement(double f_value, const char *str_value, _Bool bool_flag) {
    Element *element = malloc(sizeof(*element));
    if (element == NULL) return NULL;

    element->f_value = f_value;
    element->bool_flag = bool_flag;

    size_t len = strlen(str_value);
    element->str_value = malloc(len + 1);
    if (element->str_value == NULL) {
        free(element);
        return NULL;
    }

    memcpy(element->str_value, str_value, len + 1);
    return element;
}

Node* createNode(const char *id, Element *element) {
    Node *node = malloc(sizeof(*node));
    if (node == NULL) return NULL;

    node->next = NULL;
    node->element = element;

    size_t len = strlen(id);
    node->id = malloc(len + 1);
    if (node->id == NULL) {
        free(node);
        return NULL;
    }

    memcpy(node->id, id, len + 1);
    return node;
}

void insertNode(_Atomic(Node *) *head, Node *node) {
    pthread_mutex_lock(&lock);
    while (*head != NULL) {
        if (strcmp((*head)->id, node->id) == 0) {
            // handle duplicates or collisions as needed.
            break;
        } 

        head = &(*head)->next;
    }

    *head = node;
    pthread_mutex_unlock(&lock);
}

void deleteNode(_Atomic(Node *) *head, const char *id) {
    pthread_mutex_lock(&lock);
    while (*head != NULL) {
        if (strcmp((*head)->id, id) == 0) {
            Node *temp = *head;
            *head = temp->next;
            free(temp->element->str_value);
            free(temp->element);
            free(temp->id);
            free(temp);

            break;
        } 

        head = &(*head)->next;
    }

    pthread_mutex_unlock(&lock);
}
```

