typedef struct hash_table {
    pthread_rwlock_t lock; // Use a read-write lock for thread safety 
    long* offsets;
    int* keys;
    record_t* records;
    size_t size;
    size_t capacity;
} hash_table_t;

hash_table_t* create_hash_table(size_t initial_capacity) {
    // Dynamically allocate memory for the hash table and arrays
    hash_table_t* ht = malloc(sizeof(hash_table_t)); 
    ht->offsets = malloc(initial_capacity * sizeof(long));
    ht->keys = malloc(initial_capacity * sizeof(int));
    ht->records = malloc(initial_capacity * sizeof(record_t)); 

    // Initialize other fields of hash table
    ht->size = 0;
    ht->capacity = initial_capacity; 
    pthread_rwlock_init(&ht->lock, NULL); // Initialize the read-write lock

    return ht; 
}

void insert(hash_table_t* ht, long offset, int key) {
    if (ht->size >= ht->capacity / 2) { // Resize when capacity is half full
        resize(ht);
    }

    pthread_rwlock_wrlock(&ht->lock); // Lock for writing
    size_t index = hash(key, ht->capacity);

    while (ht->keys[index] != -1) { // Use linear probing to resolve collisions 
        if (++index == ht->capacity) {
            index = 0;
        }
    }

    ht->offsets[index] = offset;
    ht->keys[index] = key;
    ht->records[index].value = rand() % 100; // Set record value to random number within range
    ht->size++;

    pthread_rwlock_unlock(&ht->lock); // Unlock for writing
}
