    int statusCode;
    unsigned char* payload;
    size_t payloadSize;
} Record;

// Structure for database
typedef struct Database {
    Record** table;
    size_t size;
    pthread_mutex_t lock;
} Database;

// Function to initialize a record
Record* initRecord(size_t payloadSize) {
    srand((unsigned int) time(NULL));

    Record* record = malloc(sizeof(Record));
    if (record == NULL) return NULL;

    record->timestamp = time(NULL);
    record->statusCode = rand() % 1000; // Random number from 0 to 999
    record->payloadSize = payloadSize;

    record->payload = malloc(payloadSize * sizeof(unsigned char));
    if (record->payload == NULL) {
        free(record);
        return NULL;
    }

    // Randomly generate payload
    for (size_t i = 0; i < payloadSize; ++i) {
        record->payload[i] = rand() % 256; // Random byte value
    }

    return record;
}

// Function to initialize the database
Database* initDB(size_t size, size_t payloadSize) {
    Database* db = malloc(sizeof(Database));
    if (db == NULL) return NULL;

    db->table = calloc(size, sizeof(Record*));
    if (db->table == NULL) {
        free(db);
        return NULL;
    }

    db->size = size;
    pthread_mutex_init(&db->lock, NULL); // Initialize the mutex lock for thread safety

    for (size_t i = 0; i < size; ++i) {
        Record* record = initRecord(payloadSize);
        if (record == NULL) {
            for (size_t j = 0; j < i; ++j) { // Free previously allocated records on error
                free(db->table[j]->payload);
                free(db->table[j]);
            }
            free(db->table); // Free table before returning NULL to prevent memory leak
            return NULL;
        }

        db->table[i] = record;
    }

    return db;
}
