const fs = require('fs');
const path = require('path');
const async = require('async');
const readdirp = require('readdirp');
const logger = console; // replace with actual logging service

// Mock function for processing file contents
function processFileContent(filePath, cooldownDuration) {
    return new Promise((resolve, reject) => {
        fs.readFile(filePath, 'utf8', (error, data) => {
            if (error) {
                logger.log('error processing file: ', error);
                reject(error);
            } else {
                // mock processing...
                setTimeout(() => {
                    resolve({ processedData: data });
                }, cooldownDuration);
            }
        });
    });
}

function processFilesWithCooldown(directoryPath, cooldownDuration = 50) {
    let filesProcessedCount = 0;
    const startTime = Date.now();

    return new Promise((resolve, reject) => {
        readdirp(directoryPath).on('data', (entry) => {
            async.waterfall([
                function(callback) {
                    processFileContent(path.join(directoryPath, entry.name), cooldownDuration)
                        .then((result) => callback(null, result))
                        .catch((error) => callback(error));
                },
                (result, callback) => {
                    filesProcessedCount++;
                    logger.log('Files processed: ', filesProcessedCount);
                    const endTime = Date.now();
                    logger.log('Total processing time: ', ((endTime - startTime) / 1000), 'seconds');
                    callback(null, result);
                }
            ], (error) => {
                if (error) {
                    reject(error);
                } else {
                    resolve({ totalFilesProcessed: filesProcessedCount });
                }
            });
        })
    });
}
```
