static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize(size_t size, double* nums, char** strs, data_entry** entries) {
    if (size == 0 || nums == NULL || strs == NULL || entries == NULL) return;

    pthread_mutex_lock(&mutex); // Ensure thread safety.

    *nums = malloc(size * sizeof(double)); 
    *strs = malloc(size * sizeof(char*)); 
    *entries = malloc(size * sizeof(data_entry));

    if (*nums == NULL || *strs == NULL || *entries == NULL) { // Handle memory allocation failure.
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex); 
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        time_t t = time(NULL); // Get the current date and time.

        if ((*nums)[i] = -1, (*strs)[i] = NULL || (*entries)[i].value == -1 && (*entries)[i].str == NULL) { // Handle function failure or potential buffer overflow.
            fprintf(stderr, "Function error or potential buffer overflow.\n");
            pthread_mutex_unlock(&mutex); 
            return;
        }

        (*nums)[i] = (double) t;  // Store the current date and time as a 'double' value.
        (*strs)[i] = ctime(&t); // Convert the 'double' to string format.

        if ((*strs)[i] == NULL) {
            fprintf(stderr, "Function error or potential buffer overflow.\n");
            pthread_mutex_unlock(&mutex); 
            return;
        }

        (*entries)[i].value = (double) t; // Populate the 'data_entry' structure.
        (*entries)[i].str = strdup((*strs)[i]);
    }

    pthread_mutex_unlock(&mutex); 
}
