#include <stdio.h>
#include <glib.h>
#include <gdk-pixbuf/gdk-pixbuf.h>
#include <libconfig.h>

// Define cache size and directory limit
#define CACHE_SIZE 1024 // Adjust as necessary
#define DIR_LIMIT  512  // Adjust as necessary

typedef struct {
    char *path;
    int count;
} CacheEntry;

gboolean compare_cache_entries(gconstpointer a, gconstpointer b) {
    return ((CacheEntry*)a)->count > ((CacheEntry*)b)->count;
}

void update_entry_frequency(GHashTable* cache, char *path) {
    CacheEntry *entry = (CacheEntry*)g_hash_table_lookup(cache, path);
    ++entry->count;
}

int main() {
    config_t cfg;
    config_init(&cfg);

    // Read the configuration file
    if(!config_read_file(&cfg, "settings.conf")) {
        fprintf(stderr, "%s:%d - %s\n", config_error_file(&cfg),
                config_error_line(&cfg), config_error_text(&cfg));
        config_destroy(&cfg);
        return(EXIT_FAILURE);
    }

    // Create a cache for theme bitmaps
    GHashTable* themeCache = g_hash_table_new(g_str_hash, g_str_equal);

    char *themeDir;
    if (config_lookup_string(&cfg, "theme.directory", &themeDir)) {
        // Theme directory is set in the configuration file
        printf("Theme directory: %s\n", themeDir);
    } else {
        // Theme directory is not set in the configuration file
        themeDir = "/default/path";  // Replace with your default path
        printf("Theme directory was not defined, using default path: %s\n", themeDir);
    }

    // Parse PNG files from the cache root directory and update their usage frequency in the cache
    GDir *dir = g_dir_open(themeDir, 0, NULL);
    const gchar *name;

    while ((name = g_dir_read_name(dir))) {
        char *path = g_build_filename(themeDir, name, NULL);

        if (gdk_pixbuf_get_file_info(path, NULL)) {  // Check if the file is a PNG image
            CacheEntry *entry;

            // If entry already exists in cache, update its count and frequency
            if ((entry = g_hash_table_lookup(themeCache, path))) {
                update_entry_frequency(themeCache, path);
            } else {  // Else create a new entry in the cache with a count of 1
                entry = g_new0(CacheEntry, 1);
                entry->path = path;
                ++entry->count;
                g_hash_table_insert(themeCache, (gpointer)path, entry);
            }
        } else {
            fprintf(stderr, "File '%s' is not a valid PNG file.\n", name);
        }
    }

    // Cleanup
    g_dir_close(dir);
    config_destroy(&cfg);

    return 0;
}
```
This code will read a configuration file, parse a directory for PNG files, and create a cache of these images with their use frequency. It also checks if the theme directory is set in the configuration file, and uses a default path if it isn't. This is a very simplified example and doesn't include many features you mentioned such as pruning the cache when it reaches its limit or calculating the average of last three numerical fields from each line in the configuration files.
