["This is quite a complex task which requires some experience in C programming and multi-threading. Here's an outline of how you might approach this problem using open addressing (double hashing) for collision resolution and pthread_rwlock to ensure thread safety. Please note that the actual implementation can vary significantly depending on specific performance requirements, hardware capabilities, or other constraints:

```c
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>

#define MAX_TABLE_SIZE 10000000 // maximum size of the cache
#define LOAD_FACTOR_THRESHOLD 0.75 // when to resize the table

typedef struct {
    int key;
    long offset;
    struct timeval timestamp;
} CacheEntry;

typedef struct {
    pthread_rwlock_t lock;
    int size;
    int capacity;
    CacheEntry **table; // hash table of pointers to entries
} Cache;

Cache *cache_create() {
    Cache *cache = malloc(sizeof(Cache));
    cache->size = 0;
    cache->capacity = MAX_TABLE_SIZE / 10; // start with a small table size
    cache->table = calloc(cache->capacity, sizeof(CacheEntry *));
    pthread_rwlock_init(&cache->lock, NULL);
    return cache;
}

void cache_insert(Cache *cache, int key, long offset) {
    pthread_rwlock_wrlock(&cache->lock); // acquire write lock

    if (cache->size >= cache->capacity * LOAD_FACTOR_THRESHOLD) {
        resize_table(cache); // handle resizing the table when it's 75% full
    }

    CacheEntry *new_entry = malloc(sizeof(CacheEntry));
    new_entry->key = key;
    new_entry->offset = offset;
    gettimeofday(&new_entry->timestamp, NULL); // record the current time as insertion timestamp

    int index = hash1(key), increment = hash2(key);
    while (cache->table[index] != NULL) { // handle collisions using open addressing
        if (cache->table[index]->key == key) {
            free(new_entry);
            return; // no duplicates allowed in this cache
        }
        index = (index + increment) % cache->capacity;
    }
    cache->size++;
    cache->table[index] = new_entry;

    pthread_rwlock_unlock(&cache->lock); // release lock
}

/* other functions for delete, update, read etc. */
```
This code only includes the core functionality of your requirements. You would also need to implement helper methods such as `hash1()`, `hash2()` and `resize_table()`. Also note that you will have to ensure thread safety in other parts of your program where this cache is being accessed from multiple threads.
