#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long* offset;
    int* key;
} record;

typedef struct {
    pthread_mutex_t lock;
    size_t nrecords;
    record** records;
} data_store;

data_store* create_store(size_t size) {
    srand((unsigned int)time(NULL));
    data_store *store = malloc(sizeof(data_store));
    store->nrecords = 0;
    pthread_mutex_init(&(store->lock), NULL);
    store->records = calloc(size, sizeof(record*));
    return store;
}

void insert_record(data_store *store, long offset, int key) {
    pthread_mutex_lock(&(store->lock));

    record *new_record = malloc(sizeof(record));
    new_record->value = rand() % 100 + 1; // Random value between 1 and 100
    new_record->offset = malloc(sizeof(long));
    *(new_record->offset) = offset;
    new_record->key = malloc(sizeof(int));
    *(new_record->key) = key;

    store->records[store->nrecords++] = new_record;

    pthread_mutex_unlock(&(store->lock));
}

void destroy_store(data_store *store) {
    for (size_t i = 0; i < store->nrecords; ++i) {
        free(store->records[i]->offset);
        free(store->records[i]->key);
        free(store->records[i]);
    }

    free(store->records);
    pthread_mutex_destroy(&(store->lock));
    free(store);
}
