typedef struct cacheNode {
    double distance;
    int index1, index2;
    struct cacheNode* next;
} CacheNode;

CacheNode* head = NULL;
pthread_mutex_t lock;

double getDistance(struct point p1, struct point p2) {
    return sqrt((p1.x - p2.x) * (p1.x - p2.x) + (p1.y - p2.y) * (p1.y - p2.y));
}

double* getCachedDistance(int index1, int index2, Geometry geom, CacheNode** cacheHead){
    CacheNode* temp = *cacheHead;
    while(temp != NULL) {
        if((temp->index1 == index1 && temp->index2 == index2)) {
            return &(temp->distance);
        }
        temp = temp->next;
    }
    double distance = getDistance(geom.pts[index1], geom.pts[index2]);
    CacheNode* newCacheNode = (CacheNode*) malloc(sizeof(CacheNode));
    if(!newCacheNode){ 
        printf("Memory allocation failed");
        exit(0);
    }
    newCacheNode->distance = distance;
    newCacheNode->index1 = index1;
    newCacheNode->index2 = index2;
    pthread_mutex_lock(&lock);
    newCacheNode->next = *cacheHead;
    *cacheHead = newCacheNode;
    pthread_mutex_unlock(&lock);
    return &(newCacheNode->distance);
}

void* calculateDistances(void* geomData) {
    Geometry geom = *((Geometry*)geomData);
    for (int i = 0; i < geom.size - 1; ++i){
