    if(pthread_create(&threadID, NULL, &calculateDistances, (void*)&geom)){ 
        printf("Thread creation failed");
        exit(0);
    }
    if(pthread_join(threadID, NULL)){ 
        printf("Thread join failed");
        exit(0);
    }

    CacheNode* temp = head;
    while(temp){
        CacheNode* nextNode = temp->next;
        free(temp);
        temp = nextNode;
    }
    free(geom.pts);
    free(geom.int_val);

    return 0;
}
