```c
#include <stdlib.h>
#include <assert.h>
#include <time.h>

#define MAX_OFFSETS 100000
#define MAX_KEYS 1000000
#define MAX_RECORDS 2000000
#define MAX_MEMORY_KB 1024*5 // 5MB
#define MAX_OFFSET_VALUE LONG_MAX
#define MAX_KEY_VALUE INT_MAX

typedef struct record {
    long offset;
    int key;
} record;

record* init_memory(size_t max_offsets, size_t max_keys, size_t max_records, size_t max_memory) {
    assert(max_offets > 0 && max_keys > 0 && max_records > 0);

    // Calculate total memory needed and ensure it doesn't exceed the limit.
    const size_t total_mem = (sizeof(long) * max_offsets) + (sizeof(int) * max_keys) + (sizeof(record) * max_records);
    if (total_mem > max_memory*1024) {
        return NULL;
    }

    long* offsets = calloc(max_offets, sizeof(*offsets));
    if (!offsets) return NULL; // allocation failed.

    int* keys = calloc(max_keys, sizeof(*keys));
    if (!keys) {
        free(offsets);
        return NULL;
    } // allocation failed.

    record* records = calloc(max_records, sizeof(*records));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    } // allocation failed.

    srand((unsigned int) time(NULL));  // Initialize the random number generator.

    for (size_t i = 0; i < max_records; ++i) {
        records[i].offset = rand() % MAX_OFFSET_VALUE;
        records[i].key = rand() % MAX_KEY_VALUE;
    }

    return records;
}
```
