    logfile = fopen("log.txt", "a");
}

int readDataFromExternalSource(dataset *data) {
    /* Code to read data from external source */
    return 0; // Return number of records loaded
}

record* getRecordByKey(dataset *data, int key) {
    pthread_rwlock_rdlock(&rwlock);
    for (int i = 0; i < data->size; i++) {
        if (*(data->keys + i) == key) {
            pthread_rwlock_unlock(&rwlock);
            return *(data->records + i);
        }
    }
    pthread_rwlock_unlock(&rwlock);
    return NULL; // No record with given key found
}

void updateRecordByKey(dataset *data, int key, int newValue) {
    pthread_mutex_lock(&data->lock);
    for (int i = 0; i < data->size; i++) {
        if (*(data->keys + i) == key) {
            record* rec = *(data->records + i);
            rec->value = newValue;
            pthread_mutex_unlock(&data->lock);
            return;
        }
    }
    pthread_mutex_unlock(&data->lock);
}

dataset *initializeData() {
    if (data != NULL) {
        return data; // Already initialized
    }

    openLogFile();

    data = malloc(sizeof(dataset));
    data->records = calloc(0, sizeof(record*));
    data->offsets = calloc(0, sizeof(long));
    data->keys = calloc(0, sizeof(int));
    pthread_mutex_init(&data->lock, NULL);

