void processFile(char* filename, int batchSize, int numThreads) {
    FILE* file = fopen(filename, "r");  // Open the input file in read mode

    while (!feof(file)) {
        record_t* batch = malloc(batchSize * sizeof(record_t));

        for (int i = 0; i < batchSize; ++i) {
            fread(&batch[i], sizeof(record_t), 1, file);  // Read a batch of records from the file
        }

        pthread_t threads[numThreads];
        for (int i = 0; i < numThreads; ++i) {
            pthread_create(&threads[i], NULL, processBatch, batch);  // Process each batch concurrently
        }

        for (int i = 0; i < numThreads; ++i) {
            pthread_join(threads[i], NULL);  // Wait for all threads to finish before moving on to the next batch
        }

        free(batch);  // Free memory allocated for this batch
    }

