// Assuming angularJS environment with $http service
app.factory('refreshDialogFields', ['$http', function($http) {
    // Private variables and functions
    var forwardList = [];
    var cache = {};
    var timestamp = 0;
    var isUpdating = false;

    return {
        refresh: function(resourceId, url, fieldNames, config={}) {
            if (!Array.isArray(fieldNames) || !fieldNames.length) throw new Error('Invalid or empty field names array');

            // Lazy loading of fields
            var lazyLoadField = function(name) {
                // Check cache first for performance improvement
                if (cache[name]) return Promise.resolve();

                // If not in cache, make API call and add to cache
                return $http.get(`${url}/${resourceId}/fields/${name}`).then((response) => {
                    cache[name] = response;
                });
            };

            // Handle concurrency control (optimistic)
            if (!isUpdating) {
                isUpdating = true;

                return Promise.all(fieldNames.map(lazyLoadField)).then(() => {
                    // Update dialog fields
                    fieldNames.forEach((name, index) => {
                        var field = cache[name];

                        if (config.validate && config.validate(field)) {
                            window.parent.postMessage({ field: name, status: 'success' });

                            // Update dialog field
                            updateDialogField(index, field);
                        } else {
                            window.parent.postMessage({ field: name, status: 'failure' });
                        }
                    });

                    isUpdating = false;
                }).catch((error) => {
                    isUpdating = false;
                    throw error;
                });
            } else {
                // Handle case of concurrent update
                return Promise.reject(new Error('Already updating'));
            }
        },

        insertAfter: function(search, insert) {
            var index = forwardList.indexOf(search);

            if (index !== -1 && index < forwardList.length - 1) {
                forwardList.splice(index + 1, 0, insert);
            } else {
                forwardList.push(insert);
            }
        },
    };
}]);
