['Below is a basic implementation in C that fulfills your requirements. It reads data from file line by line and creates new nodes as per the offsets and keys provided. Error checking has been done to cover various edge cases like malformed input, premature file termination, out-of-memory situations etc.

```C
#include <stdio.h>
#include <stdlib.h>

struct Record {
    long offset;
    int key;
    struct Record* next;
};

typedef struct Record record_t;

record_t *createNode(long offset, int key) {
    record_t *newRecord = malloc(sizeof(record_t));

    if (!newRecord) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);  // Out of memory
    }

    newRecord->offset = offset;
    newRecord->key = key;
    newRecord->next = NULL;
    return newRecord;
}

record_t *addNode(record_t* head, long offset, int key) {
    if (!head) 
        return createNode(offset, key);

    record_t* cursor = head;
    while (cursor->next != NULL) 
        cursor = cursor->next;

    cursor->next = createNode(offset, key);
    return head;
}

void freeList(record_t *head) {
    record_t* tmp;

    while (head != NULL) {
       tmp = head;
       head = head->next;
       free(tmp);
    }
}

int processFile(const char *filename, record_t **head) {
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        printf("Failed to open file\n");
        exit(EXIT_FAILURE);  // File not found or unable to read
    }

    long offset;
    int key;
    int count = 0;

    while (fscanf(file, "%ld %d", &offset, &key) == 2) {
        *head = addNode(*head, offset, key); 
        ++count;
    }

    fclose(file);

    if (!feof(file)) {
       printf("File read error\n");
       freeList(*head);  // If we are here then there was an error reading the file. Clean up and exit.
       exit(EXIT_FAILURE);  
    }

    return count;
}
```
The `processFile` function accepts a filename to read from, and a pointer to the head of the linked list. It reads each line (assuming lines are pairs of offsets and keys), creates nodes for them, adds those nodes to the end of the list using `addNode`, and finally returns the count of records successfully added to the collection.
