hash_table* initialize(int size) {
    hash_table* table = malloc(sizeof(hash_table));
    table->offsets = calloc(size, sizeof(long));
    table->keys = calloc(size, sizeof(int));
    table->records = calloc(size, sizeof(record));
    return table;
}
