    }
    size_t index = ((size_t)key) % ht->capacity;
    while (ht->records[index] != NULL) {
        if (++index == ht->capacity)
            index = 0;
    }
    ht->records[index] = record;
    ++ht->count;
    pthread_mutex_unlock(&ht->lock);
}

void *hash_table_find(HashTable *ht, int key) {
    size_t index = ((size_t)key) % ht->capacity;
    pthread_mutex_lock(&ht->lock);
    while (ht->records[index] != NULL && ht->records[index]->key != key) {
        if (++index == ht->capacity)
            index = 0;
    }
