4. Ensure thread-safe resizing:
```c
void hashTableResize(HashTable* h, size_t newBucketCount) {
    pthread_mutex_lock(&h->resizeLock); // Lock the table before resizing to prevent other threads from modifying it during the process
    Bucket* oldBuckets = h->buckets;
    int oldBucketCount = h->bucketCount;
    h->buckets = calloc(newBucketCount, sizeof(Bucket)); // Allocate new buckets
    for (int i = 0; i < oldBucketCount; ++i) {
        pthread_rwlock_rdlock(&oldBuckets[i].lock);  // Lock old bucket to prevent writing during resizing
        for (int j = 0; j < oldBuckets[i].count; ++j) {
            int newIndex = hash(oldBuckets[i].records[j].value, newBucketCount);
            pthread_rwlock_wrlock(&h->buckets[newIndex].lock);  // Lock the target bucket for writing
            h->buckets[newIndex].records = realloc(h->buckets[newIndex].records, (h->buckets[newIndex].count + 1) * sizeof(Record));
            h->buckets[newIndex].records[h->buckets[newIndex].count] = oldBuckets[i].records[j]; // Copy the record to new bucket
            ++h->buckets[newIndex].count;
            pthread_rwlock_unlock(&h->buckets[newIndex].lock);  // Unlock the target bucket
        }
        free(oldBuckets[i].records); // Free old records memory
        pthread_rwlock_unlock(&oldBuckets[i].lock);  // Unlock old bucket
    }
    h->bucketCount = newBucketCount;
    free(oldBuckets); // Free old buckets memory
    pthread_mutex_unlock(&h->resizeLock); // Release the lock
}
```
5. For flexible configuration, you can use a config file and parse it at runtime or provide options for users to modify these parameters in runtime. This depends on your specific requirements and usability considerations.

