["Here's how you can start solving this problem. This is a complex task that requires a lot of knowledge about C programming, concurrent programming, and memory management, especially in an environment like Linux where memory allocation is not deterministic due to virtual memory paging. 

```C
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

// Define the record structure
typedef struct {
    int value;
} record;

// Define the hash table node structure
typedef struct ht_node {
    int key;
    long offset;
    record *record;
    struct ht_node *next;
} ht_node;

// Define the hash table structure
typedef struct {
    atomic_int count;
    pthread_mutex_t lock;
    ht_node **nodes;
} hash_table;

hash_table* create_ht(int size) {
    // Allocate memory for the hash table
    hash_table *ht = malloc(sizeof(*ht));

    // Initialize mutex and count
    pthread_mutex_init(&ht->lock, NULL);
    atomic_init(&ht->count, 0);

    // Allocate memory for the hash table nodes
    ht->nodes = calloc(sizeof(ht_node*), size);

    return ht;
}

void destroy_ht(hash_table *ht) {
    // Destroy all nodes in the hash table and free their memory
    for (int i = 0, len = atomic_load(&ht->count); i < len; ++i) {
        if (!ht->nodes[i]) continue;

        ht_node *tmp;

        // Lock the node while freeing its memory
        pthread_mutex_lock(&ht->nodes[i]->lock);

        while (ht->nodes[i]) {
            tmp = ht->nodes[i];
            ht->nodes[i] = tmp->next;

            // Free the record memory first, as it's at a different location than the node itself
            free(tmp->record);
            free(tmp);
        }

        pthread_mutex_unlock(&ht->nodes[i]->lock);
    }

    // Destroy and free the hash table's mutex and its nodes memory
    pthread_mutex_destroy(&ht->lock);
    free(ht->nodes);
    free(ht);
}
```

This is just a start to solving this problem. It demonstrates how to create, and destroy a hash table structure with mutually exclusive locks on each node in the hash table for thread safety. More code would be required to implement adding entries to the table, searching for keys, etc. Note that due to the complexity of this task, I recommend dividing it into multiple smaller tasks and tackling them one at a time.
