    public async Task<IDataReader> ExecuteSqlCommandAsync(List<int> values, MySqlConnection connection, string sqlQuery)
    {
        // Create a parameterized SQL command with the initialized array of records
        var command = new MySqlCommand(sqlQuery, connection);

        // Add parameters to the command using random 'int' values from each record
        for (var i = 0; i < values.Count(); i++)
        {
            command.Parameters.AddWithValue("@p" + i, values[i]);
        }

        // Execute the SQL command and return IDataReader asynchronously
        if(connection.State == ConnectionState.Closed)
           await connection.OpenAsync();

        return await command.ExecuteReaderAsync(); 
    }

    private string DecryptMessage(string base64EncodedString, byte[] key, byte[] iv)
    {
        // Convert the Base64-encoded string back to bytes
        var encryptedBytes = Convert.FromBase64String(base64EncodedString);

        using (var tripleDesCryptoProvider = new TripleDESCryptoServiceProvider())
        {
            tripleDesCryptoProvider.Key = key;
            tripleDesCryptoProvider.IV = iv;

            var decrypter = tripleDesCryptoProvider.CreateDecryptor();

            // Decrypt the encrypted bytes and return a string
            var decryptedBytes = decrypter.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }
}
