typedef struct data_struct {
    long* offsets;
    int* keys;
    record_t* records;
    // Additional structures for tracking key frequencies go here
    pthread_mutex_t lock;
} data_struct_t;

data_struct_t* allocate(int num_elements) {
    data_struct_t *data = malloc(sizeof(data_struct_t));
    if (data == NULL) {
        return NULL;
    }

    data->offsets = malloc(num_elements * sizeof(long));
    if (data->offsets == NULL) {
        free(data);
        return NULL;
    }

    data->keys = malloc(num_elements * sizeof(int));
    if (data->keys == NULL) {
        free(data->offsets);
        free(data);
        return NULL;
    }

    data->records = malloc(num_elements * sizeof(record_t));
    if (data->records == NULL) {
        free(data->keys);
        free(data->offsets);
        free(data);
        return NULL;
    }

    pthread_mutex_init(&data->lock, NULL);
    // Initialize other structures for tracking key frequencies here

    return data;
}

void populate(data_struct_t *data, int num_elements, int min, int max) {
    srand(time(NULL));

    for (int i = 0; i < num_elements; ++i) {
        // Ensure uniqueness of keys
        do {
            data->keys[i] = rand() % (max - min + 1) + min;
        } while (is_duplicate(data, data->keys[i], i));

        data->records[i].value = data->keys[i];
    }
}

int is_duplicate(data_struct_t *data, int key, int current) {
    for (int i = 0; i < current; ++i) {
        if (data->keys[i] == key) {
            return 1;
        }
    }

    return 0;
}

void release_memory(data_struct_t *data) {
    pthread_mutex_lock(&data->lock);

    free(data->records);
    free(data->keys);
    free(data->offsets);
    // Free memory for other structures here

    pthread_mutex_unlock(&data->lock);
    pthread_mutex_destroy(&data->lock);
    free(data);
}
```
