// A node in the linked list
typedef struct Node {
    Record record;
    struct Node* next;
} Node;

Node* create_linked_list() {
    Node *head = NULL, *tail = NULL;

    for (long i = 0; i < MAX_RECORDS; i++) {
        // Allocate memory for a new node
        Node* new_node = (Node*) malloc(sizeof(Node));

        if (new_node == NULL) {
            printf("Failed to allocate memory.\n");
            break;
        }

        // Assign values to the record inside the node
        new_node->record.offset = i;
        new_node->record.key = hash_function(i);  // Implement this
        new_node->record.value = 0;
        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    return head;
}

void delete_linked_list(Node* head) {
    Node *current, *tmp;

    current = head;
    while (current != NULL) {
        tmp = current->next;

        free(current);
        current = tmp;
    }
}

void modify_record(Node* node, int new_value) {
    if (node == NULL || node->record.offset >= MAX_RECORDS 
                        || node->record.key != hash_function(node->record.offset)) {
        printf("Invalid record.\n");
        return;
    }

    node->record.value = new_value;
}
