In C:
```c
#include <stdio.h>
#include <string.h>
#include <curl/curl.h>

typedef void (*CallbackFunction)(char* data, size_t len);

size_t writeData(void *ptr, size_t size, size_t nmemb, void *stream) {
    size_t realSize = size * nmemb;

    CallbackFunction callback = (CallbackFunction)(*(long*)stream);
    (*callback)((char*)ptr, realSize);

    return realSize;
}

void networkDataFetcher(char* url, int buffer_size, CallbackFunction callback) {
    CURL *curl;
    FILE *fp;

    curl = curl_easy_init();

    if (curl) {
        fp = fopen("/dev/null", "wb");
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeData);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)callback);
        curl_easy_perform(curl);

        /* Always cleanup */
        curl_easy_cleanup(curl);
        fclose(fp);
    }
}
```
In Python:
```python
def streamingDataProcessor(data_stream, process_function, error_callback):
    processed_results = []

    for chunk in data_stream:
        try:
            processed_result = process_function(chunk)
            processed_results.append(processed_result)
        except Exception as e:
            error_callback(chunk, str(e))

    return processed_results
```
Remember to install libcurl and python3-pip before running this code by typing the following command in your terminal: `sudo apt-get install libcurl4-gnutls-dev python3-pip`. Then install pycurl module for python using the command: `pip3 install pycurl`.
