event_t* create_events(long epoch, size_t count) {
    // Allocate memory for the whole array in one go
    event_t *events = malloc(count * sizeof(event_t));

    if (events == NULL) {
        return NULL;  // Out of memory error
    }

    const char* descriptions[] = {"Event1", "Event2", "Event3"};  // List of predefined events
    srand(time(NULL));  

    for (size_t i = 0; i < count; ++i) {
        size_t index = rand() % (sizeof(descriptions) / sizeof(char*));

        // Duplicate the string to ensure it doesn't get deallocated
        events[i].description = strdup(descriptions[index]);

        if (events[i].description == NULL) {
            return NULL;  // Out of memory error
        }

        events[i].timestamp = epoch + i;  
    }

    return events;
}
```
