```csharp
using System;
using System.Threading;
using System.Collections.Concurrent;
using BoostLibrary; // Assuming there is a Boost library available

public class DynamicRandomGenerator
{
    private Random rand = new Random();
    private ConcurrentDictionary<int, int> distributionData = new ConcurrentDictionary<int, int>();
    private readonly object syncLock = new object();
    private int seed;

    public DynamicRandomGenerator() 
    {
        this.seed = 0;
    }

    // Methods to generate random integers and floats with specified ranges
    public int Next(int minValue, int maxValue, bool isInclusive = true) 
    {
        if (maxValue < minValue) throw new ArgumentOutOfRangeException("maxValue", "maxValue must be greater than or equal to minValue");

        lock(syncLock)
        {
            rand = new Random(seed); // create a new random object with the current seed value
            int result;

            if (isInclusive)
                result = rand.Next(minValue, maxValue + 1);
            else
                result = rand.Next(minValue, maxValue);

            distributionData.AddOrUpdate(result, 1, (key, oldValue) => oldValue + 1); // update the statistics data for logging purposes

            return result;
        }
    }

    public double NextDouble(double minValue, double maxValue, bool isInclusive = true) 
    {
        if (maxValue < minValue) throw new ArgumentOutOfRangeException("maxValue", "maxValue must be greater than or equal to minValue");

        lock(syncLock)
        {
            rand = new Random(seed); // create a new random object with the current seed value
            double result;

            if (isInclusive)
                result = minValue + rand.NextDouble() * (maxValue - minValue);
            else
                result = minValue + rand.NextDouble() * (maxValue - minValue + 0.1);

            distributionData.AddOrUpdate((int)(result*100), 1, (key, oldValue) => oldValue + 1); // update the statistics data for logging purposes

            return result;
        }
    }

    public void SetSeed(int seed) 
    {
        this.seed = seed;
    }

    public void ResetSeed() 
    {
        this.seed = 0;
    }

    // Implement the Sandesh client to send a sequence of random numbers to a server using a POST request
}
```
