#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    char key[20];
    double timestamp;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} pool;

pool* createPool(size_t initialSize) {
    pool* newPool = malloc(sizeof(pool));
    if (newPool == NULL) return NULL;  // Error check memory allocation

    newPool->offsets = malloc(initialSize * sizeof(long));
    newPool->keys = malloc(initialSize * sizeof(int));
    newPool->records = malloc(initialSize * sizeof(record*));
    if (newPool->offsets == NULL || newPool->keys == NULL || newPool->records == NULL) return NULL;  // Error check memory allocation

    newPool->capacity = initialSize;
    newPool->size = 0;
    pthread_mutex_init(&newPool->lock, NULL);

    srand(time(NULL));
    for (int i = 0; i < initialSize; ++i) {  // Initialize with random values
        newPool->offsets[i] = rand();
        newPool->keys[i] = rand();
        newPool->records[i] = malloc(sizeof(record));
        if (newPool->records[i] == NULL) return NULL;  // Error check memory allocation

        newPool->records[i]->value = rand();
        sprintf(newPool->records[i]->key, "key%d", i);
        newPool->records[i]->timestamp = (double)time(NULL);
    }

    return newPool;
}
```
