```c
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int value;
} Record;

typedef struct data_t {
    long* offsets;
    int* keys;
    Record* records;
    pthread_mutex_t lock;
} Data;

Data* manage_data(int offset_size, int key_size, int value_range_start, int value_range_end) {
    if (offset_size <= 0 || key_size <= 0 || value_range_start > value_range_end) {
        return NULL;
    }

    Data* data = malloc(sizeof(Data));
    if (data == NULL) {
        return NULL;
    }

    // allocate memory for the arrays, initialize offsets to 0 and keys to unique sequential values
    data->offsets = calloc(offset_size, sizeof(long));
    data->keys = malloc(key_size * sizeof(int));
    data->records = malloc(key_size * sizeof(Record));

    if (data->offsets == NULL || data->keys == NULL || data->records == NULL) {
        free(data->offsets);
        free(data->keys);
        free(data->records);
        free(data);
        return NULL;
    }

    // initialize keys array with unique sequential values within the range of [0, key_size - 1]
    for (int i = 0; i < key_size; ++i) {
        data->keys[i] = i % key_size;
    }

    // initialize record values to random numbers in the provided range
    for (int i = 0; i < key_size; ++i) {
        int value = rand() % (value_range_end - value_range_start + 1) + value_range_start;
        data->records[i].value = value;
    }

    // initialize the mutex for thread safety
    pthread_mutex_init(&data->lock, NULL);

    return data;
