```csharp
using System;
using System.Threading;

public class DynamicValueGenerator
{
    private int minValue, maxValue;
    private Random random;

    // For logging
    private long floatGenerationCount = 0;
    private long integerGenerationCount = 0;

    public DynamicValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value can't be greater than Max Value");

        this.minValue = minValue;
        this.maxValue = maxValue;

        // Create a new instance of Random with the current time as seed to ensure uniqueness across calls
        random = new Random();
    }

    public float GenerateRandomFloat(bool inclusive)
    {
        Interlocked.Increment(ref floatGenerationCount);

        if (inclusive)
            return (float)(minValue + (random.NextDouble() * (maxValue - minValue)));
        else
            return (float)(minValue + (random.NextDouble() * (maxValue - minValue + 1e-30)));
    }

    public int GenerateRandomInt(bool inclusive)
    {
        Interlocked.Increment(ref integerGenerationCount);

        return random.Next(minValue, inclusive ? maxValue : (maxValue - 1));
    }

    // We need to synchronize this operation to prevent inconsistencies during concurrent modifications of the range
    public void UpdateRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value can't be greater than Max Value");

        lock(this)
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public void RefreshState()
    {
        // Here we could potentially synchronize with external data sources if needed

        lock(this)
        {
            random = new Random();
        }
    }

    public void LogStats()
    {
        Console.WriteLine("Float Generation Count: " + floatGenerationCount);
        Console.WriteLine("Integer Generation Count: " + integerGenerationCount);
    }
}
```
