    char key[20];
    double timestamp;
} Record;

Record* records = NULL;
int num_records = 0;
int max_size = 1000; // You can set this to any number you want
pthread_mutex_t lock; 

void init(void) {
    srand((unsigned int)time(NULL)); // Initialize the random seed
    pthread_mutex_init(&lock, NULL);
}

int getRandomValue(int min, int max) {
    return rand() % (max - min + 1) + min; 
}

void* createRecord(void* arg) {
    // Lock to avoid data races
    pthread_mutex_lock(&lock);

    if (num_records >= max_size) {
        printf("Memory limit reached.\n");
        return NULL;
    }

    Record newRecord;
    newRecord.value = getRandomValue(0, 100); // Adjust these values as needed for your use case

    // Populate other fields of the record...

    records[num_records++] = newRecord;

    printf("Created record with value: %d\n", newRecord.value);

    pthread_mutex_unlock(&lock); // Unlock after modifying data

    return NULL;
}
```
In this code, we use POSIX threads to ensure thread safety when creating records. We also use a mutex (`pthread_mutex_t lock`) to protect against race conditions where two or more threads could attempt to modify `records` simultaneously. When a new record is created, it's added to the `records` array and the total number of records (`num_records`) is incremented atomically.

