['Here is a sample implementation of your request in C#. This uses `ThreadStatic` to maintain separate random generators for each thread, ensuring thread safety. 

```csharp
using System;
using System.Text.Json; // For serialization
using System.Collections.Concurrent; // For thread-safe operations
using System.Threading; // For ThreadStatic

public class CustomRandomGenerator
{
    private int min, max;
    private bool isExclusive;

    [ThreadStatic]
    private static Random random;
    private object seedLock = new object();
    private long seed;

    public CustomRandomGenerator(long customSeed = 0) 
    {
        this.min = int.MinValue;
        this.max = int.MaxValue;
        this.isExclusive = false;
        SetSeed(customSeed);
    }

    public void SetSeed(long customSeed) 
    {
        lock (seedLock)
        {
            seed = customSeed == 0 ? Guid.NewGuid().GetHashCode() : customSeed;
            random = new Random((int)seed);
        }
    }

    public int NextInt(bool isExclusiveRange = false) 
    {
        if (random == null) throw new InvalidOperationException("The generator's seed has not been set.");

        return random.Next(min + Convert.ToInt32(isExclusiveRange), max - Convert.ToInt32(isExclusiveRange));
    }

    public double NextDouble(bool isExclusiveRange = false) 
    {
        if (random == null) throw new InvalidOperationException("The generator's seed has not been set.");

        return random.NextDouble() * (max - min - Convert.ToInt32(isExclusiveRange)) + min + Convert.ToInt32(!isExclusiveRange);
    }

    public void SetRange(int min, int max) 
    {
        if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        this.min = min;
        this.max = max;
    }

    public override string ToString() 
    {
        return $"Range: [{min}, {max}], Seed: {seed}";
    }

    private class GeneratorState 
    {
        public int Min { get; set; }
        public int Max { get; set; }
        public long Seed { get; set; }
    }

    public string SaveState() 
    {
        var state = new GeneratorState {Min = min, Max = max, Seed = seed};

        return JsonSerializer.Serialize(state);
    }

    public void LoadState(string serializedState) 
    {
        var state = JsonSerializer.Deserialize<GeneratorState>(serializedState);

        this.min = state.Min;
        this.max = state.Max;
        SetSeed(state.Seed);
    }
}
```

This class uses `ThreadStatic` to maintain separate random generators for each thread, ensuring thread safety. It also provides methods for setting and saving a custom seed for reproducibility, as well as setting the range of generated values. The `ToString()` method displays the current state of the generator. 

Please note that this is a basic implementation, and further optimizations could be made according to your specific needs and requirements.
']

