public class FlexibleRandomGenerator {
    private static int seed = Environment.TickCount;
    [ThreadStatic] 
    private static Random randomLocal;

    public FlexibleRandomGenerator() {
        var tempSeed = Interlocked.Increment(ref seed);
        randomLocal = new Random(tempSeed);
    }

    public void ResetSeed() {
        var tempSeed = Interlocked.Exchange(ref seed, Environment.TickCount);
        randomLocal = new Random(tempSeed);
