["Here's a basic example of how you might implement this in C. This is simplified, as the exact details would depend on your specific requirements and constraints. It includes the creation and destruction of these entities, but does not include the actual manipulation or access of them (which could be more complex depending on what kind of operations you need to support).

This code uses a simple linked list for managing the geometric entities as this should provide good performance for insertions and deletions. It also uses a pthread mutex to ensure thread safety, allowing multiple threads to safely access and modify the collection concurrently.

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct vector {
    int x;
    int y;
    int z;
} Vector;

typedef struct geometry {
    double size;
    char* type;
    Vector* position;
} Geometry;

typedef struct node {
    Geometry* entity;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Geometry* createEntity(double size, const char* type, Vector* position) {
    Geometry* entity = malloc(sizeof(Geometry));
    if (entity == NULL) return NULL;

    entity->size = size;
    entity->type = strdup(type);
    if (entity->type == NULL) {
        free(entity);
        return NULL;
    }

    entity->position = malloc(sizeof(Vector));
    if (entity->position == NULL) {
        free(entity->type);
        free(entity);
        return NULL;
    }
    memcpy(entity->position, position, sizeof(Vector));

    return entity;
}

void destroyEntity(Geometry* entity) {
    if (entity != NULL) {
        free(entity->type);
        free(entity->position);
        free(entity);
    }
}

int addEntity(double size, const char* type, Vector* position) {
    pthread_mutex_lock(&lock);

    Geometry* entity = createEntity(size, type, position);
    if (entity == NULL) {
        pthread_mutex_unlock(&lock);
        return -1;  // Failed to allocate memory.
    }

    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        destroyEntity(entity);
        pthread_mutex_unlock(&lock);
        return -1;  // Failed to allocate memory.
    }
    node->entity = entity;

    node->next = head;
    head = node;

    pthread_mutex_unlock(&lock);
    return 0;  // Success.
}

void removeEntity(Geometry* entity) {
    pthread_mutex_lock(&lock);

    Node** indirect = &head;
    while (*indirect != NULL) {
        if ((*indirect)->entity == entity) {
            Node* node = *indirect;
            *indirect = node->next;
            destroyEntity(node->entity);
            free(node);
            break;
        }
        indirect = &(*indirect)->next;
    }

    pthread_mutex_unlock(&lock);
}
```
This code does not include logging, error handling or a full memory management strategy. Also note that this is a simple example and will not cover all potential issues such as fragmentation, reallocation etc. In a real-world scenario, you would want to use more sophisticated data structures like B-Trees for the geometric entities depending on your specific requirements (e.g., if you need to frequently insert or remove elements anywhere but the end of the list).
