    pthread_mutex_lock(&q->lock);

    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) return -1; // Out of memory.

    new_node->key = key;
    new_node->offset = offset;
    new_node->next = NULL;

    if (q->tail != NULL) {
        q->tail->next = new_node;
    } else {
        q->head = new_node;
    }

    q->tail = new_node;

    pthread_mutex_unlock(&q->lock);
    return 0; // Success.
}

// Dequeue an item from the queue and insert it into the hash table.
void* dequeue(Queue *q, HashTable *ht) {
    pthread_mutex_lock(&q->lock);

    if (q->head == NULL) return NULL; // Queue is empty.

    Node *node = q->head;
    q->head = node->next;

    if (q->head == NULL) {
        q->tail = NULL;
    }

    pthread_mutex_unlock(&q->lock);

    hash_table_insert(ht, node->key, node->offset); // Insert into the hash table.

