    private static readonly IMetricFamily<IHistogram> Latency = Metrics
        .CreateHistogram("network_latency", "Help text");

    private static Dictionary<string, int[]> configuration;
    private static bool isDisposed = false;
    private CancellationTokenSource cancellationTokenSource = new CancellationTokenSource();

    public NetworkHealthMonitor()
    {
        try 
        {
            var path = ConfigurationManager.AppSettings["ConfigurationFile"];

            if (string.IsNullOrEmpty(path)) throw new Exception("Configuration file not found.");

            using (StreamReader reader = new StreamReader(path))
            {
                string json = reader.ReadToEnd();
                configuration = JsonConvert.DeserializeObject<Dictionary<string, int[]>>(json);
            }
        } 
        catch (Exception) 
        {
            throw; // Handle exception as per your requirements
        }
    }

    public void StartMonitoring()
    {
        while (!cancellationTokenSource.IsCancellationRequested)
        {
            var interfaces = NetworkInterface.GetAllNetworkInterfaces();

            foreach (var networkInterface in interfaces)
            {
                // Simulate high latency and packet loss for testing purposes
                var metrics = GetSimulatedMetrics(networkInterface); 

                Latency.WithLabels(metrics).Observe(networkInterface.Speed / metrics[1]);
            }
        }
    }

