    public override string ToString() => $"Configuration: {JsonConvert.SerializeObject(configuration)}";

    // Simulates different conditions such as high latency and packet loss
    private int[] GetSimulatedMetrics(NetworkInterface networkInterface)
    {
        var threshold = configuration[networkInterface.Name];
        var rnd = new Random();

        return new [] 
        {
            rnd.Next(threshold[0], threshold[1]), // Simulate latency
            rnd.Next(threshold[2], threshold[3]) // Simulate packet loss
        };
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!isDisposed)
        {
            if (disposing) 
            {
                cancellationTokenSource.Dispose();
            }

            isDisposed = true;
        }
    }

    public void Dispose() => Dispose(true);
}
