["This is a complex task that involves multiple aspects of programming such as dynamic memory allocation, data structures, concurrency control, error handling, disk storage operations, data persistence, efficient data retrieval from hash tables, resizing policies, collision resolution strategies, exponential backoff, logging mechanisms and performance tuning. Here's an outline of how you might start implementing this function:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <math.h>

typedef struct {
    long offset;
    int key;
    double value;
} record_t;

// Hash table node structure
typedef struct ht_node {
   int key;
   long offset;
   double value;
   struct ht_node* next;
} ht_node_t;

// Function to allocate memory for an array and initialize it with random values
void init_array(long* offsets, int n1, long min1, long max1) {
    srand((unsigned) time(NULL));  // Seed the random number generator

    for (int i = 0; i < n1; ++i) {
        offsets[i] = rand() % (max1 - min1 + 1) + min1;
    }
}

void init_array(int* keys, int n2, long min2, long max2) {
    srand((unsigned) time(NULL));  // Seed the random number generator

    for (int i = 0; i < n2; ++i) {
        keys[i] = rand() % (max2 - min2 + 1) + min2;
    }
}

void init_array(double* values, int n3, double min3, double max3) {
    srand((unsigned) time(NULL));  // Seed the random number generator

    for (int i = 0; i < n3; ++i) {
        double range = max3 - min3;
        double div = RAND_MAX / range;
        values[i] = min3 + (rand() / div);
    }
}

// Function to initialize the hash table
void init_hashtable(ht_node_t** ht, int size) {
    for (int i = 0; i < size; ++i) {
        ht[i] = NULL;
    }
}

// Function to insert a key-value pair into the hash table
void hashtable_insert(ht_node_t** ht, int key, long offset, double value, pthread_mutex_t* lock) {
    // Acquire the lock before accessing the hash table
    pthread_mutex_lock(lock);

    // Calculate the index in the array for this key
    int index = abs(key % size);

    // Create a new node with the given key, offset and value
    ht_node_t* newNode = malloc(sizeof(ht_node_t));
    newNode->key = key;
    newNode->offset = offset;
    newNode->value = value;

    // Insert the new node at the head of the linked list in this index
    newNode->next = ht[index];
    ht[index] = newNode;

    // Release the lock after modifying the hash table
    pthread_mutex_unlock(lock);
}

// Function to retrieve a value from the hash table given a key
double hashtable_get(ht_node_t** ht, int key, long* offset, pthread_mutex_t* lock) {
    // Acquire the lock before accessing the hash table
    pthread_mutex_lock(lock);

    // Calculate the index in the array for this key
    int index = abs(key % size);

    // Search through the linked list in this index for the given key
    ht_node_t* node = ht[index];
    while (node != NULL) {
        if (node->key == key) {
            *offset = node->offset;

            // Release the lock before returning
            pthread_mutex_unlock(lock);
            return node->value;
        }

        node = node->next;
    }

    // If the key was not found, release the lock and return 0.0
    pthread_mutex_unlock(lock);
    return 0.0;
}
```

