typedef struct Record {
    int value;
} Record;

typedef struct HashTable {
    pthread_mutex_t lock;
    Record* table;
    long* offsets;
    size_t size;
    size_t count;
} HashTable;

HashTable createTable(size_t initialSize) {
    srand(time(0));
    HashTable ht = { PTHREAD_MUTEX_INITIALIZER, malloc(initialSize * sizeof(Record)), calloc(initialSize, sizeof(long)), initialSize, 0 };
    return ht;
}

void insert(HashTable* ht, int key, Record value) {
    pthread_mutex_lock(&ht->lock);

    if (((double) ht->count / ht->size) > 0.75) {
        resize(ht, ht->size * 2);
    }

    size_t index = key % ht->size;

    while (1) {
        if (ht->offsets[index] == -1) {
            ht->table[index] = value;
            ht->offsets[key] = index;
            ht->count++;
            break;
        }
        index = (index + 1) % ht->size;
    }

    pthread_mutex_unlock(&ht->lock);
}

Record* get(HashTable* ht, int key) {
    size_t index = key % ht->size;
    Record *result = NULL;
    while (1) {
        if (ht->offsets[index] == -1) break; // Empty slot found
        else if (ht->table[index].value == key) { // Found a match
            result = &ht->table[index];
            break;
        }
        index = (index + 1) % ht->size;
    }
    return result;
}
