using System;
using System.Collections.Concurrent;
using System.Linq;
using System.IO;
using Newtonsoft.Json;

public class DataPoint
{
    public DateTime Timestamp { get; set; }
    public double Value { get; set; }
    public string Status { get; set; }
}

public class DataProcessor
{
    private ConcurrentDictionary<DateTime, DataPoint> dataPoints = new ConcurrentDictionary<DateTime, DataPoint>();

    // Initialization
    public DataProcessor(ConcurrentBag<DataPoint> initialData)
    {
        if (initialData != null && initialData.Count > 0)
        {
            foreach (var data in initialData)
            {
                AddDataPoint(data);
            }
        }
    }

    private void AddDataPoint(DataPoint dataPoint)
    {
        if (!dataPoints.ContainsKey(dataPoint.Timestamp))
        {
            dataPoints[dataPoint.Timestamp] = dataPoint;
        }
        else
        {
            throw new ArgumentException("Duplicate timestamp");
        }
    }

    // Dynamic Range Filtering
    public IEnumerable<DataPoint> GetDataForTimeRange(DateTime from, DateTime to)
    {
        return dataPoints.Values.Where(x => x.Timestamp >= from && x.Timestamp <= to);
    }

    // Flexible Aggregation 
    public Dictionary<DateTime, double> ComputeAggregates(Func<IEnumerable<double>, double> aggregateFunction)
    {
        return dataPoints.GroupBy(x => x.Key.Date)
                         .ToDictionary(g => g.Key, g => aggregateFunction(g.Select(x => x.Value.Value)));
    }

    // Concurrency Management 
    public void UpdateDataPoint(DateTime timestamp, double newValue)
    {
        DataPoint dataPoint;
        if (dataPoints.TryGetValue(timestamp, out dataPoint))
        {
            dataPoint.Value = newValue;
        }
    }

    // Scalable Persistence 
    public void SerializeToFile(string filePath)
    {
        var jsonData = JsonConvert.SerializeObject(dataPoints);
        File.WriteAllText(filePath, jsonData);
    }

    public void DeserializeFromFile(string filePath)
    {
        var jsonData = File.ReadAllText(filePath);
        dataPoints = JsonConvert.DeserializeObject<ConcurrentDictionary<DateTime, DataPoint>>(jsonData);
    }
}
```
