["```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

typedef int OrderID_t;
typedef int CustomerID_t;
typedef double Price_t;

typedef struct {
    char* paymentMethod;
    double amountPaid;
} PaymentDetails_t;

typedef struct {
    char* itemName;
    Price_t price;
} OrderItem_t;

typedef struct OrderNode {
    OrderID_t orderId;
    CustomerID_t customerId;
    PaymentDetails_t *paymentDetails;
    OrderItem_t **orderItems;
    int itemCount;
    struct OrderNode* next;
} OrderNode_t;

typedef struct {
    OrderNode_t *head, *tail;
    pthread_mutex_t mutex;
    atomic_int size;
} OrderList_t;

OrderList_t orderList;

static void initPaymentDetails(PaymentDetails_t* paymentDetails, const char* method, double amount) {
    paymentDetails->paymentMethod = malloc(strlen(method) + 1);
    strcpy(paymentDetails->paymentMethod, method);
    paymentDetails->amountPaid = amount;
}

static void initOrderItem(OrderItem_t* orderItem, const char* name, Price_t price) {
    orderItem->itemName = malloc(strlen(name) + 1);
    strcpy(orderItem->itemName, name);
    orderItem->price = price;
}

static OrderNode_t* createOrderNode(OrderID_t orderId, CustomerID_t customerId, PaymentDetails_t *paymentDetails, OrderItem_t **orderItems, int itemCount) {
    OrderNode_t* node = malloc(sizeof(OrderNode_t));
    if (node == NULL) {
        return NULL; // handle memory allocation error
    }

    node->orderId = orderId;
    node->customerId = customerId;
    node->paymentDetails = paymentDetails;
    node->orderItems = orderItems;
    node->itemCount = itemCount;
    node->next = NULL;

    return node;
}

static OrderNode_t* findOrder(OrderList_t *list, OrderID_t orderId) {
    pthread_mutex_lock(&list->mutex); // lock critical section
    OrderNode_t *node = list->head;
    while (node != NULL && node->orderId != orderId) {
        node = node->next;
    }
    pthread_mutex_unlock(&list->mutex); // unlock critical section

    return node; // returns NULL if not found
}

static OrderNode_t* findOrderByCustomerID(OrderList_t *list, CustomerID_t customerId) {
    pthread_mutex_lock(&list->mutex); // lock critical section
    OrderNode_t *node = list->head;
    while (node != NULL && node->customerId != customerId) {
        node = node->next;
    }
    pthread_mutex_unlock(&list->mutex); // unlock critical section

    return node; // returns NULL if not found
}

void insertOrder(OrderList_t *list, OrderID_t orderId, CustomerID_t customerId, PaymentDetails_t *paymentDetails, OrderItem_t **orderItems, int itemCount) {
    OrderNode_t* newNode = createOrderNode(orderId, customerId, paymentDetails, orderItems, itemCount);

    if (newNode == NULL) {
        return; // handle memory allocation error
    }

    pthread_mutex_lock(&list->mutex); // lock critical section
    atomic_fetch_add(&list->size, 1);
    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }

    list->tail = newNode;
    pthread_mutex_unlock(&list->mutex); // unlock critical section
}

void updatePayment(OrderList_t *list, OrderID_t orderId, const char* method, double amount) {
    OrderNode_t* node = findOrder(list, orderId);

    if (node != NULL) {
        pthread_mutex_lock(&list->mutex); // lock critical section

        free(node->paymentDetails->paymentMethod);
        initPaymentDetails(node->paymentDetails, method, amount);

        pthread_mutex_unlock(&list->mutex); // unlock critical section
    }
}

void deleteOrder(OrderList_t *list, OrderID_t orderId) {
    if (atomic_load(&list->size) == 0) return;

    pthread_mutex_lock(&list->mutex); // lock critical section
    if (list->head != NULL && list->head->orderId == orderId) {
        OrderNode_t *temp = list->head;
        list->head = temp->next;

        free(temp->paymentDetails->paymentMethod);
        for (int i = 0; i < temp->itemCount; ++i) {
            free(temp->orderItems[i]->itemName);
        }
        free(temp->paymentDetails);
        free(temp->orderItems);
        free(temp);

        atomic_fetch_sub(&list->size, 1);
    } else {
        OrderNode_t *node = list->head;
        while (node != NULL && node->next != NULL) {
            if (node->next->orderId == orderId) {
                OrderNode_t* temp = node->next;
                node->next = temp->next;

                free(temp->paymentDetails->paymentMethod);
                for (int i = 0; i < temp->itemCount; ++i) {
                    free(temp->orderItems[i]->itemName);
                }
                free(temp->paymentDetails);
                free(temp->orderItems);
                free(temp);

                atomic_fetch_sub(&list->size, 1);
            } else {
                node = node->next;
            }
        }
    }

    if (atomic_load(&list->size) == 0) list->tail = NULL;

    pthread_mutex_unlock(&list->mutex); // unlock critical section
}

double getTotalSales(OrderList_t *list) {
    double total = 0.0;
    pthread_mutex_lock(&list->mutex); // lock critical section
    OrderNode_t* node = list->head;

    while (node != NULL) {
        for (int i = 0; i < node->itemCount; ++i) {
            total += node->orderItems[i]->price;
        }

        node = node->next;
    }

    pthread_mutex_unlock(&list->mutex); // unlock critical section

    return total;
}

void initOrderList(OrderList_t *list) {
    list->head = NULL;
    list->tail = NULL;
    atomic_init(&list->size, 0);
    pthread_mutex_init(&list->mutex, NULL);
}

void destroyOrderList(OrderList_t *list) {
    while (atomic_load(&list->size) > 0) deleteOrder(list, list->head->orderId);

    pthread_mutex_destroy(&list->mutex);
}
```python
