size_t poolSize = 0, capacity = 0, size = 0;

// Lock for synchronization 
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize(size_t poolSz, size_t arrayCap) {
    offsets = (long*)malloc(poolSz * sizeof(long));
    keys = (int*)calloc(poolSz, sizeof(int));

    if (!offsets || !keys) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    records = (Record*)malloc(arrayCap * sizeof(Record));
    if (!records) {
        printf("Memory allocation failed\n");
        free(offsets);
        free(keys);
        exit(1);
    }

    memset(records, 0, arrayCap * sizeof(Record));
    poolSize = poolSz;
    capacity = arrayCap;
    size = 0;
}

void insert(int key) {
    pthread_mutex_lock(&lock);

    if (size >= capacity) {
        Record* temp = (Record*)realloc(records, 2 * capacity * sizeof(Record));
        if (!temp) {
            printf("Memory allocation failed\n");
            free(offsets);
            free(keys);
            pthread_mutex_unlock(&lock);
            exit(1);
        }
        records = temp;
        capacity *= 2;
    }

    // Assuming a collision-resistant hash function for simplicity
    size_t index = key % poolSize;
    while (keys[index] != 0) {
        ++index;
        if (index >= poolSize) {
            index = 0;
        }
    }

    keys[index] = key;
    records[size].value = rand();  // Assigning random value, not thread-safe & secure seeding
    ++size;

    pthread_mutex_unlock(&lock);
}

void cleanup() {
    free(offsets);
    free(keys);
    free(records);
}
```
The `insert` function could be modified to handle concurrency, for example by using a lock. However, this would also require the implementation of additional synchronization mechanisms such as condition variables or semaphores depending on the exact requirements and usage pattern of the system. Also note that memory management is kept very simple for the sake of clarity in this answer, real-world applications will need to handle things like fragmentation, cache efficiency, etc. which are beyond scope of this question.
