['Implementing a full C program for this task would be quite extensive and complex as it involves dealing with many aspects like concurrency control, efficient memory management, BST operations etc. Here is a simplified example of how you could start implementing such function in C. This does not include the whole functionality but provides an idea about structuring your code and how to deal with some parts:

```C
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct event {
    unsigned long timestamp;
    int event_id;
    double priority;
} event;

typedef struct Node {
    pthread_mutex_t lock;
    event* e;
    struct Node* left;
    struct Node* right;
} Node;

Node* root = NULL; // global BST root node
pthread_mutex_t rootLock = PTHREAD_MUTEX_INITIALIZER; // lock for changing the root

// Function to allocate and initialize a new event
event* createEvent(int id, double priority) {
    event* e = malloc(sizeof(event));
    if (!e) return NULL;

    e->timestamp = time(NULL); // set timestamp to current system time
    e->event_id = id;
    e->priority = priority;

    return e;
}

// Function to insert an event into the BST
void insertEvent(Node** root, pthread_mutex_t* lock, event* e) {
    pthread_mutex_lock(lock); // locking here means only one thread can modify this subtree at a time

    if (*root == NULL) { 
        *root = malloc(sizeof(Node)); 
        (*root)->e = e; 
        (*root)->left = NULL; 
        (*root)->right = NULL; 
        pthread_mutex_init(&((*root)->lock), NULL); // initialize mutex for new node
    } else if (e->timestamp < (*root)->e->timestamp) {
        insertEvent(&((*root)->left), &(*root)->lock, e);
    } else if (e->timestamp > (*root)->e->timestamp) {
        insertEvent(&((*root)->right), &(*root)->lock, e);
    }

    pthread_mutex_unlock(lock); // unlocking here allows other threads to modify this subtree
}

// Function to deallocate all memory when exiting the function
void destroyBST(Node* root) {
    if (root != NULL) {
        destroyBST(root->left);
        destroyBST(root->right);
        free(root->e);
        pthread_mutex_destroy(&(root->lock)); // destroy mutex for this node before freeing it
        free(root);
    }
}
```
