} OffsetsKeysValues;

OffsetsKeysValues* allocateMemory(size_t size, long initValue) {
    OffsetsKeysValues *okv = malloc(sizeof(OffsetsKeysValues));
    if (!okv) return NULL;

    okv->offsets = calloc(size, sizeof(long));
    if (!okv->offsets) { free(okv); return NULL; }
    memset(okv->offsets, initValue, size * sizeof(long));

    okv->keys = malloc(size * sizeof(int));
    if (!okv->keys) { free(okv->offsets); free(okv); return NULL; }
    for (size_t i = 0; i < size; ++i)
        okv->keys[i] = i; // or whatever you want to calculate keys based on indices

    okv->values = malloc(size * sizeof(int*));
    if (!okv->values) { free(okv->offsets); free(okv->keys); free(okv); return NULL; }
    for (size_t i = 0; i < size; ++i) {
        okv->values[i] = malloc(sizeof(int));
        if (!okv->values[i]) {
            // clean up if any allocation fails
            for (size_t j = 0; j < i; ++j) free(okv->values[j]); 
            free(okv->offsets); free(okv->keys); free(okv);
            return NULL;
        }
        *okv->values[i] = rand(); // assign a random value
    }

    return okv;
}

void deallocateMemory(OffsetsKeysValues *okv, size_t size) {
