        std::map<int, int> attacks = {{1, 70}, {2, 50}, {3, 80}, {4, 60}};

        std::uniform_int_distribution<> dis(1, 4); // attack distribution
        auto now = std::chrono::system_clock::now();

        while (true) {
            int selectedAttack = dis(gen);

            if (cooldowns[selectedAttack] <= now && attempts[selectedAttack] < 3) { // attack has not cooled down and can be tried
                cooldowns[selectedAttack] = now + std::chrono::seconds(getCooldownForAttack(selectedAttack));
                attempts[selectedAttack] += 1;

                if (rollSuccess(attacks[selectedAttack])) { // attack was successful
                    successStreak++;

                    if (successStreak >= 5) { // boost attack power if 5 successive attacks are successful
                        increaseAttackPower();
                        successStreak = 0;
                    }
                } else {
                    successStreak = 0;
                }

                return selectedAttack;
            } else { // cooldown has not finished or maximum attempts reached, select another attack
                continue;
            }
        }
    }

private:
    int getCooldownForAttack(int attack) {
        switch (attack) {
            case 1: return 10;
            case 2: return 15;
            case 3: return 8;
            case 4: return 12;
            default: throw std::invalid_argument("Invalid attack number");
        }
    }

    bool rollSuccess(int successRate) {
        std::random_device rd;
        std::mt19937 gen(rd());

        std::uniform_int_distribution<> dis(0, 99); // distribution of numbers from 0-99

        return (dis(gen) < successRate); // returns true if the roll is less than the success rate
    }

    void increaseAttackPower() {
        attackPower *= 1.1; // increase attack power by 10% for each successful attack
    }

    std::map<int, std::chrono::system_clock::time_point> cooldowns; // maps attack number to next available time
    std::map<int, int> attempts; // maps attack number to current attempt count
    int successStreak = 0; // current successful attack streak
    double attackPower = 1.0; // current character attack power (1.0 is default)
};
```
Please note that this code is a simplified version and might not work correctly as the game environment becomes more complex, such as in a distributed network system or under high network latency conditions. Implementing such advanced features would require careful design and testing to ensure smooth operation even under these conditions.
