ConcurrentHashTable* newConcurrentHashTable() {
    ConcurrentHashTable *table = malloc(sizeof(ConcurrentHashTable));
    if (table == NULL) return NULL;

    table->offsets = calloc(INITIAL_SIZE, sizeof(long));
    table->keys = calloc(INITIAL_SIZE, sizeof(int));
    table->records = calloc(INITIAL_SIZE, sizeof(Record*));
    if (table->offsets == NULL || table->keys == NULL || table->records == NULL) {
        free(table->offsets);
        free(table->keys);
        free(table->records);
        free(table);
        return NULL;
    }
    table->size = INITIAL_SIZE;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void deleteConcurrentHashTable(ConcurrentHashTable *table) {
    for (size_t i = 0; i < table->count; ++i) {
        free(table->records[i]);
    }
    free(table->offsets);
    free(table->keys);
    free(table->records);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
