typedef struct Node {
    LogEntry data;
    pthread_mutex_t lock;  /* Mutex to ensure thread safety */
    struct Node* next;
} Node;

/* Linked list to store log entries */
Node* head = NULL;

pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER; /* Read-write lock for synchronization */

void addEntry(LogEntry entry) {
    Node* newNode = (Node*) malloc(sizeof(Node)); 

    if (newNode == NULL) {
        // Log error and return or handle as appropriate
    } else {
        pthread_mutex_init(&(newNode->lock), NULL); /* Initialize the mutex */

        newNode->data = entry; 
        newNode->next = head; 

        pthread_rwlock_wrlock(&rwlock);
        head = newNode;
        pthread_rwlock_unlock(&rwlock);
    }
}

LogEntry getEntry(int index) {
    Node* current = head;
    int i = 0;

    pthread_rwlock_rdlock(&rwlock);
    while (current != NULL && i < index) {
        current = current->next;
        i++;
    }

    if(i == index)
        return current->data;  /* Return the log entry */

    pthread_rwlock_unlock(&rwlock);
}
