```c
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

// 节点定义
typedef struct CacheEntry {
    char *request_id;
    char *response_body;
    time_t expiration_time;
    int hit_count, miss_count;
    struct CacheEntry *next;
} CacheEntry;

// 链式哈希表定义
typedef struct HashTable {
    pthread_mutex_t lock;
    CacheEntry **buckets;
    size_t num_buckets, entries;
} HashTable;

HashTable *create_hash_table(size_t num_buckets) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->num_buckets = num_buckets;
    ht->entries = 0;
    ht->buckets = calloc(num_buckets, sizeof(CacheEntry *));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

size_t hash(const char *s) {  // 简单的哈希函数
    size_t hash = 5381;
    int c;

    while ((c = *s++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % ht->num_buckets;
}

// 插入操作，使用链式处理冲突
void insert(HashTable *ht, const char *request_id, const char *response_body) {
    pthread_mutex_lock(&ht->lock);

    size_t index = hash(request_id);
    CacheEntry *entry = malloc(sizeof(CacheEntry));
    entry->request_id = strdup(request_id);
    entry->response_body = strdup(response_body);
    entry->next = ht->buckets[index];
    ht->entries++;

    pthread_mutex_unlock(&ht->lock);
}

// 查找操作，使用链式处理冲突
CacheEntry *find(HashTable *ht, const char *request_id) {
    size_t index = hash(request_id);

    pthread_mutex_lock(&ht->lock);

    CacheEntry *entry;
    for (entry = ht->buckets[index]; entry != NULL && strcmp(entry->request_id, request_id) != 0;
         entry = entry->next);

    pthread_mutex_unlock(&ht->lock);

    return entry;
}
```
