    Geometry** geometries;
    size_t geometryCount;
} SharedData;

SharedData* initializeMemory(size_t numPoints, size_t numGeometries) {
    SharedData* shared = malloc(sizeof(*shared));
    if (!shared) return NULL;  // handle allocation failure

    pthread_mutex_init(&shared->mutex, NULL);

    shared->points = calloc(numPoints, sizeof(Point));
    if (!shared->points) {
        free(shared);
        return NULL;  // handle allocation failure
    }

    shared->pointCount = numPoints;

    shared->geometries = malloc(numGeometries * sizeof(Geometry*));
    if (!shared->geometries) {
        free(shared->points);
        free(shared);
        return NULL;  // handle allocation failure
    }

    for (size_t i = 0; i < numGeometries; ++i) {
        shared->geometries[i] = malloc(sizeof(Geometry));
        if (!shared->geometries[i]) {
            // clean up allocated memory and return on failure
            for (--i; i >= 0; --i) free(shared->geometries[i]);
            free(shared->points);
            free(shared);
            return NULL;  // handle allocation failure
        }
    }

    shared->geometryCount = numGeometries;

    return shared;
}

void cleanupMemory(SharedData* shared) {
    if (shared) {
        pthread_mutex_destroy(&shared->mutex);

        for (size_t i = 0; i < shared->geometryCount; ++i) {
            free(shared->geometries[i]->name);
            free(shared->geometries[i]);
        }
        free(shared->geometries);

        free(shared->points);

        free(shared);
    }
}
``` 
Please note, this is a very basic implementation and doesn't cover all aspects requested (for example, error handling when resizing arrays). It also doesn't demonstrate thread safety. For such complex scenarios, consider using more mature libraries or languages that have better support for multithreading and memory management.
