Firstly, let's implement the hash table. We will use separate chaining for collision resolution. Here's a basic implementation:

```c
#include <stdlib.h>
#define TABLE_SIZE 10007 // a prime number

typedef struct node {
    int key;
    long offset;
    struct node *next;
} Node;

Node* hashTable[TABLE_SIZE];

// basic hash function
int hash(int key) {
    return key % TABLE_SIZE;
}

void insert(int key, long offset) {
    int index = hash(key);

    // create new node and initialize it
    Node *newNode = (Node*) malloc(sizeof(Node));
    newNode->key = key;
    newNode->offset = offset;
    newNode->next = NULL;

    // insert at head of linked list
    newNode->next = hashTable[index];
    hashTable[index] = newNode;
}

long get(int key) {
    int index = hash(key);
    Node *node = hashTable[index];

    // search in the linked list for the key
    while (node != NULL) {
        if (node->key == key) {
            return node->offset;
        }
        node = node->next;
    }

    return -1;  // return a sentinel value indicating not found
}
```
This hash table supports quick lookups and insertions, while maintaining good performance even when there are many collisions due to the use of separate chaining. This is a simple implementation which doesn't take into account more complex factors like memory efficiency and handling varying data volumes.

