#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define MAX_RECORDS 1000 // define your own limit
#define MAX_BUFFER 256

typedef struct record {
    int value;
    double decimal;
    char buffer[MAX_BUFFER];
} Record;

Record *records[MAX_RECORDS]; // index map
int size = 0;

void add_record(int v, double d, const char *b) {
    if (size >= MAX_RECORDS) {
        printf("Error: Maximum number of records reached.\n");
        return;
    }

    Record *new_record = malloc(sizeof(Record));
    if (new_record == NULL) {
        printf("Memory allocation failed. Exiting...\n");
        exit(1);
    }

    new_record->value = v;
    new_record->decimal = d;
    strncpy(new_record->buffer, b, MAX_BUFFER - 1); // -1 to ensure space for null character

    records[size++] = new_record;
}

void process_records() {
    int i;

    // User input or predefined sources could be added here
    add_record(1, 2.0, "Hello, world!");
    add_record(2, 3.14, "This is a test.");

    for (i = 0; i < size; i++) {
        printf("Record %d: value=%d decimal=%.2lf buffer=\"%s\"\n", i+1, records[i]->value, records[i]->decimal, records[i]->buffer);
    }

    // Cleanup allocated memory
    for (i = 0; i < size; i++) {
        free(records[i]);
    }
}

int main() {
    process_records();
    return 0;
}
```
