['Here is a simple C function that should fulfill the requirements described in the task. It uses `malloc()`, `realloc()`, `free()` for dynamic memory management which are part of the C standard library. It also uses random number generation from the `stdlib.h` library to initialize the `record` structures with a random value between 0 and 1000.

```c
#include <stdio.h>
#include <stdlib.h>
#define MAX_OFFSETS 1000 // define your system-defined maximum limit here

typedef struct {
    int value;
} record;

int manageMemory(size_t offsetsCount, long **offsetsPtr, int **keysPtr, record ***recordsPtr) {
    if (offsetsCount > MAX_OFFSETS || offsetsCount % 2 != 0) {
        printf("Invalid input. Offsets count must be less than or equal to the system-defined maximum limit and an even number.\n");
        return -1;
    }

    *offsetsPtr = malloc(sizeof(long) * offsetsCount);
    if (*offsetsPtr == NULL) {
        printf("Out of memory. Could not allocate for offsets array.\n");
        return -1;
    }

    size_t keysCount = offsetsCount / 2;
    *keysPtr = malloc(sizeof(int) * keysCount);
    if (*keysPtr == NULL) {
        printf("Out of memory. Could not allocate for keys array.\n");
        free(*offsetsPtr);
        return -1;
    }

    *recordsPtr = malloc(sizeof(record*) * keysCount);
    if (*recordsPtr == NULL) {
        printf("Out of memory. Could not allocate for records array.\n");
        free(*offsetsPtr);
        free(*keysPtr);
        return -1;
    }

    srand(time(NULL)); // seed the random number generator
    for (size_t i = 0; i < keysCount; ++i) {
        (*recordsPtr)[i] = malloc(sizeof(record));
        if ((*recordsPtr)[i] == NULL) {
            printf("Out of memory. Could not allocate for record %zu.\n", i);
            // Free all previously allocated records and keys, then offsets
            for (--i; i > 0; --i) {
                free((*recordsPtr)[i]);
            }
            free(*keysPtr);
            free(*offsetsPtr);
            return -1;
        }
        (*recordsPtr)[i]->value = rand() % 1001; // random value between 0 and 1000
    }

    printf("Memory allocated successfully.\n");
    return 0;
}

void freeMemory(long *offsets, int *keys, record **records, size_t keysCount) {
    for (size_t i = 0; i < keysCount / 2; ++i) { // keysCount is always even
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}
```

This function takes in the number of offsets to allocate and three pointers by which it will return allocated memory for an array of long integers, an array of int integers (the keys), and an array of record structures. After allocation checks if any of these operations fail due to out-of-memory conditions and returns -1 in such cases. In case of success, the function fills in each `record` with a random number between 0 and 1000.

The second function, `freeMemory()`, takes in these allocated pointers and their count (which is always half of the count of offsets), frees up all previously allocated memory to avoid memory leaks.
']

