    pthread_rwlock_wrlock(&g_sessionLock); // Lock for writing

    if (g_numSessions >= g_capacity) {
        size_t newCapacity = g_capacity == 0 ? 16 : g_capacity * 2;
        UserSession** newArray = realloc(g_sessions, sizeof(UserSession*) * newCapacity);

        if (newArray == NULL) {
            pthread_rwlock_unlock(&g_sessionLock); // Unlock in case of error
            return;
        }

        g_capacity = newCapacity;
        g_sessions = newArray;
    }

    UserSession* session = malloc(sizeof(UserSession));
    session->userId = userId;
    session->sessionContext = sessionContext;

    g_sessions[g_numSessions++] = session;

    pthread_rwlock_unlock(&g_sessionLock); // Unlock after writing
}
