#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#define MAX_CACHE_SIZE 1024
#define MIN_CACHE_SIZE 64

typedef struct CacheNode {
    char* key;
    void* value;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct Cache {
    atomic_int size;
    pthread_mutex_t lock;
    CacheNode *head, *tail;
    int (*evictionPolicy)(struct Cache*, CacheNode*);
    void (*recoveryStrategy)(void*);
} Cache;

Cache cache;

// Initialize the cache system
int init(size_t size) {
    if (size > MAX_CACHE_SIZE || size < MIN_CACHE_SIZE) return -1; // error handling for invalid size

    atomic_init(&cache.size, size);
    pthread_mutex_init(&cache.lock, NULL);
    cache.head = cache.tail = NULL;
    cache.evictionPolicy = lruEvictionPolicy; // default policy
    cache.recoveryStrategy = gossipRecoveryStrategy; // default strategy

    return 0;
}

// Add a key-value pair to the cache system
void put(char* key, void* value) {
    pthread_mutex_lock(&cache.lock);

    if (atomic_load(&cache.size) == 0) resizeCache(); // dynamic resizing strategy

    CacheNode *node = malloc(sizeof(CacheNode));
    node->key = key;
    node->value = value;
    addToHead(node);  // least recently used policy

    pthread_mutex_unlock(&cache.lock);
}

// Retrieve a value from the cache system
void* get(char* key) {
    pthread_mutex_lock(&cache.lock);

    CacheNode *node = findNode(key); // search for key in linked list
    if (node == NULL) return NULL; 
    moveToHead(node); // update recently used policy

    pthread_mutex_unlock(&cache.lock);

    return node->value;
}
```
