['Implementing the described task would be a non-trivial task requiring a deep understanding of C programming, synchronization primitives, memory management, hash functions and more. Here is an outline of how such implementation might look like:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdatomic.h>

typedef struct {
    atomic_uint index;
    time_t timestamp;
    _Atomic(bool) updateFlag;
} Metadata;

typedef struct {
    int key;
    long offset;
    Metadata meta;
} Record;

typedef struct {
    Record* table;
    size_t capacity;
    atomic_size_t count;
    pthread_mutex_t lock;
} HashTable;

static unsigned long hash(int key, size_t capacity) {
    return ((unsigned long)key * 2654435761) % capacity;
}

HashTable* create_table(size_t initialCapacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->capacity = initialCapacity;
    table->count = 0;
    table->table = calloc(initialCapacity, sizeof(Record));

    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void resize(HashTable* oldTable, size_t newSize) {
    HashTable newTable = create_table(newSize);

    for (size_t i = 0; i < oldTable->capacity; ++i) {
        Record record = oldTable->table[i];
        if (record.key != 0) {
            size_t index = hash(record.key, newSize);

            while (newTable->table[index].key != 0) {
                index = (index + 1) % newSize;
            }

            newTable->table[index] = record;
        }
    }

    free(oldTable->table);
    *oldTable = newTable;
}
``` 
Please note that this is only a starting point and the actual implementation should include error checking, thread safety, efficient resizing logic, correct usage of pthread mutexes/condition variables for thread synchronization etc. Additionally, handling memory allocation and deallocation in an optimal way, ensuring cache locality, graceful degradation under high load conditions are highly dependent on specific use cases. They need to be carefully designed according to these factors.
