const fs = require('fs');
const cache = {};
let timeoutId = 0;

function readFileSyncWithCache(path) {
    if (cache[path] && Date.now() < cache[path].expiresAt) {
        return cache[path].data;
    } else {
        try {
            const data = fs.readFileSync(path, 'utf8');

            // Clear previous timeoutId before setting a new one to avoid multiple timeouts firing concurrently
            clearTimeout(timeoutId);

            cache[path] = {
                expiresAt: Date.now() + 60000,  // Cache for one minute (value in milliseconds)
                data,
            };

            timeoutId = setTimeout(() => delete cache[path], 60000); // Delete the entry after one minute

            return data;
        } catch(err) {
            console.error('Error reading file:', err);
        }
    }
}
```
