['Here's an implementation that uses a dynamic array (contiguous block) for efficient space usage. However, if you are frequently inserting elements at the front or in the middle, linked list might be a better choice.

```C
#include <stdio.h>
#include <stdlib.h>

typedef struct data {
    double d;
    int i;
    char c;
} Data;

Data* read_data(FILE *file, size_t *size) {
    Data *arr = NULL;
    *size = 0;

    while (1) {
        // Ensure space for one more element.
        arr = realloc(arr, (*size + 1) * sizeof(*arr));

        if (!fread(&arr[*size], sizeof(*arr), 1, file)) {
            if (feof(file)) {
                break;
            } else {
                // Handle IO error.
                perror("Error while reading file");
                free(arr);
                return NULL;
            }
        }

        (*size)++;
    }

    return arr;
}

void iterate_data(Data *arr, size_t size, void (*func)(const Data*)) {
    for (size_t i = 0; i < size; ++i) {
        func(&arr[i]);
    }
}

int main() {
    FILE *file = fopen("data.bin", "rb");  // Replace with actual file name.

    if (!file) {
        perror("Error while opening file");
        return EXIT_FAILURE;
    }

    size_t data_size;
    Data *data = read_data(file, &data_size);

    // Use the function to iterate over data.
    iterate_data(data, data_size, [](const Data* d) {
        printf("Double: %f, Integer: %d, Char: %c\n", d->d, d->i, d->c);
    });

    fclose(file);
    free(data);  // Don't forget to clean up the memory.
}
```

This code reads `struct data` elements from a binary file and stores them in a dynamic array. It handles potential I/O errors by checking the return value of `fread()`, returning NULL on error and freeing the allocated memory to avoid leaks. After reading all data, it prints each element using a user-provided function pointer. When done with the array, it frees the allocated memory to prevent memory leaks.
