```javascript
const fs = require('fs').promises;
const path = require('path');
const os = require('os');

class FileReader {
    constructor(directoryPath, batchSize) {
        this.directoryPath = directoryPath;
        this.batchSize = batchSize;
        this.filesRead = 0;
    }

    async readDirectory() {
        const files = await fs.readdir(this.directoryPath);
        for (let i = 0; i < files.length; i += this.batchSize) {
            const batchFiles = files.slice(i, i + this.batchSize);
            const filePromises = batchFiles.map((fileName) => {
                const filePath = path.join(this.directoryPath, fileName);
                return fs.readFile(filePath, 'utf-8');
            });

            try {
                this.filesRead += batchFiles.length;
                console.log(`${new Date().toISOString()} - Read ${batchFiles.length} files: ${batchFiles.join(', ')}`);
                return Promise.all(filePromises);
            } catch (error) {
                console.error(`Failed to read files: ${error}`);
                throw error;
            }
        }
    }
}
```
In the JavaScript component, we asynchronously read files from a specified directory using fs.promises and handle errors appropriately. The batching strategy is implemented for efficient concurrent file access. Each log entry provides detailed contextual information for each file read.

