['Here's a basic example to get you started on this problem. In this code, I use `mt19937` as the random number generator with locks to ensure thread-safety:

```C++
#include <random>
#include <mutex>
#include <stdexcept>

class DynamicRandomGenerator {
public:
    explicit DynamicRandomGenerator(unsigned int seed = std::mt19937::default_seed) : rng_(seed), lock_() {}

    void setSeed(unsigned int seed) {
        std::lock_guard<std::mutex> guard(lock_);
        rng_.seed(seed);
    }

    unsigned int getUInt32Rand(unsigned int from, unsigned int to) {
        if (to < from) throw std::invalid_argument("Invalid range");
        return getUniformDistribution<unsigned int>(from, to);
    }

    float getFloatRand(float from, float to) {
        if (!(to > from)) throw std::invalid_argument("Invalid range");
        return getUniformDistribution<float>(from, to);
    }

private:
    std::mt19937 rng_;
    mutable std::mutex lock_;

    template <typename T>
    T getUniformDistribution(T from, T to) {
        std::lock_guard<std::mutex> guard(lock_);
        return std::uniform_int_distribution<T>{from, to}(rng_);
    }
};
```

This is a very basic solution. Real-world usage would involve more intricate aspects and would require profiling and testing to find the best trade-offs between speed, reproducibility, memory efficiency etc. for each possible use case scenario. 

