    if(hashtable[bucketIndex] == NULL) {
        hashtable[bucketIndex] = newNode;
    } else {
        HashTableNode* currentNode = hashtable[bucketIndex];

        while(currentNode->next != NULL) {
            currentNode = currentNode->next;
        }

        currentNode->next = newNode;
    }
}

