```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
    char* string;
} Record;

void* init_records(void* arg) {
    // Split the data and calculate the range for this thread
    long start = ((long*)arg)[0];
    long end = ((long*)arg)[1];
    int* keys = (int*)arg[2];
    Record* records = (Record*)arg[3];

    // Initialize each record with a unique string and random value within range
    for (long i = start; i < end; ++i) {
        records[i].string = malloc(10);
        sprintf(records[i].string, "str%ld", i);

        // Random value within 500-1000 range
        records[i].value = 500 + rand() % (end - start + 1);
    }

    return NULL;
}

void create_records(int num_threads, int* keys, Record* records) {
    pthread_t threads[num_threads];
    long args[4];
    int range = sizeof(keys)/sizeof(keys[0]);

    // Calculate the workload for each thread and start it
    for (int i = 0; i < num_threads; ++i) {
        args[0] = i * range / num_threads;  // Start index
        args[1] = (i+1) * range / num_threads;  // End index
        args[2] = keys;  // Key array
        args[3] = records;  // Record array

        if(pthread_create(&threads[i], NULL, init_records, args)) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; ++i) {
        if(pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return;
        }
    }
}
```
