class RealTimeDataAnalyzer {
private:
    // For data thread safety
    std::mutex mtx;
    std::vector<record*> dataset;

    // Logger class to log operations, errors etc. 
    Logger logger;

public:
    RealTimeDataAnalyzer() {
        // Initialize the logger here
    }

    ~RealTimeDataAnalyzer() {
        reset();
    }

    void processDataset(std::function<void(record*)> analyzeFunction, 
                        bool parallel = true) {
        if (parallel) {
            // Use multithreading to speed up processing
            std::vector<std::thread> threads;

            for (auto& record : dataset) {
                threads.push_back(std::thread([&](){
                    mtx.lock();
                    analyzeFunction(record);
                    mtx.unlock();

                    // Log the operation
                    logger.logOperation("Analyze", record->timestamp);
                }));
            }

            for (auto& thread : threads) {
                if (thread.joinable()) {
                    thread.join();
                }
            }
        } else {
            // Use serial processing when not in parallel mode
            for (auto& record : dataset) {
                mtx.lock();
                analyzeFunction(record);
                mtx.unlock();

                logger.logOperation("Analyze", record->timestamp);
            }
        }
    }

    void reset() {
        for (auto& record : dataset) {
            delete record;
        }

        dataset.clear();
    }
};
