// Assume we have a hash table with open addressing and linear probing for collision resolution
typedef struct HashTable {
    Record* records;
    size_t size;
    pthread_mutex_t lock; // used to protect the hash table during concurrent access
} HashTable;

// Assume we have a helper function that initializes and returns a record with random value
Record init_record();

HashTable* create_hashtable(size_t size) {
    HashTable* ht = malloc(sizeof(HashTable));
    ht->records = calloc(size, sizeof(Record));
    ht->size = size;
    pthread_mutex_init(&ht->lock, NULL); // Initialize the lock

    for (int i = 0; i < size; i++) {
        ht->records[i] = init_record();
    }

    return ht;
}

void destroy_hashtable(HashTable* ht) {
    free(ht->records); // Free the array of records first 
    pthread_mutex_destroy(&ht->lock); // Destroy the lock
    free(ht); // Then, free the hash table itself
}
```
