// Define a custom synchronization mechanism using atomic operations.
struct CustomMutex {
    std::atomic<bool> locked{false};

    void lock() {
        bool expected = false;
        while(!locked.compare_exchange_weak(expected, true))
            expected = false;
    }

    void unlock() { 
        locked.store(false);
    }
};

// Define a memory pool for efficient memory management.
class MemoryPool {
public:
    MemoryPool(size_t size) : buffer(new char[size]), available(size){}
    ~MemoryPool() { delete[] buffer; }

    void* allocate(size_t bytes) {
        if (bytes > available.load()) 
            throw std::bad_alloc();
        return &buffer[available -= bytes];
    }

    void deallocate(size_t bytes) {
        available += bytes;
    }
private:
    char* buffer;
    std::atomic<size_t> available;
};

