            try {
                File cacheFile = new File(themeDirectory, fileName);
                Bitmap bitmap = BitmapFactory.decodeFile(cacheFile.getAbsolutePath());

                if (bitmap != null) {
                    if (themeCache == null) {
                        themeCache = Collections.synchronizedMap(new HashMap<>());
                    }

                    themeCache.put(fileName, bitmap);
                }
