ssize_t allocate_memory(size_t size) {
    void *ptr = malloc(size);

    if (ptr == NULL) {
        log_error("Memory allocation failed.");
        return -1;
    }

    memset(ptr, 0, size); // zero-fill memory for security

    return (ssize_t) ptr;
}

int main() {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJK...";
    const size_t charsetSize = sizeof(charset);

    ssize_t keyOffsetsPtr = allocate_memory(10 * sizeof(long)); // long for offsets
    ssize_t keysPtr = allocate_memory(10 * sizeof(int));        // int for keys
    ssize_t recordsPtr = allocate_memory(10 * sizeof(struct record));  // custom structs

    if (keyOffsetsPtr == -1 || keysPtr == -1 || recordsPtr == -1) {
      log_error("Memory allocation failed. Exiting...");
      return EXIT_FAILURE;
    }

    long *keyOffsets = (long *) keyOffsetsPtr;
    int *keys = (int *) keysPtr;
    struct record *records = (struct record *) recordsPtr;

    srand(time(NULL)); // initialize random seed 

    for (size_t i = 0; i < 10; ++i) {
        keyOffsets[i] = rand() % charsetSize;     // generate secure random offset
        keys[i] = rand();                        // generate secure random number
        records[i].value = rand();                // initialize record value
    }

    free((void *) keyOffsetsPtr);
    free((void *) keysPtr);
    free((void *) recordsPtr);

    return EXIT_SUCCESS;
}
