#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
    double measurement;
} record;

struct hash_table_entry {
    atomic_flag occupied = ATOMIC_FLAG_INIT;
    record rec;
};

typedef struct {
    size_t size;
    struct hash_table_entry* entries;
    pthread_rwlock_t lock;
} hash_table;

static unsigned long hash(int key, unsigned long mod) {
    return (unsigned int)(key % mod);
}

void init_hash_table(hash_table *ht, size_t initial_size) {
    ht->entries = calloc(initial_size, sizeof(*ht->entries));
    ht->size = initial_size;
    pthread_rwlock_init(&ht->lock, NULL);
}

int insert_entry(hash_table *ht, record rec) {
    unsigned long index;
    struct hash_table_entry* entry;

    for (unsigned long trial = 0; ; ++trial) {
        index = hash(rec.value, ht->size);
        entry = &ht->entries[index];

        if (!atomic_flag_test_and_set(&entry->occupied)) {
            break;
        } else if (trial % ht->size == 0) {
            resize_hash_table(ht, ht->size * 2);
        }
    }

    entry->rec = rec;
    return index;
}

void resize_hash_table(hash_table* ht, size_t new_size) {
    struct hash_table_entry* old_entries = ht->entries;
    size_t old_size = ht->size;

    init_hash_table(ht, new_size);
    for (size_t i = 0; i < old_size; ++i) {
        if (atomic_flag_test_and_set(&old_entries[i].occupied)) {
            insert_entry(ht, old_entries[i].rec);
            atomic_flag_clear(&old_entries[i].occupied);
        }
    }

    free(old_entries);
}

void* log_process_times(void *arg) {
    // logging code here
    return NULL;
}

int process_data(hash_table* ht, size_t data_size, double threshold, int min_value, int max_value) {
    clock_t start = clock();

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < data_size; ++i) {
        record rec = {
            .value = min_value + rand() % ((max_value + 1) - min_value),
            .offset = rand(),
            .measurement = (double)rand() / (double)RAND_MAX
        };

        if (rec.measurement >= threshold) {
            insert_entry(ht, rec);
        }
    }

    clock_t end = clock();
    double time_spent = (double)(end - start) / CLOCKS_PER_SEC;

    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, log_process_times, &time_spent)) {
        // error handling code here
        return 1;
    }

    if (pthread_join(log_thread, NULL)) {
        // error handling code here
        return 1;
    }

    return 0;
}
```
This is a simple example and you may want to expand upon this or add additional functionality depending on the specifics of your application. This function assumes that the hash table can fit within available memory, which may not be the case for very large datasets. You could implement resizing in chunks as opposed to doubling the size with each expansion.
']

