    let start_time = Instant::now();

    let mut mac_rx_arr: Vec<MAC_RX_FLOWINFO> = Vec::with_capacity(M);
    for _i in 0..M {
        // Dynamically allocate memory and initialize MAC_RX_FLOWINFO struct.
        let mut context_ptr: *mut L2_CONTEXT = mem::uninitialized();
        unsafe { ptr::write(context_ptr, 0); }
        mac_rx_arr.push(MAC_RX_FLOWINFO { tag: 0, flow_id: 0, context_ptr });
