['Here is how you can implement this in C#. Note that some parts of this code are just placeholders for illustrative purposes and real-world applications would require more comprehensive error handling, logging, and recovery mechanisms. 

```CSharp
using System;
using System.IO;
using System.Collections.Concurrent;
using System.Threading;

public class DataRecord
{
    public int Value { get; set; }
}

public class CustomHashTable<TKey, TValue> : IDisposable where TKey : struct where TValue : struct
{
    private ConcurrentDictionary<TKey, TValue> dictionary = new ConcurrentDictionary<TKey, TValue>();

    public void Add(TKey key, TValue value)
    {
        dictionary.TryAdd(key, value);
    }

    public bool TryGetValue(TKey key, out TValue value)
    {
        return dictionary.TryGetValue(key, out value);
    }

    public void Dispose()
    {
        // Clean up any unmanaged resources here
    }
}

public class DataLoader
{
    private CustomHashTable<int, long> hashTable;
    private readonly int[] keysArray;
    private readonly long[] offsetsArray;
    private readonly DataRecord[] recordsArray;

    public DataLoader(int size)
    {
        this.hashTable = new CustomHashTable<int, long>();
        this.keysArray = new int[size];
        this.offsetsArray = new long[size];
        this.recordsArray = new DataRecord[size];
    }

    public void LoadDataFromFile(string filePath)
    {
        try
        {
            using (var stream = new FileStream(filePath, FileMode.Open))
            using (var reader = new BinaryReader(stream))
            {
                for (int i = 0; i < keysArray.Length; i++)
                {
                    keysArray[i] = reader.ReadInt32();
                    offsetsArray[i] = reader.BaseStream.Position;
                    recordsArray[i] = new DataRecord { Value = reader.ReadInt32() };

                    hashTable.Add(keysArray[i], offsetsArray[i]);
                }
            }
        }
        catch (Exception ex)
        {
            // Log the exception
            Console.WriteLine("Error loading data from file: " + ex);
        }
    }

    public void Dispose()
    {
        hashTable?.Dispose();
    }
}
```

This code creates a `DataRecord` class to represent individual records in the dataset, and an implementation of a custom hash table using ConcurrentDictionary. The `DataLoader` class loads data from a binary file into these arrays and populates the hash table.

