["The task you're asking to be done is quite complex and involves many aspects of C programming such as handling large-scale datasets, memory management, thread safety, data validation, computation of average temperature, time series indexing, error checking, etc. Here is a simplified implementation for the first part of your request:

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct sensor {
    double temperature;
    char* log_message;
} sensor_t;

typedef struct time_series {
    pthread_mutex_t lock;
    size_t size;
    unsigned long* timestamps;
    double* temperatures;
    sensor_t** sensors;
} time_series_t;

time_series_t* create_timeseries() {
    time_series_t* ts = malloc(sizeof(time_series_t));
    pthread_mutex_init(&ts->lock, NULL);
    ts->size = 0;
    ts->timestamps = NULL;
    ts->temperatures = NULL;
    ts->sensors = NULL;
    return ts;
}

void append_reading(time_series_t* ts, unsigned long timestamp, double temperature, char* log) {
    pthread_mutex_lock(&ts->lock);
    ++ts->size;
    ts->timestamps = realloc(ts->timestamps, sizeof(*ts->timestamps) * ts->size);
    ts->temperatures = realloc(ts->temperatures, sizeof(*ts->temperatures) * ts->size);
    ts->sensors = realloc(ts->sensors, sizeof(*ts->sensors) * ts->size);
    ts->timestamps[ts->size - 1] = timestamp;
    ts->temperatures[ts->size - 1] = temperature;
    sensor_t* s = malloc(sizeof(sensor_t));
    s->temperature = temperature;
    s->log_message = log ? strdup(log) : NULL;
    ts->sensors[ts->size - 1] = s;
    pthread_mutex_unlock(&ts->lock);
}

double average_temperature(time_series_t* ts) {
    pthread_mutex_lock(&ts->lock);
    double sum = 0.0;
    for (size_t i = 0; i < ts->size; ++i) {
        sum += ts->temperatures[i];
    }
    pthread_mutex_unlock(&ts->lock);
    return sum / ts->size;
}

unsigned long timestamp_of_highest(time_series_t* ts) {
    pthread_mutex_lock(&ts->lock);
    double highest = ts->temperatures[0];
    unsigned long timestamp = 0;
    for (size_t i = 1; i < ts->size; ++i) {
        if (ts->temperatures[i] > highest) {
            highest = ts->temperatures[i];
            timestamp = ts->timestamps[i];
        }
    }
    pthread_mutex_unlock(&ts->lock);
    return timestamp;
}

void destroy_timeseries(time_series_t* ts) {
    for (size_t i = 0; i < ts->size; ++i) {
        free(ts->sensors[i]->log_message);
        free(ts->sensors[i]);
    }
    free(ts->timestamps);
    free(ts->temperatures);
    free(ts->sensors);
    pthread_mutex_destroy(&ts->lock);
    free(ts);
}
```
This code creates a time series data structure which is thread-safe. It uses a `pthread_mutex_t` to ensure that only one thread can modify the time series at a time, which prevents race conditions and guarantees data integrity. The size of the time series is dynamically increased each time a new reading is added.

Please note that this is a simplified version of your request. To handle large-scale datasets efficiently, you need to use more advanced techniques like chunked dynamic arrays, memory pool for allocations, concurrent collections etc. Also, to compute the average temperature and identify the timestamp associated with the highest temperature reading without sorting or scanning the array, you would need a different data structure (like priority queue) or algorithm (like divide-and-conquer).
