["Here is a JavaScript code snippet that implements this functionality using Node's `fs` module for file system operations:

```javascript
const fs = require('fs');
const path = require('path');

function processFilesWithCooldown(dirPath, maxConcurrent = 3, cooldownDuration = 9000) {
    return new Promise((resolve, reject) => {
        const files = [];

        fs.readdirSync(dirPath).forEach(fileName => {
            if (path.extname(fileName) === '.js') { // Only process JavaScript files
                files.push({ name: fileName, path: path.join(dirPath, fileName) });
            }
        });

        let fileIndex = 0;
        let activeProcesses = 0;
        let aggregatedResult = [];

        function processFile() {
            if (fileIndex < files.length && activeProcesses < maxConcurrent) {
                const fileInfo = files[fileIndex++];

                fs.readFile(fileInfo.path, 'utf8', (error, content) => {
                    if (error) {
                        console.log('Error processing file:', error);
                        return processFile();
                    }

                    // Process the file's content here...
                    aggregatedResult.push(content);  // Example: Aggregate content

                    activeProcesses--;
                    printProgress();

                    setTimeout(() => {
                        if (activeProcesses < maxConcurrent) processFile();
                    }, cooldownDuration);
                });

                activeProcesses++;
                processFile();
            }
        }

        function printProgress() {
            const elapsedTime = Date.now() - startTime;
            const estimatedRemainingTime = ((files.length - fileIndex) * cooldownDuration / 1000);

            console.log(`Processed ${fileIndex} files out of ${files.length}. Elapsed time: ${elapsedTime/1000}s, Estimated remaining time: ${estimatedRemainingTime}s`);
        }

        const startTime = Date.now();
        processFile(); // Start the processing
    });
}
```
This code uses a combination of recursive function calls and setTimeout to manage file processing concurrency and cooldown periods, respectively. It also uses a counter variable to track the number of active file processes for managing concurrency. The code calculates an estimated remaining time based on the average cooldown duration. Please note that this is just a basic example and actual implementation might require handling different types of files, large directories efficiently, error handling and much more depending on the specific requirements of your task.
