    EVP_CIPHER_CTX* ctx;
    char password[256];
};

// Global variables and constants
#define CACHE_SIZE 1000
static CacheEntry cache[CACHE_SIZE];
static int currentSize = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initializeEncryptionCipher(const char* password) {
    if (password == NULL || strlen(password) == 0) {
        printf("Invalid or empty password\n");
        return;
    }

    pthread_mutex_lock(&mutex); // Lock mutex for thread safety

    unsigned char key[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), key); // Generate the encryption key

    EVP_CIPHER_CTX* ctx = NULL;
    for (int i = 0; i < currentSize; ++i) {
        if (strcmp(cache[i].password, password) == 0) {
            ctx = cache[i].ctx; // If the key is in cache, use it
            break;
        }
    }

    if (ctx == NULL) {
        if (currentSize >= CACHE_SIZE) { // If cache is full
            for (int i = 0; i < currentSize - 1; ++i) {
                cache[i] = cache[i + 1]; // Evict the oldest entry
            }
            --currentSize;
        }

        ctx = EVP_CIPHER_CTX_new();
        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL) != 1) { // Initialize cipher
            printf("Failed to initialize cipher\n");
            pthread_mutex_unlock(&mutex); 
            return;
        }

        cache[currentSize].ctx = ctx; 
        strncpy(cache[currentSize].password, password, sizeof(cache[currentSize].password));
        ++currentSize;
    }

    pthread_mutex_unlock(&mutex); // Unlock mutex after operations are done
}
