        coordinates[i * 2 + 1] = rand() / (float)RAND_MAX * 10.0f - 5.0f;

        ids[i] = rand();  // Generate random unsigned int ID

        points[i].x = coordinates[i * 2];
        points[i].y = coordinates[i * 2 + 1];

        if (points[i].x > 0 && points[i].y > 0) {
            points[i].quadrant = 1;
        } else if (points[i].x < 0 && points[i].y > 0) {
            points[i].quadrant = 2;
        } else if (points[i].x < 0 && points[i].y < 0) {
            points[i].quadrant = 3;
        } else if (points[i].x > 0 && points[i].y < 0) {
            points[i].quadrant = 4;
        } else {
            points[i].quadrant = 0;
        }

        statuses[i] = rand() % 2 ? STATUS_ACTIVE : STATUS_INACTIVE;  // Randomly generate status

        timestamps[i] = generate_timestamp();  // Generate timestamp
    }

    free(coordinates);
    free(ids);
    free(points);
    free(statuses);
    free(timestamps);
}
