        pthread_mutex_lock(&db.lock);

        if (db.data[hash] == NULL) {
            db.count++;
            db.data[hash] = record;

            // Resize the array if it's over half full
            if (db.count * 2 > db.size) {
                pthread_mutex_unlock(&db.lock);
                resize();
            } else {
                pthread_mutex_unlock(&db.lock);
                break;
