#include <stdlib.h>
#include <stdint.h>
#include <assert.h>
#include <stdbool.h>

typedef struct Record {
    size_t offset;
    int key;
} Record;

// User-provided function that generates keys based on a seed and a range limit
int (*generate_key)(uint32_t, uint32_t);

// User-provided function to generate offsets
size_t (*generate_offset)();

bool is_unique(Record **records, size_t num_records, int key) {
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i]->key == key) return false;
    }
    return true;
}

Record **init_records(uint32_t seed, uint32_t range_limit, size_t max_size, uint32_t base_offset, float scale, int attempts) {
    assert(max_size != 0);

    Record **records = malloc(max_size * sizeof(*records));
    if (records == NULL) return NULL;

    size_t num_records = 0;
    while (num_records < max_size) {
        int key = generate_key(seed, range_limit);

        // Resolve collisions by trying to generate a new unique key up to attempts times.
        for (int attempt = 1; attempt <= attempts && !is_unique(records, num_records, key); ++attempt) {
            key = generate_key(seed, range_limit);
        }

        if (!is_unique(records, num_records, key)) return NULL;  // Unable to find a unique key.

        records[num_records] = malloc(sizeof(**records));
        if (records[num_records] == NULL) {
            free_records(records, num_records);
            return NULL;  // Failed to allocate memory for Record.
        }

        records[num_records]->key = key;
        records[num_records]->offset = base_offset + generate_offset() * scale;

        ++num_records;
    }

    return records;
}

void free_records(Record **records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i] != NULL) free(records[i]);
    }

    free(records);
}
