void addTask(int maxTasks, int priorityRange, Task** tasks, size_t* currentSize) {
    if (*currentSize >= maxTasks) {
        printf("Cannot add more than %d tasks!\n", maxTasks);
        return;
    }

    *tasks = realloc(*tasks, sizeof(Task*)*(*currentSize + 1));
    Task* newTask = malloc(sizeof(Task));

