        self._load_factor = 0.75

    def __setitem__(self, key, value):
        slot = hash(key) % len(self._table)
        bucket = self._table[slot]
        for i, (k, v) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return
        bucket.append((key, value))

