// Simple prime checker, replace with a more efficient one for large numbers.
int isPrime(int n) {
    if (n <= 1)  return 0;
    if (n == 2 || n == 3) return 1;
    if (n % 2 == 0 || n % 3 == 0) return 0;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0)
            return 0;
    }
    return 1;
}

// Ensure p is a prime number before proceeding.
int validateP(int p) {
    if (!isPrime(p)) {
        printf("Error: p is not a prime number.\n");
        return 0;
    }
    return 1;
}

// Dynamically allocate memory for offsets, keys and records.
int populateArrays(long *offsets, int **keys, struct record ***records, int min_val, int max_val, size_t arraySize) {
    srand((unsigned) time(NULL)); // Seed the random number generator
    *offsets = malloc(sizeof(long) * arraySize);
    if (*offsets == NULL) return 0;

    *keys = malloc(sizeof(int) * arraySize);
    if (*keys == NULL) {
        free(*offsets);
        return 0;
    }

    *records = malloc(sizeof(struct record*) * arraySize);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return 0;
    }

    for (size_t i = 0; i < arraySize; ++i) {
        // Initialize offsets with unique values.
        (*offsets)[i] = rand() % 1000 + 1;

        // Derive keys from corresponding offset using modulo operation with p.
        int p = 37; // Use a known prime for this example, replace with actual value.
        if (!validateP(p)) return 0;
        (*keys)[i] = (*offsets)[i] % p;

        // Allocate and initialize records.
        struct record *r = malloc(sizeof(struct record));
        if (r == NULL) {
            for (--i; i >= 0; --i) free((*records)[i]);
            free(*offsets);
            free(*keys);
            free(*records);
            return 0;
        }
        r->val = (*keys)[i] + min_val + (rand() % (max_val - min_val + 1));
        (*records)[i] = r;
    }
    return 1;
}

void addAlgorithm(char *name, void (*impl)(void *)) {
    pthread_mutex_lock(&lock);
    ++num_algos;
    algorithms = realloc(algorithms, sizeof(Algorithm) * num_algos);
    if (algorithms == NULL) {
        --num_algos;
        return;
    }
    strncpy(algorithms[num_algos - 1].name, name, sizeof(algorithms[num_algos - 1].name));
    algorithms[num_algos - 1].impl = impl;
    pthread_mutex_unlock(&lock);
}
```
