['Here is a high level overview of how you might approach this task in Rust using the async programming model for IO-bound tasks. Note that writing code for each specific case would require a significant amount of work and is beyond the scope of this platform. 

```rust
use std::fs;
use std::io::{self, Write};
use serde_json::Value as JsonValue;
use tokio::sync::mpsc; // for async channel communication
use url::Url;
use std::net::TcpStream;

pub struct Config {
    pub file: String,
}

impl Config {
    pub fn new(args: &[String]) -> Result<Config, &'static str> {
        if args.len() < 2 {
            return Err("not enough arguments");
        }
        let config_file = args[1].clone();
        Ok(Config{ file: config_file })
    }
}

pub struct FileProcessor {
    pub tx: mpsc::UnboundedSender<JsonValue>, // for async channel communication
    pub rx: mpsc::UnboundedReceiver<JsonValue>,
}

impl FileProcessor {
    pub fn new(tx: mpsc::UnboundedSender<JsonValue>, rx: mpsc::UnboundedReceiver<JsonValue>) -> FileProcessor {
        FileProcessor{ tx, rx }
    }

    pub async fn process_file(&self, file_path: &str) -> io::Result<()> {
        let contents = fs::read_to_string(file_path)?; // read the file to string
        let json: JsonValue = serde_json::from_str(&contents)?; // parse as JSON
        self.tx.send(json).await.unwrap();  // send the value through the channel
        Ok(())
    }
}

pub struct Validator {
    pub tx: mpsc::UnboundedSender<JsonValue>, // for async channel communication
    pub rx: mpsc::UnboundedReceiver<JsonValue>,
}

impl Validator {
    pub fn new(tx: mpsc::UnboundedSender<JsonValue>, rx: mpsc::UnboundedReceiver<JsonValue>) -> Validator {
        Validator{ tx, rx }
    }

    pub async fn validate(&self) -> Result<(), Box<dyn std::error::Error>> {
        while let Some(json) = self.rx.recv().await { // receive value from the channel
            if let Ok(_validated_value) = validate(&json){ 
                self.tx.send(json).await.unwrap();  // send the validated json through the channel
            }
        }
        Ok(())
    }
}

pub fn main() {
    let (raw_tx, raw_rx) = mpsc::unbounded_channel(); // for async channel communication
    let (validated_tx, validated_rx) = mpsc::unbounded_channel(); // for async channel communication
    tokio::spawn(async move {  // spawn a new task
        FileProcessor::new(raw_tx, raw_rx).process_file("config.json").await.unwrap();
    });
    tokio::spawn(async move {  // spawn a new task
        Validator::new(validated_tx, validated_rx).validate().await.unwrap();
    });
}
```
This is a simplified version of the code and doesn't include everything you requested (such as integration with network management system or external dependencies). It only demonstrates how to read configuration files in parallel, parse them as JSON, and pass them on for further processing. 

Remember, this solution assumes that all operations are IO-bound and can be performed concurrently without conflicts. If operations were CPU-intensive or conflicting (like reading the same file), you would need to use a more complex approach with proper synchronization mechanisms like locks, atomic variables or channels for inter-task communication.
