```C
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

// Define your memory pool structure here
struct MemoryPool {
    long *offset_values;
    int *keys;
    Record **records;
};

pthread_mutex_t lock;

struct MemoryPool* init(int offsetSize, int keysSize, int recordsSize) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));

    if (pool == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;  // or exit the program
    }

    pool->offset_values = calloc(offsetSize, sizeof(long));
    pool->keys = malloc(keysSize * sizeof(int));
    pool->records = malloc(recordsSize * sizeof(Record*));

    if (pool->offset_values == NULL || pool->keys == NULL || pool->records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        // free previously allocated memory here
        exit(-1);  // or exit the program
    }

    return pool;
}

void fillWithRandomValues(int* arr, int size, int lowerBound, int upperBound) {
    pthread_mutex_lock(&lock);
    srand(time(0));

    for (int i = 0; i < size; i++) {
        // Generate a random number in the range [lowerBound, upperBound]
        arr[i] = (rand() % (upperBound - lowerBound + 1)) + lowerBound;
    }

    pthread_mutex_unlock(&lock);
}

void freePool(struct MemoryPool* pool) {
    if (pool != NULL) {
        free(pool->offset_values);
        free(pool->keys);

        for (int i = 0; i < sizeof(pool->records)/sizeof(Record*) ; i++) 
            free(pool->records[i]);

        free(pool->records);
        free(pool);
    }
}

// Main program to test the code
int main() {
    struct MemoryPool* pool = init(10, 5, 20);

    fillWithRandomValues(pool->keys, 5, 0, 100);

    for (int i = 0; i < 5; i++) {
        printf("%d ", pool->keys[i]);
    }

    freePool(pool);

    return 0;
}
```
