["Here is a basic implementation of the function you described in C using POSIX Semaphores for thread synchronization and atomic operations for concurrent updates. The semaphore management functions are wrapped in an object structure with additional tracking capabilities. A sample logger has been included that can be easily extended to integrate with external logging services.

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>

typedef struct Semaphore {
    sem_t raw;
    atomic_int accesses;
} Semaphore;

Semaphore* create_and_init_semaphore(int initialValue) {
    if (initialValue < 0 || initialValue > SEM_VALUE_MAX) {
        // handle error - sem value out of range
        return NULL;
    }

    Semaphore *s = malloc(sizeof(Semaphore));
    s->accesses = 0;
    if (sem_init(&s->raw, 0, initialValue) != 0) {
        // handle error - sem init failed
        free(s);
        return NULL;
    }

    return s;
}

void manage_semaphore(Semaphore *s, int increment) {
    if (increment > 0 && atomic_fetch_add(&s->accesses, increment) + increment > SEM_VALUE_MAX) {
        // handle error - sem value would exceed max
        return;
    } else if (increment < 0 && atomic_load(&s->accesses) < -increment) {
        // handle error - sem value below min
        return;
    }

    while (increment-- > 0) {
        if (sem_post(&s->raw) != 0) {
            // handle error - sem post failed
        }
    }
    while(increment++ < 0){
        if (sem_wait(&s->raw) != 0) {
            // handle error - sem wait failed
        }
    } 
}

int get_accesses(Semaphore *s) {
    return atomic_load(&s->accesses);
}

void delete_semaphore(Semaphore *s) {
    sem_destroy(&s->raw);
    free(s);
}
``` 

Remember that POSIX Semaphores do not provide direct access to the current value and do not allow for atomic increments or decrements, hence `atomic_int` is used. Also, it's recommended to use semaphore functions in a loop to handle potential interruptions by signals. The actual error handling would depend on the exact requirements of your project.
"]

