```php
<?php
class UserManagementService {
    public function updateUserProfile($email, $contactNumber, $address) {
        // Input validation
        if(!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new Exception('Invalid email format');
        }

        $contactNumber = preg_replace('/[^0-9]/', '', $contactNumber);
        if(strlen($contactNumber) != 10) {
            throw new Exception('Contact number must be 10 digits long');
        }

        if(!isset($address)) {
            throw new Exception('Address cannot be empty');
        }

        // Cooldown period check - you might need to store this state somewhere (e.g., database)
        $lastUpdateTime = userProfileDao::getLastUpdatedTimestamp();
        if((time() - $lastUpdateTime) < 300) {  // 5 minutes cooldown
            throw new Exception('Cooldown period must pass before a new update');
        }

        try{
            $userProfileDao = new userProfileDao();

            // Begin transaction to ensure atomicity
            $userProfileDao->beginTransaction();
            $userProfileDao->updateUser($email, $contactNumber, $address);
            // Commit the transaction if everything goes well 
            $userProfileDao->commitTransaction();
        } catch (Exception $e) {
            // Rollback in case of error to avoid data corruption
            $userProfileDao->rollBackTransaction();
            throw new Exception('Failed to update user profile: ' . $e->getMessage());
        }
    }
}
?>
```

