```cpp
#include <iostream>
#include <random>
#include <chrono>
#include <thread>

std::mt19937 mt{ std::random_device{}() };
int lastSelectedAttack = -1; // Initialize to an invalid value for the first attack

void cycleAttackSelection(){
    auto currentTime = std::chrono::system_clock::now();
    static auto lastUpdateTime = currentTime; // Static variable is preserved between function calls

    if(std::chrono::duration_cast<std::chrono::seconds>(currentTime - lastUpdateTime).count() < 10){
        std::this_thread::sleep_for(std::chrono::seconds(10)); // Wait for the cooldown period before selecting a new attack 
    }

    int selectedAttack;
    do{
        std::uniform_int_distribution dist(0,2);
        selectedAttack = dist(mt);
    } while (selectedAttack == lastSelectedAttack); // Ensure no consecutive same attacks

    lastUpdateTime = currentTime; // Update the last update time after a successful attack selection 
    lastSelectedAttack = selectedAttack; // Update the last selected attack 

    std::cout << "Selected Attack Index: " << selectedAttack << std::endl;
}
```
This function uses `std::mt19937` for random number generation, and checks the time difference from the last update to apply a cooldown period. It also ensures that no consecutive attacks are the same by regenerating a new attack until it's different than the previous one. The selection is printed to the console. Please adjust according to your needs.
