["Here is a basic example of how you might accomplish this task in C using OpenSSL library. Note that the actual implementation could be quite complex depending on your specific needs, so adjust accordingly. 

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

#define ITERATIONS 4096
#define KEY_SIZE 32 /* 256 bits */
#define BLOCK_SIZE 16 /* AES-256 block size is 128 bits (16 bytes) */

typedef struct {
    unsigned char key[KEY_SIZE];
    unsigned char iv[BLOCK_SIZE];
} aes256_context;

void handleErrors(void) { /* Error handling function */ }

int aes256_init(aes256_context *ctx, const char* password, size_t len) {
    int rc = 1;
    if(!RAND_bytes(ctx->iv, BLOCK_SIZE)) handleErrors(); /* Generate IV */
    else if(!PKCS5_PBKDF2_HMAC_SHA1(password, len, ctx->iv, BLOCK_SIZE, ITERATIONS, KEY_SIZE, ctx->key)) handleErrors(); /* Derive key using PBKDF2 */
    else rc = 0; /* success */
    return rc;
}

int aes256_encrypt(aes256_context *ctx, unsigned char* in, size_t len, unsigned char* out) {
    int outlen1, outlen2, rc = 1;
    EVP_CIPHER_CTX* cipher = EVP_CIPHER_CTX_new();

    if(!EVP_EncryptInit(cipher, EVP_aes_256_cbc(), ctx->key, ctx->iv)) handleErrors(); /* Initialize cipher context */
    else if(!EVP_EncryptUpdate(cipher, out, &outlen1, in, len)) handleErrors(); /* Encrypt data */
    else if(!EVP_EncryptFinal(cipher, out + outlen1, &outlen2)) handleErrors(); /* Finalize encryption and get the tag */
    else rc = 0; /* success */

    EVP_CIPHER_CTX_free(cipher); /* Clean up cipher context */
    return rc ? -1 : outlen1 + outlen2;
}

int aes256_decrypt(aes256_context *ctx, unsigned char* in, size_t len, unsigned char* out) {
    int outlen1, outlen2, rc = 1;
    EVP_CIPHER_CTX* cipher = EVP_CIPHER_CTX_new();

    if(!EVP_DecryptInit(cipher, EVP_aes_256_cbc(), ctx->key, ctx->iv)) handleErrors(); /* Initialize cipher context */
    else if(!EVP_DecryptUpdate(cipher, out, &outlen1, in, len)) handleErrors(); /* Decrypt data */
    else if(!EVP_DecryptFinal(cipher, out + outlen1, &outlen2)) handleErrors(); /* Finalize decryption and get the tag */
    else rc = 0; /* success */

    EVP_CIPHER_CTX_free(cipher); /* Clean up cipher context */
    return rc ? -1 : outlen1 + outlen2;
}

void aes256_cleanup(aes256_context *ctx) {
    if (ctx != NULL) memset(ctx, 0, sizeof(*ctx)); /* Zero-out the context */
}
```

This code provides the basic functionality of initializing and using an AES-256 CBC cipher with a given password. For security reasons, it also cleans up any sensitive data (e.g., key or IV) once it is no longer needed. 

Please note that this example does not perform any error handling for brevity's sake - you would want to add in appropriate error checks and handle different types of errors appropriately. Also, this code uses PBKDF2 with SHA-1 (which is considered secure) but it could be upgraded to use stronger hash function like SHA-3 or Argon2 for more security at the cost of computational overhead. 

Remember to link your program against OpenSSL library when compiling: `gcc -lcrypto your_program.c`. You may also need to install and configure OpenSSL on your system if it's not already done so.
