typedef struct File {
    int id;
    char* name;
    size_t bufferSize;
    void* buffer;
} File;

typedef struct Directory {
    pthread_mutex_t lock;
    File** files;
    size_t fileCount;
    size_t maxFiles;
} Directory;

File* createFile(int id, const char* name) {
    assert(name);

    File* newFile = (File*) malloc(sizeof(File));
    if (!newFile) {
        return NULL;
    }
    newFile->id = id;
    newFile->name = strdup(name);
    newFile->bufferSize = 0;
    newFile->buffer = NULL;

    return newFile;
}

void deleteFile(File* file) {
    assert(file);

    free(file->name);
    free(file->buffer);
    free(file);
}

int addFileToDirectory(Directory* directory, File* file) {
    assert(directory && file);

    pthread_mutex_lock(&directory->lock);

    for (size_t i = 0; i < directory->fileCount; ++i) {
        if (directory->files[i]->id == file->id) {
            // Duplicate ID
            pthread_mutex_unlock(&directory->lock);
            return -1;  // Or any appropriate error code for duplicate files
        }
    }

    if (directory->fileCount >= directory->maxFiles) {
        size_t newMaxFiles = directory->maxFiles * 2;
        File** newFilesArray = realloc(directory->files, sizeof(File*) * newMaxFiles);
        if (!newFilesArray) {
            pthread_mutex_unlock(&directory->lock);
            return -1; // Or any appropriate error code for failed allocation
        }

        directory->maxFiles = newMaxFiles;
        directory->files = newFilesArray;
    }

    directory->files[directory->fileCount++] = file;

    pthread_mutex_unlock(&directory->lock);

    return 0; // Success
}

Directory* createDirectory() {
    Directory* newDir = (Directory*) malloc(sizeof(Directory));
    if (!newDir) {
        return NULL;
    }
    pthread_mutex_init(&newDir->lock, NULL);
    newDir->files = NULL;
    newDir->fileCount = 0;
    newDir->maxFiles = 10; // Starting capacity

    return newDir;
}

void deleteDirectory(Directory* directory) {
    assert(directory);

    for (size_t i = 0; i < directory->fileCount; ++i) {
        deleteFile(directory->files[i]);
    }
    free(directory->files);
    pthread_mutex_destroy(&directory->lock);
    free(directory);
}
