["Here is an implementation of a thread-safe record management system with the constraints and design choices you specified:

```C
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>

// Structure for record
typedef struct Record {
    long offset;
    int key;
    char string[32];
} Record;

// Structure for node in linked list
typedef struct Node {
    Record* record;
    struct Node *next;
} Node;

// Data structure to manage records
typedef struct RecordManager {
    Node *head;
    pthread_mutex_t lock;
    int max_records; // maximum number of records allowed
    int curr_records; // current number of records in list
} RecordManager;

// Initialize the record manager
RecordManager* init_manager(int max) {
    srand((unsigned)time(NULL));
    RecordManager *mgr = malloc(sizeof(RecordManager));
    if (!mgr) return NULL; // Handle allocation failure

    pthread_mutex_init(&mgr->lock, NULL);
    mgr->head = NULL;
    mgr->max_records = max;
    mgr->curr_records = 0;

    return mgr;
}

// Generate random string and key
Record* generate_record(int key_range) {
    Record *record = malloc(sizeof(Record));
    if (!record) return NULL; // Handle allocation failure

    record->offset = 0;
    record->key = rand() % key_range;

    for (int i=0; i<31; ++i) {
        record->string[i] = 'a' + (rand() % 26); // Generate random lowercase English letters
    }
    record->string[31] = 0;

    return record;
}

// Insert a record into the linked list, thread-safely
int insert_record(RecordManager *mgr, Record* record) {
    pthread_mutex_lock(&mgr->lock);
    if (mgr->curr_records >= mgr->max_records) { // If reached limit of records
        pthread_mutex_unlock(&mgr->lock);
        return -1; // Return error code for too many records
    }
    ++mgr->curr_records;
    Node *node = malloc(sizeof(Node));
    if (!node) {
        --mgr->curr_records;
        pthread_mutex_unlock(&mgr->lock);
        return -2; // Return error code for allocation failure
    }

    node->record = record;
    node->next = mgr->head;
    mgr->head = node;
    pthread_mutex_unlock(&mgr->lock);

    return 0; // Return success code
}

// Delete a record from the linked list, thread-safely
int delete_record(RecordManager *mgr, int key) {
    pthread_mutex_lock(&mgr->lock);

    Node **ptr = &mgr->head;
    while (*ptr && (*ptr)->record->key != key) { // Traverse list to find matching record
        ptr = &((*ptr)->next);
    }
    if (!(*ptr)) { // If no matching record was found
        pthread_mutex_unlock(&mgr->lock);
        return -1; // Return error code for not found
    }

    Node *temp = *ptr;
    *ptr = temp->next;
    --mgr->curr_records;
    free(temp->record);
    free(temp);
    pthread_mutex_unlock(&mgr->lock);

    return 0; // Return success code
}
```
This code provides a basic thread-safe record management system with insertion, deletion and key range generation. It is written for educational purposes and does not handle advanced features such as efficient search or modification of records. For production use, additional error handling, performance optimization and potentially different data structures would be required.
"]

