#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#define HASH_TABLE_SIZE 1024

typedef struct Element {
    double value;
    short index;
    char string[65]; // 64 characters + null character
} Element;

typedef struct HashTableEntry {
    Element* element;
    struct HashTableEntry* next;
} HashTableEntry;

HashTableEntry* hash_table[HASH_TABLE_SIZE] = {0};

unsigned long hash(short index) {
    return (index % HASH_TABLE_SIZE); //Simple hash function
}

int insertElement(Element* element){
    unsigned int key = hash(element->index);

    HashTableEntry* entry = malloc(sizeof(HashTableEntry));
    if(!entry) return 1; //Memory allocation failure.

    entry->element = element;
    entry->next = hash_table[key];
    hash_table[key] = entry;

    return 0;
}

int deleteElement(short index){
    unsigned int key = hash(index);
    HashTableEntry* prev = NULL;

    for (HashTableEntry* curr = hash_table[key]; curr != NULL; prev = curr, curr = curr->next) {
        if (curr->element->index == index){
            if(prev)
                prev->next = curr->next; //Element is in the middle of the list.
            else
                hash_table[key] = curr->next; //Element is at head of the list.

            free(curr->element); //Free allocated memory.
            free(curr);
            return 0;
        }
    }

    return -1; //Could not find element in hash table.
}

Element* createElement(){
    srand(time(NULL)); //Seed random number generator with current time.

    Element* e = malloc(sizeof(Element));
    if(!e) return NULL; //Memory allocation failure.

    e->value = ((double) rand() / (RAND_MAX)) * 100; //Generate random double between 0 and 100.
    e->index = rand(); //Generate random short index.
    sprintf(e->string, "random_%d", e->index); //Generate random alphanumeric string based on index.

    return e;
}
