void initializeRecords(Record* records, size_t count, long offsets[], int keys[], int min, int max) {
    srand((unsigned int)time(NULL)); // Seed for the random number generator

    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max - min + 1) + min; // Random value between min and max
        keys[i] = records[i].value; // Store the key in separate array
    }
}

// Function to decrypt ciphertext using AES-CBC and initialize record structures
int decryptAndInitializeRecords(const unsigned char *ciphertext, size_t len, const unsigned char *key, 
                                const unsigned char *iv, int min, int max, long offsets[], int keys[]) {
    EVP_CIPHER_CTX *ctx;
    unsigned char plaintext[len]; // Assume plaintext is same size as ciphertext
    int lenPlaintext = 0, retVal = -1;

    /* Create and initialise the context */
    if(!(ctx = EVP_CIPHER_CTX_new())) {
        return retVal; // Handle error
    }

    /* Initialise the decryption operation. */
    if(EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        return retVal; // Handle error
    }

    /* Provide the message to be decrypted, and obtain the plaintext output. */
    if(EVP_DecryptUpdate(ctx, plaintext, &lenPlaintext, ciphertext, len) != 1) {
        return retVal; // Handle error
    }

    /* Finalise the decryption. Further plaintext bytes may be written at this stage. */
    if(EVP_DecryptFinal_ex(ctx, plaintext + lenPlaintext, &lenPlaintext) != 1) {
        return retVal; // Handle error
    }

    /* Clean up */
    EVP_CIPHER_CTX_free(ctx);

    size_t recordCount = sizeof(plaintext)/sizeof(Record);
    Record* records = malloc(recordCount * sizeof(Record)); // Allocate memory for record structures

    if (records == NULL) {
        return retVal; // Handle error
    }

    initializeRecords(records, recordCount, offsets, keys, min, max); // Initialize the records

    retVal = 0; 
    return retVal;
}
```
This is a simplistic example and doesn't account for many factors such as memory allocation failure, error handling in decryption/encryption operations, secure key management, or handling different data sizes. It also does not return the decrypted plaintext. 

