void initializeRecordSystem(const unsigned char *ciphertext, const unsigned char *key, 
                            const unsigned char *iv, int range_start, int range_end, size_t bufsize) {

    // Decrypt ciphertext using AES-CBC encryption.
    unsigned char plaintext[AES_BLOCK_SIZE];
    AES_KEY dec_key;
    AES_set_decrypt_key(key, 128, &dec_key);
