typedef struct {
    double value;
} Vector;

// The spatial index can be implemented as a linked list for simplicity
typedef struct PointList {
    float* point;
    Vector vector;
    struct PointList *next;
} PointList;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
PointList* spatialIndexHead = NULL;
size_t maxPoolSize = 0; // Limit for the maximum pool size
size_t currentPoolSize = 0; // Current size of the pool

// Function to create a new point with random vector value and add it to spatial index
void addPointToSpatialIndex(float* coordinates, int dimensions) {
    Vector vector = {.value = 0};
    RAND_bytes((unsigned char*)&vector.value, sizeof(double)); // Random number generation using OpenSSL library

    pthread_mutex_lock(&lock);

    PointList* newPoint = (PointList*)malloc(sizeof(PointList));
    if(newPoint == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the point and vector
    newPoint->point = coordinates;
    newPoint->vector = vector;

    // Add the new point to spatial index head
    if(spatialIndexHead == NULL) {
        spatialIndexHead = newPoint;
    } else {
        PointList* lastPoint = spatialIndexHead;
        while(lastPoint->next != NULL) {
            lastPoint = lastPoint->next;
        }
        lastPoint->next = newPoint;
    }

    currentPoolSize++;

    if(currentPoolSize > maxPoolSize) {
        // Remove the least recently used point from the index and free its memory
        PointList* temp = spatialIndexHead;
        spatialIndexHead = spatialIndexHead->next;
        free(temp);
        currentPoolSize--;
    }

    pthread_mutex_unlock(&lock);
}
```
Note: This is a simplified version of the function, and it doesn't handle all scenarios mentioned in your requirements. You would need to add error handling code for things like out-of-memory conditions, incorrect dimensions, etc. Also, this example uses OpenSSL for random number generation which might not be available on some systems or environments, you should use a suitable cryptographic library for your specific needs.
