["Here's a basic implementation of what you described using OpenMP for parallelization, logging, error checking and clean up, etc. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <omp.h>
#include <math.h>
#include <assert.h>

typedef struct point{
    double x;
    double y;
}point_t;

typedef struct geometry {
    double *x;
    double *y;
    unsigned short *value;
}geometry_t;

double euclideanDistance(double x1, double y1, double x2, double y2) {
    return sqrt(pow((x2-x1), 2) + pow((y2-y1), 2));
}

void sortArray(double* array, int length) {
    for (int i = 0; i < length-1; i++) {
        for (int j = i+1; j < length; j++) {
            if (array[i] > array[j]) {
                double temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
    }
}

void calculateDistances(int numPoints, geometry_t* geometry, double* distances) {
   #pragma omp parallel for schedule(dynamic) 
    for (int i = 0; i < numPoints-1; ++i) {
        for (int j = i+1; j < numPoints; ++j) {
            int index = i * numPoints + j - ((i+1)*i)/2;
            distances[index] = euclideanDistance(geometry->x[i], geometry->y[i], geometry->x[j], geometry->y[j]);
        }
    }
}

int main() {
    int numPoints = 5000;

    double *distances = (double*) malloc(numPoints*(numPoints+1)/2*sizeof(double));
    assert(distances != NULL); 

    point_t *points = (point_t*) malloc(numPoints*sizeof(point_t));
    assert(points != NULL); 

    geometry_t geometry;
    geometry.x = (double*)malloc(numPoints*sizeof(double));
    geometry.y = (double*)malloc(numPoints*sizeof(double));
    geometry.value = (unsigned short*)malloc(numPoints*sizeof(unsigned short));

    assert(geometry.x != NULL && geometry.y != NULL && geometry.value != NULL); 

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < numPoints; ++i) {
        points[i].x = rand() % 100; // Assigning some values to demonstrate.
        points[i].y = rand() % 100;
    }

    for (int i = 0; i < numPoints; ++i) {
        geometry.x[i] = points[i].x;
        geometry.y[i] = points[i].y;
        geometry.value[i] = rand() % 100;
    }

    calculateDistances(numPoints, &geometry, distances);
    sortArray(distances, numPoints*(numPoints+1)/2);

    free(points);
    free(distances);
    free(geometry.x);
    free(geometry.y);
    free(geometry.value);
}
``` 

This function calculates the Euclidean distance between each pair of points and stores them in a one-dimensional array, sorted in ascending order after computation. The use of OpenMP for parallelization is demonstrated with the `#pragma omp parallel for` directive to calculate distances in parallel.

