    char *name;
    /* Other customer info fields */
};

struct OrderProcessing {
    OrderID_t id;
    struct ProductOrderDetails product_details;
    struct CustomerInfo *customer_info;
};

typedef struct {
    pthread_mutex_t lock;
    size_t size, capacity;
    struct OrderProcessing **data;
} OrderList;

OrderList* createOrderList() {
    OrderList *list = malloc(sizeof(OrderList));
    list->capacity = 1024; /* Initial capacity */
    list->size = 0;
    list->data = malloc(list->capacity * sizeof(struct OrderProcessing*));
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroyOrderList(OrderList *list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->data[i]->customer_info);
        free(list->data[i]);
    }

    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}

void insertOrder(OrderList *list, struct OrderProcessing* order) {
    if (order == NULL) return; /* Invalid order */

    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        list->capacity *= 2;
