["Here is an example of how you could approach this task. Note that in a real-world application, there are many additional considerations such as error handling, concurrency control, etc., which are not covered here for simplicity's sake:

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} record_t;

typedef struct hash_entry_s {
    long offset;
    struct hash_entry_s *next;
} hash_entry_t;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Global variables for the data
int* keys;
long* offsets;
record_t** records;
hash_entry_t** hash_table;
size_t capacity = 1024;  // Initial capacity of the hash table
size_t size = 0;        // Current number of entries in the hash table

// Hash function
static size_t hash(int key) {
    return (key % capacity + capacity) % capacity;
}

void initialize(size_t dataset_size, int range) {
    keys = malloc(dataset_size * sizeof(int));
    offsets = malloc(dataset_size * sizeof(long));
    records = malloc(dataset_size * sizeof(record_t*));

    // Initialize arrays and hash table
    for (size_t i = 0; i < dataset_size; i++) {
        keys[i] = rand() % range;  // Random key within a specified range
        offsets[i] = rand();      // Random long offset

        records[i] = malloc(sizeof(record_t));
        records[i]->value = rand();  // Random record value

        insert(keys[i], i);  // Insert the key-offset pair into the hash table
    }
}

void insert(int key, size_t offset) {
    pthread_mutex_lock(&mutex);

    if (size >= capacity * 0.75) {
        resize();  // Resize the hash table when it's 75% full
    }

    size_t index = hash(key);
    hash_entry_t* new_entry = malloc(sizeof(hash_entry_t));
    new_entry->offset = offset;
    new_entry->next = hash_table[index];
    hash_table[index] = new_entry;

    size++;  // Increment the number of entries in the hash table

    pthread_mutex_unlock(&mutex);
}

// Resize the hash table and rehash all key-offset pairs
void resize() {
    capacity *= 2;        // Double the capacity
    size_t old_capacity = capacity / 2;

    hash_entry_t** new_table = malloc(capacity * sizeof(hash_entry_t*));

    // Rehash all key-offset pairs into the new table
    for (size_t i = 0; i < old_capacity; i++) {
        hash_entry_t* entry = hash_table[i];

        while (entry != NULL) {
            hash_entry_t* next = entry->next;

            size_t index = hash(keys[entry->offset]);
            entry->next = new_table[index];
            new_table[index] = entry;

            entry = next;
        }
    }

    free(hash_table);  // Free the old table
    hash_table = new_table;  // Update the global table pointer
}
```
This code implements a basic hash table with linear probing for collision resolution, and resizes when the load factor reaches 75%. It uses a single mutex to protect concurrent access. Resizing is done by creating a larger hash table and rehashing all key-offset pairs into it. The `insert` function locks the mutex before modifying the hash table and incrementing its size, then unlocks it after completion.
"]

