            continue;
        }

        int key = rand();
        record_t* newRecord = calloc(1, sizeof(record_t));
        if (!newRecord) {
            logError("Memory allocation failed");
            free(newOffset);
            continue;
        }

        pthread_mutex_lock(&bufferMutex);

        while (batchCount == BUFFER_SIZE) {
            pthread_cond_wait(&bufferNotFull, &bufferMutex);
        }

        offsetsBuffer[putIndex] = newOffset;
        keysBuffer[putIndex] = key;
        recordsBuffer[putIndex++] = newRecord;
        if (putIndex == BUFFER_SIZE) putIndex = 0;
        batchCount++;

        pthread_cond_signal(&bufferNotEmpty);
        pthread_mutex_unlock(&bufferMutex);
    }
}

void processRecordBatch(long** offsets, int* keys, record_t* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        concurrent_unordered_map<int, long>::accessor acc;
        map.insert(acc, keys[i]);
        *(offsets[i]) = rand(); // initialize with a unique value based on the record index
        records[i].value = rand() % 1000 + 1; // set to a random value within a specified range
        acc->second = *(offsets[i]);
    }
}

void* processBatches(void* args) {
    while (1) {
        pthread_mutex_lock(&bufferMutex);

        while (batchCount == 0) {
            pthread_cond_wait(&bufferNotEmpty, &bufferMutex);
        }

        size_t count = batchCount < BUFFER_SIZE ? batchCount : BUFFER_SIZE;
        long** offsetsToProcess[BUFFER_SIZE], *offsetsTemp[count];
        int keysToProcess[BUFFER_SIZE], keysTemp[count];
        record_t* recordsToProcess[BUFFER_SIZE], *recordsTemp[count];

        for (size_t i = 0; i < count; ++i) {
            offsetsToProcess[i] = offsetsBuffer[takeIndex];
            keysToProcess[i] = keysBuffer[takeIndex];
            recordsToProcess[i] = recordsBuffer[takeIndex++];

            if (takeIndex == BUFFER_SIZE) takeIndex = 0;
        }

        batchCount -= count;
        pthread_cond_signal(&bufferNotFull);
        pthread_mutex_unlock(&bufferMutex);

        memcpy(offsetsTemp, offsetsToProcess, sizeof(long*) * count);
        memcpy(keysTemp, keysToProcess, sizeof(int) * count);
        memcpy(recordsTemp, recordsToProcess, sizeof(record_t) * count);

        processRecordBatch(offsetsTemp, keysTemp, recordsTemp, count);
    }
}

void initializeThreadPool() {
    pthread_t threads[NUM_THREADS];

    for (size_t i = 0; i < NUM_THREADS - 1; ++i) {
        pthread_create(&threads[i], NULL, &fetchRecords, NULL);
    }

    pthread_create(&threads[NUM_THREADS - 1], NULL, &processBatches, NULL);
}
```

This code initializes a thread pool that fetches records from an external API and stores them in buffers. A separate thread processes these batches into the hash map, ensuring thread safety during read/write operations with `concurrent_unordered_map`. Memory allocated for 'record' structures is freed when the function exits using `calloc` and `malloc` calls. Error messages are logged with `logError` if memory allocation fails or invalid data is received from the external API. Finally, resource usage is reported with `reportMemoryUsage`.
']

