// Define the hash table structure
typedef struct HashTableEntry_t {
    int key;
    long offset;
    struct HashTableEntry_t *next;
} HashTableEntry;

// Global variables
HashTableEntry **hashTable = NULL;
int TABLE_SIZE = 2039;  // Prime number for less collision
Record* records = NULL;
long* offsets = NULL;
pthread_rwlock_t hashLock = PTHREAD_RWLOCK_INITIALIZER;

// Hash function
unsigned long djb2(char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % TABLE_SIZE;
}

// Function to handle updates from external data sources
void update(int key, long offset) {
    pthread_rwlock_wrlock(&hashLock);
    unsigned long index = djb2((char*)&key);

    HashTableEntry* entry = hashTable[index];
    while (entry != NULL) {
        if (entry->key == key) {
            entry->offset = offset;
            break;
        }

        entry = entry->next;
    }

    pthread_rwlock_unlock(&hashLock);
}

// Function to initialize the hash table and other arrays
void init(int numRecords, int minValue, int maxValue) {
    // Allocate memory for all arrays
    records = (Record*) malloc(numRecords * sizeof(Record));
    offsets = (long*) malloc(numRecords * sizeof(long));

    hashTable = (HashTableEntry**) calloc(TABLE_SIZE, sizeof(HashTableEntry*));

    srand((unsigned int) time(NULL)); // Seed the random number generator

    for(int i = 0; i < numRecords; i++) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;

        update(&records[i], offsets[i]); // Add to hash table
    }
}

// Function to free all allocated memory on exit
void cleanup(int numRecords) {
    for(int i = 0; i < TABLE_SIZE; i++) {
        HashTableEntry* entry = hashTable[i];

        while (entry != NULL) {
            HashTableEntry* prev = entry;
            entry = entry->next;
            free(prev);
        }
    }

    free(hashTable);
    free(records);
    free(offsets);
}
```

