```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value; 
} Record;

typedef struct Node {
    int key; 
    long offset; 
    pthread_mutex_t mutex; 
    Record* record; 
} Node;

Node** dataStore = NULL;
size_t size = 0;
pthread_rwlock_t rwLock;

void resize(int newSize) {
    Node** newDataStore = (Node**)calloc(newSize, sizeof(Node*)); 

    for (int i=0; i<size && i<newSize; ++i) { 
        newDataStore[i] = dataStore[i]; 
    }

    free(dataStore);
    dataStore = newDataStore;
}

void init_store(int n, int m, int min_val, int max_val) {
    if (n < 1 || m < min_val || max_val < min_val) return NULL; 

    size = m - min_val + 1;
    dataStore = (Node**)calloc(size, sizeof(Node*));
    pthread_rwlock_init(&rwLock, NULL);

    for (int i=0; i<size; ++i) { 
        Node* node = (Node*)malloc(sizeof(Node));

        if (!node) return NULL; 

        pthread_mutex_init(&node->mutex, NULL);
        node->key = i + min_val;
        node->offset = 0L;
        node->record = (Record*)calloc(n, sizeof(Record));
        dataStore[i] = node; 
    }

    return &dataStore[0]->record;
}

void insert(int key, int value) {
    if (!dataStore) return;

    pthread_rwlock_rdlock(&rwLock);
    Node* node = dataStore[key - min_val];

    if (!node) return; 

    pthread_mutex_lock(&node->mutex);
    node->record[node->offset].value = value;
    (node->offset)++;

    pthread_rwlock_unlock(&rwLock);
}
```
This is a highly simplified example, and there are many additional details that would need to be handled such as input validation, memory management for deallocation, threading synchronization mechanisms etc. Also note that C doesn't have garbage collection out of the box like some other languages do. Therefore, manual resource handling becomes very important in C.
