However, here's a simplified example of how to dynamically allocate memory using malloc or realloc in C, as well as how to handle hash table concurrency control:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int key;
    long offset;
    double value;
} record_t;

typedef struct hash_table {
    pthread_mutex_t lock;
    size_t size;
    size_t capacity;
    record_t** records;
} hash_table_t;

hash_table_t* create_hash_table(size_t initial_capacity) {
    hash_table_t* table = malloc(sizeof(hash_table_t));
    if (table == NULL) return NULL;

    table->records = calloc(initial_capacity, sizeof(record_t*));
    if (table->records == NULL) {
        free(table);
        return NULL;
    }

    table->size = 0;
    table->capacity = initial_capacity;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insert_record(hash_table_t* table, record_t* record) {
    pthread_mutex_lock(&table->lock);

    if (table->size == table->capacity) {
        // Resize the hash table. For simplicity we double its capacity here
        size_t new_capacity = table->capacity * 2;
        record_t** new_records = realloc(table->records, new_capacity * sizeof(record_t*));

        if (new_records == NULL) {
            // Failed to resize. We should handle this error gracefully depending on the requirements
            pthread_mutex_unlock(&table->lock);
            return;
        }

        table->capacity = new_capacity;
        table->records = new_records;
    }

    // Insert the record into the hash table. For simplicity, we assume there's no collision
    table->records[table->size++] = record;

    pthread_mutex_unlock(&table->lock);
}

void free_hash_table(hash_table_t* table) {
    // First, we unlock all the records to ensure no deadlocks happen when a thread is trying to access an already freed record 
    for (size_t i = 0; i < table->size; ++i) {
        pthread_mutex_unlock(&table->records[i]->lock);
    }

    // Then we free all the records and finally the hash table itself
    for (size_t i = 0; i < table->capacity; ++i) {
        if(table->records[i] != NULL) {
            pthread_mutex_destroy(&table->records[i]->lock);
            free(table->records[i]);
        }
    }

    free(table->records);
    pthread_mutex_unlock(&table->lock);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
```

Please note that this is just a simplified example. In real use case, you would likely need more advanced solutions like fine grained locking or lock-free data structures for the hash table, and also additional error handling depending on your specific requirements. 

