```C
#include <stdlib.h>
#include <pthread.h>

// Define the packet structure
typedef struct Packet {
    int data;
} Packet;

// Define a buffer to store incoming packets
typedef struct Buffer {
    pthread_mutex_t mutex; // for thread safety
    Packet *buffer; 
    size_t head, tail, capacity;
} Buffer;

// Initialize the buffer with dynamic size
Buffer* init_buffer(size_t initialSize) {
    Buffer *buf = malloc(sizeof(Buffer));
    buf->capacity = initialSize;
    buf->buffer = malloc(initialSize * sizeof(Packet));
    buf->head = 0;
    buf->tail = 0;
    pthread_mutex_init(&buf->mutex, NULL);
    return buf;
}

// Resize the buffer when it is full
void resize_buffer(Buffer *buf) {
    size_t newCapacity = buf->capacity * 2; // you can choose any resizing policy here

    Packet *newBuffer = malloc(newCapacity * sizeof(Packet));
    for (size_t i = 0; i < buf->capacity; ++i) {
        newBuffer[i] = buf->buffer[(buf->head + i) % buf->capacity];
    }

    free(buf->buffer);
    buf->buffer = newBuffer;
    buf->head = 0;
    buf->tail = buf->capacity;
    buf->capacity = newCapacity;
}

// Push a packet into the buffer
void push_packet(Buffer *buf, Packet p) {
    if ((buf->tail + 1) % buf->capacity == buf->head) {
        resize_buffer(buf);
    }

    pthread_mutex_lock(&buf->mutex);
    buf->buffer[buf->tail] = p;
    buf->tail = (buf->tail + 1) % buf->capacity;
    pthread_mutex_unlock(&buf->mutex);
}
```
This code provides a basic buffer implementation for storing packets. The `resize_buffer` function doubles the capacity of the buffer when it's full, which is a simple approach to handle memory usage. In a more complex scenario, you might want to adjust this based on your specific needs and conditions. The buffer operations are wrapped in mutex locks to ensure thread safety, although they should be replaced with appropriate synchronization primitives depending on the use case (e.g., semaphores, condition variables).
