    std::default_random_engine generator(seed);
    std::uniform_int_distribution<int> distribution(-1000, 1000);

    int* keys = new int[n];
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = static_cast<long>(i);
        keys[i] = distribution(generator);
