    std::list<Record> records;

    for (size_t i = 0; i < n; ++i) {
        Record rec;
        rec.value = keys[i];
        records.push_back(rec);
    }

    // Vector of string identifiers.
    std::vector<std::string> identifiers;
    identifiers.reserve(n);  // Reserve memory to avoid reallocation overhead.

    for (size_t i = 0; i < n; ++i) {
        identifiers.push_back("ID" + std::to_string(keys[i]));
