typedef struct configuration_settings {
    int integer;
    char *string;
    bool boolean;
} ConfigurationSettings;

typedef struct configuration_node {
    char *key;
    ConfigurationSettings *value;
    struct configuration_node *next;
} ConfigurationNode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Lock for thread safety
ConfigurationNode *head = NULL; // Head of the linked list

void add(char *key, ConfigurationSettings *value) {
    pthread_mutex_lock(&lock); // Acquire lock to ensure thread-safety

    ConfigurationNode *node = malloc(sizeof(ConfigurationNode));
    node->key = key;
    node->value = value;
    node->next = head;

    head = node;

    pthread_mutex_unlock(&lock); // Release lock so other threads can access the list
}

void remove(char *key) {
    pthread_mutex_lock(&lock); // Acquire lock to ensure thread-safety

    ConfigurationNode **link = &head;

    while (*link != NULL) {
        if (strcmp((*link)->key, key) == 0) {
            ConfigurationNode *nodeToRemove = *link;
            *link = nodeToRemove->next;

            free(nodeToRemove); // Free dynamically allocated resources
            break;
        } else {
            link = &((*link)->next);
        }
    }

    pthread_mutex_unlock(&lock); // Release lock so other threads can access the list
}

ConfigurationSettings *get(char *key) {
    pthread_mutex_lock(&lock); // Acquire lock to ensure thread-safety

    ConfigurationNode *node = head;

    while (node != NULL) {
        if (strcmp(node->key, key) == 0) {
            break;
        } else {
            node = node->next;
        }
    }

    pthread_mutex_unlock(&lock); // Release lock so other threads can access the list

    return (node != NULL) ? node->value : NULL;
}

void update(char *key, ConfigurationSettings *newValue) {
    remove(key);
    add(key, newValue);
}

char *serialize() {
    pthread_mutex_lock(&lock); // Acquire lock to ensure thread-safety

    cJSON *root = cJSON_CreateObject();

    ConfigurationNode *node = head;
    while (node != NULL) {
        cJSON *value = cJSON_CreateObject();

        cJSON_AddStringToObject(value, "integer", node->value->integer);
        cJSON_AddStringToObject(value, "string", node->value->string);
        cJSON_AddBoolToObject(value, "boolean", node->value->boolean);

        cJSON_AddItemToObject(root, node->key, value);
    }

    char *jsonString = cJSON_PrintUnformatted(root);
    cJSON_Delete(root); // We're done with this object now, so we can delete it

    pthread_mutex_unlock(&lock); // Release lock so other threads can access the list

    return jsonString;
}
```

Please note that this code doesn't include error checking for simplicity. You should add appropriate checks according to your needs, like ensuring `malloc` and `cJSON_*` calls didn't fail etc. Also, don't forget to free all dynamically allocated resources when you're done with them to avoid memory leaks.
