['Here is a high level implementation of these ideas in C using pthread library for thread safety and simple logging mechanism. 

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <assert.h>

typedef struct record {
    int value;
    int* key_ptr;
    long* offset_ptr;
    time_t lastAccessTime;
    unsigned accessCount;
} Record;

typedef struct dataSet {
    pthread_mutex_t mutex;  // To protect concurrent operations
    size_t maxSize;        // Maximum number of records
    size_t currSize;       // Current number of records in use
    Record* recordArray;   // The actual array of records
} DataSet;

DataSet* createDataset(size_t maxSize) {
    DataSet* data = malloc(sizeof(DataSet));
    if (data == NULL) {
        fprintf(stderr, "Failed to allocate memory for dataset.\n");
        return NULL;
    }

    pthread_mutex_init(&data->mutex, NULL);
    data->maxSize = maxSize;
    data->currSize = 0;
    data->recordArray = calloc(maxSize, sizeof(Record));

    if (data->recordArray == NULL) {
        fprintf(stderr, "Failed to allocate memory for record array.\n");
        free(data);
        return NULL;
    }

    return data;
}

void destroyDataset(DataSet* data) {
    assert(data != NULL);
    pthread_mutex_destroy(&data->mutex);
    for (size_t i = 0; i < data->currSize; ++i) {
        free(data->recordArray[i].key_ptr);
        free(data->recordArray[i].offset_ptr);
    }
    free(data->recordArray);
    free(data);
}
```
This code provides a simple way to manage dynamic datasets of 'Record' structures, including memory allocation and deallocation. The 'DataSet' structure contains a mutex for thread safety, the maximum size of the dataset, the current size (i.e., how many records are in use), and an array of Records.

