// This struct represents a single cache entry
typedef struct CacheEntry {
    int key;  // Key of the entry
    void *value;  // Value associated with the key
    pthread_mutex_t mutex; // Mutex for thread safety
} CacheEntry;

CacheEntry* initCache(int size) {
    CacheEntry* cache = (CacheEntry*)malloc(sizeof(CacheEntry)*size);
