["Here is an example C program using open addressing with quadratic probing as collision resolution strategy:

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct record {
    long offset;
    int key;
    int value;
} record_t;

struct hashTable {
    pthread_mutex_t lock;
    size_t capacity, count;
    double loadFactor;
    record_t **data;
};
typedef struct hashTable hashTable_t;

hashTable_t *initializeHashTable(size_t initialCapacity, double loadFactor);
void destroyHashTable(hashTable_t *table);
record_t* getRecord(hashTable_t *table, int key);
bool setRecord(hashTable_t *table, record_t *record);
static void rehash(hashTable_t *table);

hashTable_t *initializeHashTable(size_t initialCapacity, double loadFactor) {
    hashTable_t *newTable = (hashTable_t *)malloc(sizeof(hashTable_t));

    newTable->capacity = initialCapacity;
    newTable->count = 0;
    newTable->loadFactor = loadFactor;
    newTable->data = calloc(newTable->capacity, sizeof(record_t *));

    pthread_mutex_init(&newTable->lock, NULL);
    return newTable;
}

void destroyHashTable(hashTable_t *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->data[i] != NULL) {
            free(table->data[i]);
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->data);
    free(table);
}

record_t* getRecord(hashTable_t *table, int key) {
    size_t index = (size_t)key % table->capacity;

    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->data[index] != NULL && table->data[index]->key == key) return table->data[index];

        index = (index + 1) % table->capacity;  // Quadratic probing.
    }

    return NULL;
}

bool setRecord(hashTable_t *table, record_t *record) {
    pthread_mutex_lock(&table->lock);

    table->count++;
    if (((double)table->count / table->capacity) > table->loadFactor) rehash(table);

    size_t index = (size_t)record->key % table->capacity;

    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->data[index] == NULL || table->data[index]->key == record->key) {
            if (table->data[index] != NULL && table->data[index]->key != record->key) free(table->data[index]);

            table->data[index] = record;
            pthread_mutex_unlock(&table->lock);
            return true;
        }

        index = (index + 1) % table->capacity;  // Quadratic probing.
    }

    pthread_mutex_unlock(&table->lock);
    return false;
}

static void rehash(hashTable_t *table) {
    record_t **oldData = table->data;
    size_t oldCapacity = table->capacity;

    // Double the capacity.
    table->capacity <<= 1;
    table->count = 0;
    table->data = calloc(table->capacity, sizeof(record_t *));

    for (size_t i = 0; i < oldCapacity; ++i) {
        if (oldData[i] != NULL) setRecord(table, oldData[i]);

        free(oldData[i]);
    }

    free(oldData);
}
```

