ListNode* listHead = NULL;
HashTable hashTable;

// Helper function to initialize a new record
void initRecord(Record* record, int value) {
    record->value = value;
}

// Helper function to create a new linked list node
ListNode* createNode() {
    ListNode* node = malloc(sizeof(ListNode));
    node->record = NULL;
    node->next = NULL;
    return node;
}

// Custom hash function using prime number multiplication to distribute keys more uniformly
int customHash(int key) {
    return (key * 2654435761) % MAX_SIZE;
}

// Insert a new record into the hash table and linked list, handling memory allocation and resizing
void insertRecord(int key, Record* record) {
    int index = customHash(key);

    pthread_spin_lock(&hashTable.lock);

    // Handle collisions using linear probing
    while (hashTable.records[index] != NULL) {
        index++;
        if (index >= MAX_SIZE)
            index = 0;
    }

    hashTable.key[index] = key;
    hashTable.offset[index] = record - recordPool;
    hashTable.records[index] = record;

    // Append the new node to the linked list
    ListNode* newNode = createNode();
    newNode->record = record;
    if (listHead == NULL) {
        listHead = newNode;
    } else {
        newNode->next = listHead;
        listHead = newNode;
    }

    pthread_spin_unlock(&hashTable.lock);
}

