        // Initialize a new record with a random value in the specified range
        Record* record = &recordPool[i];
        initRecord(record, rand() % 100);

        // Insert the new record into the hash table and linked list
        insertRecord(arr[i], record);
    }

    // Find and print the largest integer in the array
    int maxVal = findMax(arr, size);
    printf("The largest integer is %d\n", maxVal);

    // Free all allocated memory when exiting
    free(arr);
    pthread_spin_destroy(&hashTable.lock);
    for (ListNode* node = listHead; node != NULL;) {
        ListNode* next = node->next;
        free(node);
        node = next;
    }
}
