typedef struct {
    int timestamp;
    char* key;
} Entry;

typedef struct Node{
    Entry *entry;
    struct Node *next;
}Node;

// Global variables to manage thread-safe access and memory deallocation
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 
static int destroy = 0; // flag to signal termination of threads 

// Helper function for entry creation
Entry* createEntry(char *key, int timestamp) {
    Entry *entry = malloc(sizeof(Entry));
    entry->timestamp = timestamp;
    entry->key = key;
    return entry;
}

// Helper function to insert new entries in order
void insertEntry(Node **head_ref, char *new_data, int new_timestamp) {
    Node* current;

    // Create a new node and assign data to it 
    Node *new_node = (Node*) malloc(sizeof(Node));
    new_node->entry = createEntry(new_data, new_timestamp);

    if (*head_ref == NULL || (*head_ref)->entry->timestamp >= new_node->entry->timestamp) {
        new_node->next = *head_ref;
        *head_ref = new_node;
    } else {
        current = *head_ref;
        while (current->next != NULL && current->next->entry->timestamp < new_node->entry->timestamp) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

// Function for concurrent retrieval, insertion and deletion of entries
void* storeOperations(void *arg) {
    Node **head = (Node**) arg; 

    while(!destroy) { // thread termination condition
        pthread_mutex_lock(&lock); // enter critical section 

        /* Perform insertions, retrievals and deletions here */

        pthread_mutex_unlock(&lock); // leave critical section
    }

    return NULL;
}

// Function to free all allocated memory when function exits
void destroyStore(Node **head) {
    Node *temp, *current = *head; 
    while (current != NULL) {
        temp = current->next;
        free(current->entry); // first free the data part
        free(current);         // then free node itself
        current = temp;
    }
    *head = NULL; // set head to null
}

int main() {
    Node *store = NULL; 
    pthread_t threads[2];

    /* Create two worker threads that will concurrently perform store operations */
    for(int i=0;i<2;i++)
        pthread_create(&threads[i],NULL,&storeOperations,(void*)&store);

    /* Simulate input data and perform insertion operation */
    char *data = "test";
    int timestamp = 1;  // Or generate a timestamp here based on your needs
    insertEntry(&store, data, timestamp);

    destroy=1; // Signal threads to terminate
    for(int i=0;i<2;i++)
        pthread_join(threads[i],NULL); // Wait until all threads finish their operations 

    destroyStore(&store);
}
```
