typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t size;
    size_t capacity;
} DynamicArray;

void initDynamicArray(DynamicArray *arr) {
    arr->size = 0;
    arr->capacity = 2;
    arr->records = malloc(sizeof(Record) * arr->capacity);
}

int pushBack(DynamicArray *arr, Record record) {
    if (arr->size == arr->capacity) {
        arr->capacity *= 2;
        arr->records = realloc(arr->records, sizeof(Record) * arr->capacity);
        if (!arr->records) return 0;
    }

    arr->records[arr->size++] = record;
    return 1;
}

void freeDynamicArray(DynamicArray *arr) {
    free(arr->records);
    arr->records = NULL;
    arr->capacity = 0;
    arr->size = 0;
}

typedef struct HashNode {
    Record record;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    size_t size;
    size_t capacity;
} HashTable;

void initHashTable(HashTable *ht, size_t capacity) {
    ht->size = 0;
    ht->capacity = capacity;
    ht->buckets = calloc(ht->capacity, sizeof(HashNode*));
}

int insert(HashTable *ht, Record record) {
    size_t index = record.key % ht->capacity;

    HashNode *node = malloc(sizeof(HashNode));
    if (!node) return 0;

    node->record = record;
    node->next = ht->buckets[index];
    ht->buckets[index] = node;
    ++ht->size;

    return 1;
}

int lookup(HashTable *ht, int key) {
    size_t index = key % ht->capacity;

    HashNode *node = ht->buckets[index];
    while (node && node->record.key != key) {
        node = node->next;
    }

    return !!node;
}

void freeHashTable(HashTable *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        HashNode *node = ht->buckets[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(ht->buckets);
    ht->size = 0;
    ht->capacity = 0;
}

void handleError() {
    // Log the error using your logging library.
}

Record generateRandomRecord() {
    Record record = {
        .key = rand(),
        .offset = rand()
    };

    return record;
}
