#include <string.h>

typedef struct Record {
    int value;
    long* offset_ptr;
} Record;

int manageMemory(const char* pattern, long initialOffset, long offsetRange) {
    FILE* inputStream = stdin; // Assume standard input for simplicity

    if (inputStream == NULL || fseek(inputStream, 0L, SEEK_END) != 0) {
        return -1; // Invalid or empty input stream
    }

    long inputSize = ftell(inputStream);
    rewind(inputStream);

    if (inputSize == 0) {
        return 2; // Empty input
    }

    char* inputString = malloc((inputSize + 1) * sizeof(char));
    if (inputString == NULL) {
        return -3; // Memory allocation failed
    }

    fread(inputString, sizeof(char), inputSize, inputStream);
    inputString[inputSize] = '\0'; // Ensure string is null-terminated

    long* offsets = calloc(inputSize, sizeof(long));
    if (offsets == NULL) {
        free(inputString);
        return -3; // Memory allocation failed for offsets
    }

    int* keys = malloc(inputSize * sizeof(int));
    if (keys == NULL) {
        free(inputString);
        free(offsets);
        return -3; // Memory allocation failed for keys
    }

    Record* records = calloc(inputSize, sizeof(Record));
    if (records == NULL) {
        free(inputString);
        free(offsets);
        free(keys);
        return -3; // Memory allocation failed for records
    }

    char* matchPtr = inputString;
    int keyIndex = 0, recordIndex = 0;
    while ((matchPtr = strstr(matchPtr, pattern)) != NULL) {
        keys[keyIndex++] = matchPtr - inputString; // Store index of occurrence

        long* offset_ptr = malloc(sizeof(long));
        if (offset_ptr == NULL) {
            free(inputString);
            free(offsets);
            free(keys);
            free(records);
            return -3; // Memory allocation failed for records' pointer
        }

        *offset_ptr = initialOffset + rand() % offsetRange; // Initialize with random value within range

        Record record = { 0, offset_ptr };
        records[recordIndex++] = record;

        matchPtr += strlen(pattern); // Advance to next possible occurrence
    }

    free(inputString);
    free(offsets);
    free(keys);
    for (int i = 0; i < inputSize; ++i) {
        free(records[i].offset_ptr);
    }
    free(records);

    return 1; // Success
}
```
This function receives a pattern and an initial offset range, allocates memory for four arrays: one for 'long' offset values, another for 'int' keys, and two more for 'record' structures. It reads the input string from standard input, stores occurrences of a specified pattern in the keys array using strstr function, and handles memory allocation failures by returning appropriate status codes.
