    int key;
} QueueNode;

typedef struct event {
    time_t timestamp;
} Event;

int comparator(const void* p, const void* q) {
    return (((QueueNode*)p)->key - ((QueueNode*)q)->key); 
}

void priority_queue_push(QueueNode** queue, int size, QueueNode *node) {
    if(*size == 0) {
        *queue = node;
    } else {
        *queue = realloc(*queue, (*size + 1) * sizeof(QueueNode));
        (*queue)[*size] = *node;
        qsort(*queue, *size+1, sizeof(QueueNode), comparator);
    }
}

