#include <stdatomic.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
    double measurement;
} Record;

// A simple lock-free linked list for hash table buckets.
typedef struct Node {
    atomic_int refcount;
    pthread_mutex_t lock;
    Record *record;
    struct Node *next;
} Node;

Node **hashTable = NULL;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
size_t hashTableSize = 0;

// Initialize the hash table.
void initializeHashTable(size_t size) {
    if (hashTable != NULL) {
        free(hashTable);
    }

    // Create a new hash table of the specified size.
    hashTableSize = size;
    hashTable = calloc(size, sizeof(Node*));
}

// Hashing function.
size_t hashFunction(int key) {
    return (key % hashTableSize);
}

// Add a record to the hash table.
void addRecord(Record *record) {
    size_t index = hashFunction(record->key);

    // Lock the bucket list using a reader/writer lock.
    pthread_rwlock_wrlock(&rwlock);
    Node *node = malloc(sizeof(Node));
    node->refcount = 1;
    pthread_mutex_init(&node->lock, NULL);
    node->record = record;

    // Add the new node to the beginning of the list.
    if (hashTable[index] == NULL) {
        hashTable[index] = node;
    } else {
        node->next = hashTable[index];
        atomic_fetch_add(&node->next->refcount, 1);
        hashTable[index] = node;
    }

    pthread_rwlock_unlock(&rwlock);
}

// Remove a record from the hash table.
void removeRecord(int key) {
    size_t index = hashFunction(key);

    // Lock the bucket list using a reader/writer lock.
    pthread_rwlock_wrlock(&rwlock);
    Node *prevNode = NULL;
    for (Node *node = hashTable[index]; node != NULL; prevNode = node, node = node->next) {
        // Lock the node using a normal mutex.
        pthread_mutex_lock(&node->lock);

        if (node->record->key == key) {
            // Remove this node from the list.
            if (prevNode == NULL) {
                hashTable[index] = node->next;
            } else {
                prevNode->next = node->next;
            }

            atomic_fetch_sub(&node->refcount, 1);
        }

        pthread_mutex_unlock(&node->lock);
    }

    pthread_rwlock_unlock(&rwlock);
}
```
