#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    time_t timestamp;
    int identifier;
} Event;

typedef struct TransactionNode {
    int value;
    struct TransactionNode* next;
} TransactionNode;

// Function to insert a new transaction at a specified position in the linked list
void insertTransaction(TransactionNode** head, int pos, int value) {
    TransactionNode* node = malloc(sizeof(TransactionNode));
    node->value = value;

    if (pos == 0 || *head == NULL) { // Insert at the beginning of list
        node->next = *head;
        *head = node;
    } else {
        TransactionNode* current = *head;
        for(int i = 0; i < pos - 1 && current->next != NULL; ++i) { // Move to (pos - 1)-th node
            current = current->next;
        }
        node->next = current->next; // Insert new node at the position
        current->next = node;
    }
}

int main() {
    Record* records = malloc(10 * sizeof(Record)); // Assume 10 records for the sake of illustration
    Event* events = calloc(20, sizeof(Event)); // Assume 20 events for the same reason
    TransactionNode* transactions = NULL; // Start with an empty list

    insertTransaction(&transactions, 0, 5); // Insert a new transaction at position 0

    free(records);
    free(events);
    while (transactions != NULL) { // Free memory occupied by the linked list
        TransactionNode* next = transactions->next;
        free(transactions);
        transactions = next;
    }

    return 0;
}
```
