["This task requires a lot of considerations that go beyond just code generation. Here's an outline of how you could approach this:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Structure for record 
typedef struct Record {
    int value;
} Record;

// Node structure for linked list used in separate chaining
typedef struct Node {
    long offset;
    int key;
    Record* record;
    struct Node* next;
} Node;

// Hash table data structure
typedef struct HashTable {
    int size;
    Node** table;
    pthread_mutex_t* locks;
} HashTable;

HashTable* createHashTable(int size) {
    // Allocate memory for the hash table
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = size;

    // Initialize locks for each bucket
    ht->locks = (pthread_mutex_t*)calloc(ht->size, sizeof(pthread_mutex_t));
    for (int i = 0; i < ht->size; ++i) {
        pthread_mutex_init(&(ht->locks[i]), NULL);
    }

    // Allocate memory for table itself
    ht->table = (Node**)calloc(ht->size, sizeof(Node*));
    return ht;
}

// Function to insert a key-value pair
void insert(HashTable* ht, int key, Record* record) {
    // Compute hash for the key
    int hash = key % ht->size;

    pthread_mutex_lock(&(ht->locks[hash]));
    if (ht->table[hash] == NULL) {
        // No collision, create a new node
        Node* node = (Node*)malloc(sizeof(Node));
        node->key = key;
        node->record = record;
        node->next = NULL;

        ht->table[hash] = node;
    } else {
        // Collision, append to the existing list
        Node* temp = (Node*)malloc(sizeof(Node));
        temp->key = key;
        temp->record = record;
        temp->next = ht->table[hash];

        ht->table[hash] = temp;
    }

    pthread_mutex_unlock(&(ht->locks[hash]));
}

int main() {
    // Example usage
    srand(time(0));
    HashTable* ht = createHashTable(10);

    for (int i = 0; i < 50; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->value = rand() % 100; // Initialize with a random value between 0 and 99

        insert(ht, i, record);
    }

    return 0;
}
```
