#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct node {
    double data;
    char* str;
    struct node* next;
} Node;

typedef struct entry {
    double val;
    char* id;
    Node* head;
} Entry;

typedef struct pool {
    Entry* entries;
    size_t capacity;
    atomic_size_t count;
    pthread_mutex_t lock;
} Pool;

Pool* create_pool(size_t capacity) {
    Pool* pool = malloc(sizeof(Pool));
    if (pool == NULL) return NULL;

    pool->entries = calloc(capacity, sizeof(Entry));
    if (pool->entries == NULL) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    pool->count = 0;
    pool->capacity = capacity;

    return pool;
}

Entry* allocate_entry(Pool* pool) {
    Entry* entry = NULL;

    pthread_mutex_lock(&pool->lock);
    if (atomic_load(&pool->count) < pool->capacity) {
        size_t index = atomic_fetch_add(&pool->count, 1);
        entry = &pool->entries[index];
    }
    pthread_mutex_unlock(&pool->lock);

    return entry;
}

Node* allocate_node(Pool* pool) {
    Node* node = malloc(sizeof(Node));
    if (node != NULL) {
        memset(node, 0, sizeof(Node));
    }

    return node;
}
```
