        perror("Allocation Error: ");
        return NULL;
    }

    for(size_t i = 0; i < numItems; ++i){
        items[i] = (data_item*)malloc(sizeof(data_item));

        if(!items[i]) {
            perror("Allocation Error: ");
            return NULL;
