        items[i]->buffer = (char*)malloc(substrLen + 1);

        if(!items[i]->buffer){ 
            perror("Allocation Error: ");
            return NULL;
        }

        strncpy(items[i]->buffer, input + i * substrLen, substrLen);
        items[i]->buffer[substrLen] = '\0';

        items[i]->index = i;
    }

    return items;
}

void freeDataItems(data_item** items, size_t numItems){
    for(size_t i = 0; i < numItems; ++i) {
        free(items[i]->buffer);
        free(items[i]);
    }

    free(items);
}

void performOperationOnDataItems(data_item** items, size_t numItems, void (*operation)(data_item*)){
