#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    int value;
    char* buffer;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    size_t allocatedSize; 
    size_t maxSize;
    Record** records; // Array of pointers to Records.
    void (*logger)(const char*); // Logging function provided by the logging framework.
} Database;

// Function to initialize a database, setting up all required fields and memory allocation
Database* init_database(size_t maxSize, void (*logger)(const char*)) {
    Database* db = malloc(sizeof(Database));
    pthread_mutex_init(&db->mutex, NULL); // Initialize mutex for thread safety.
    db->maxSize = maxSize;
    db->allocatedSize = 0;
    db->records = malloc(sizeof(Record*));
    db->logger = logger;
    return db;
}

// Function to add a record in the database. This is where we would allocate memory for individual records
void add_record(Database* db, int key, int value) {
    pthread_mutex_lock(&db->mutex); // Lock mutex before accessing shared data.

    if (db->allocatedSize + sizeof(Record) > db->maxSize) {
        pthread_mutex_unlock(&db->mutex); // Unlock if we can't allocate more memory
        return;
    }

    Record* record = malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    record->buffer = malloc(key); // Allocating buffer according to the key. 

    db->records[db->allocatedSize] = record;
    db->allocatedSize += sizeof(Record);

    pthread_mutex_unlock(&db->mutex); // Unlock after we're done accessing shared data.
}

// Function to retrieve a record from the database
Record* get_record(Database* db, int key) {
    pthread_mutex_lock(&db->mutex); // Lock mutex before accessing shared data.

    for (int i = 0; i < db->allocatedSize / sizeof(Record); ++i) {
        if (db->records[i]->key == key) {
            pthread_mutex_unlock(&db->mutex); // Unlock after we're done accessing shared data.
            return db->records[i];
        }
    }

    pthread_mutex_unlock(&db->mutex); // Unlock after we're done accessing shared data.

    return NULL; // Return null if the record is not found
}

// Function to free up all resources of a database
void free_database(Database* db) {
    pthread_mutex_lock(&db->mutex); // Lock mutex before accessing shared data.

    for (int i = 0; i < db->allocatedSize / sizeof(Record); ++i) {
        free(db->records[i]->buffer);
        free(db->records[i]);
    }

    free(db->records);
    pthread_mutex_unlock(&db->mutex); // Unlock after we're done accessing shared data.
    pthread_mutex_destroy(&db->mutex); // Destroy mutex before freeing the database.
    free(db);
}
