    char* buffer;
    int index;
} data_item;

// A cache to store reusable data_items 
data_item** cache;
int cache_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_cache() {
    cache = malloc(10000 * sizeof(data_item*));  // Initialize the cache with a certain size
}

// Function to get data_items from the cache. Returns null if not found in cache
data_item* get_from_cache(int index) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < cache_size; i++) {
        if (cache[i]->index == index) {
            data_item* item = cache[i];

            // Move the fetched item to the end of cache, promoting it 
            memmove(&cache[i], &cache[i + 1], (cache_size - i - 1) * sizeof(data_item*));
            cache[cache_size - 1] = item;

            pthread_mutex_unlock(&mutex);
            return item;
        }
    }

    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to add data_items to the cache
void add_to_cache(data_item* item) {
    pthread_mutex_lock(&mutex);
    if (cache_size < 10000) {  // Maximum size of cache is 10000
        cache[cache_size++] = item;
    } else {
        free(cache[0]->buffer);  // Remove the oldest item from memory when full
        memmove(&cache[0], &cache[1], (cache_size - 1) * sizeof(data_item*));
        cache[cache_size - 1] = item;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to generate a data_item from input string and index
data_item* create_data_item(char* input, int start, int end, int index) {
    data_item* item = malloc(sizeof(data_item));

    // Allocate memory for the buffer +1 for null-termination
    item->buffer = calloc((end - start + 2), sizeof(char));  

    strncpy(item->buffer, &input[start], end - start + 1);  // Copy substring to buffer
    item->index = index;

    return item;
}
```
