// a fixed-size memory pool for data_items
#define POOL_SIZE 10000
static data_item data_pool[POOL_SIZE];
atomic_int next_free = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// function to allocate a new data_item from the pool.
data_item *allocate_data_item() {
    pthread_mutex_lock(&pool_lock);
    if(next_free >= POOL_SIZE) {
        // handle error, out of space in the pool.
        exit(-1);
    }

    data_item *result = &data_pool[atomic_fetch_add(&next_free, 1)];
    pthread_mutex_unlock(&pool_lock);

    result->buffer = malloc(BUFFER_SIZE); // assuming BUFFER_SIZE is defined elsewhere.
    if(result->buffer == NULL) {
        // handle error, out of memory for buffer allocation.
        exit(-1);
    }

    return result;
}

// function to free a data_item back into the pool.
void deallocate_data_item(data_item *di) {
    free(di->buffer); // release memory for buffer.
    di->buffer = NULL; // clear pointer in data_item structure.

    pthread_mutex_lock(&pool_lock);
    atomic_fetch_sub(&next_free, 1);
    pthread_mutex_unlock(&pool_lock);
}

// function to iterate over all data items.
void for_each_data_item(void (*callback)(data_item *di)) {
    // acquire lock before accessing the pool.
    pthread_mutex_lock(&pool_lock);

    int size = next_free;
    for(int i = 0; i < size; ++i) {
        callback(&data_pool[i]);
    }

    // release lock after all items are processed.
    pthread_mutex_unlock(&pool_lock);
}
```

