    indices = (int*) calloc(10000, sizeof(int));         // Similarly adjust these sizes as needed.
    points = (point*) malloc(sizeof(point) * 20000000);   // Allocating memory for points array.
    paths = (path**) calloc(1000, sizeof(path*));         // Allocating memory for path index.

    readFromFile("coordinates.txt", &coordinates, 20000000);
}

