    for (int i = 0; i < 1000; i++) {
        paths[i] = (path*) malloc(sizeof(path));
        pthread_mutex_init(&paths[i]->mutex, NULL);
    }
}

void insertIntoIndex(point *p){
  int index = p->id % 1000; // Assumes indices are within a range.
  pthread_rwlock_wrlock(&lock);

  node* newNode = (node*) malloc(sizeof(node));
  newNode->data = p;
  newNode->next = paths[index]->head;
  paths[index]->head = newNode;

  pthread_rwlock_unlock(&lock);
}

void freeMemory() {
    for (int i = 0; i < 1000; i++) {
        node* temp;
        while(paths[i]->head != NULL){
            temp = paths[i]->head->next;
            free(paths[i]->head);
            paths[i]->head = temp;
        }
    pthread_mutex_destroy(&paths[i]->mutex);
    free(paths[i]);
  }

  free(indices);
  free(points);
  free(coordinates);
}
