#include <stdlib.h>
#include <pthread.h>
#include <urcu-qsbr.h>  /* RCU lock */
#include <rculist.h>   /* RCU linked list library */

/* Define a struct for sensor data entry */
typedef struct {
    time_t timestamp;
    bool precision;
    int value;
    uint64_t id;
} sensor_data;

/* Define a node in the database, which points to a sensor_data object */
struct cds_list_head myNode {
  struct cds_list_head list; /* List head used by RCU linked list library */
  struct rcu_head rcu;       /* Used for graceful cleanup during updates */
  sensor_data *data;         /* The actual data */
};

/* Define the database as a pointer to the first node in our linked list. */
struct cds_list_head *database = NULL;

pthread_mutex_t dbLock = PTHREAD_MUTEX_INITIALIZER; /* Lock for concurrent write operations */

/* Insertion into database, protected by a mutex for serialized writes */
void insert(sensor_data *data) {
  struct myNode *node = malloc(sizeof(struct myNode));

  node->data = data;

  pthread_mutex_lock(&dbLock);
  cds_list_add_rcu(node->data, &database); /* Add to the database */
  synchronize_rcu();                       /* Ensure all readers see consistent state */
  pthread_mutex_unlock(&dbLock);
}

/* Retrieval from database, protected by RCU for concurrent reads with no lock overhead */
sensor_data *retrieve(uint64_t id) {
  sensor_data *result = NULL;

  cds_list_for_each_rcu(database, pos) {
    if (cds_list_entry(pos, struct myNode, list)->data->id == id) {
      result = cds_list_entry(pos, struct myNode, list)->data;
      break;
    }
  }

  return result;
}

/* Cleanup routine to free all allocated resources */
void cleanup() {
  pthread_mutex_lock(&dbLock);
  cds_list_for_each_safe(database, pos, n) {
    struct myNode *node = cds_list_entry(pos, struct myNode, list);

    /* Free the sensor_data object */
    free(node->data);

    /* Remove from the database */
    cds_list_del_rcu(pos);
    synchronize_rcu(); 

    /* Now we're safe to free our node object */
    free(node);
  }

  pthread_mutex_unlock(&dbLock);
}
```
This example assumes you have a suitable memory pool for the `sensor_data` objects, which is not shown here. The slab allocator from the Linux kernel's libslab2 library could be used to achieve this. This would help with fragmentation and cache efficiency. 

