Please note that the code below does not implement all requested features. It is just a starting point:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <search.h>
#include "avl.h" // GNU libavl library for AVL tree

typedef struct item {
    char name[50];
    int quantity;
    float price;
} item_t;

typedef struct node {
    item_t *item;
    struct node *left, *right;
} node_t;

node_t *root = NULL;
pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;

int compare(const void *pa, const void *pb, void *param) {
    item_t **a = (item_t **)pa;
    item_t **b = (item_t **)pb;
    return strcmp((*a)->name, (*b)->name);
}

void insert(item_t *item) {
    pthread_rwlock_wrlock(&lock);
    node_t **ppnode = tfind(&item, &root, compare);
    if (ppnode != NULL) {
        (*ppnode)->item->quantity += item->quantity;
        free(item);
    } else {
        node_t *node = malloc(sizeof(node_t));
        node->item = item;
        node->left = node->right = NULL;
        tsearch(item, &root, compare);
    }
    pthread_rwlock_unlock(&lock);
}

void delete(const char *name) {
    pthread_rwlock_wrlock(&lock);
    item_t target;
    strncpy(target.name, name, sizeof(target.name));
    node_t **ppnode = tfind(&target, &root, compare);
    if (ppnode != NULL) {
        tdelete(*ppnode, &root, compare);
        free((*ppnode)->item);
        free(*ppnode);
    }
    pthread_rwlock_unlock(&lock);
}

item_t *search(const char *name) {
    item_t target;
    strncpy(target.name, name, sizeof(target.name));
    pthread_rwlock_rdlock(&lock);
    node_t **ppnode = tfind(&target, &root, compare);
    if (ppnode != NULL) {
        item_t *item = malloc(sizeof(item_t));
        memcpy(item, (*ppnode)->item, sizeof(item_t));
        pthread_rwlock_unlock(&lock);
        return item;
    } else {
        pthread_rwlock_unlock(&lock);
        return NULL;
    }
}
```

The code above provides a basic thread-safe insert, delete and search operations using read/write locks in POSIX threads. 

