    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // 1. Dynamically allocate memory for an array of `float` values.
    float* intervals = malloc(sizeof(*intervals) * arraySize);
    if (!intervals) {
        exit(-1);
    }
    memset(intervals, userSpecifiedValue, sizeof(*intervals) * arraySize);

