    for (size_t i = 0; i < arraySize; ++i) {
        strings[i] = malloc(maxStringLength + 1);
        if (!strings[i]) {
            // Free all previously allocated memory and exit.
            while (i-- > 0) free(strings[i]);
            free(intervals);
            exit(-1);
