std::mutex networkDataMutex;  // mutex for network data sync
int playerSuccessCount = 0;   // count of successful attacks
double attackPower = 1.0;     // initial attack power
unsigned int cooldownSeconds = 9; // initial cooldown period
bool lastAttackSucceeded = false;  // flag for last attack status
std::unordered_map<std::string, std::any> networkData; // map to store network data

// function to handle network latency issues and update player stats
void UpdatePlayerStats() {
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(1));  // simulate server delay
        std::lock_guard<std::mutex> guard(networkDataMutex);
        if (!networkData.empty()) {  // if data is available, update player stats
            lastAttackSucceeded = std::any_cast<bool>(networkData["lastAttackStatus"]);
            networkData.clear();
        }
    }
}

// function to handle attack logic and cooldown adjustment
void Attack() {
    while (true) {
        if (cooldownSeconds > 0 || !lastAttackSucceeded) {  // if in cooldown or last attack failed
            std::this_thread::sleep_for(std::chrono::seconds(1));  // sleep until cooldown ends
            continue;
        }

        std::lock_guard<std::mutex> guard(networkDataMutex);  // lock network data mutex

        if (!networkData.empty()) {  // handle partial updates
            lastAttackSucceeded = std::any_cast<bool>(networkData["lastAttackStatus"]);
            networkData.clear();
        }

        if (lastAttackSucceeded) {  // process successful attack
            ++playerSuccessCount;
            if (playerSuccessCount >= 5) {  // increase attack power by 10% after every 5 successful attacks
                playerSuccessCount = 0;
                attackPower *= 1.1;
            }
        } else {  // reset cooldown to initial value after failed attack
            cooldownSeconds = 9;
        }
    }
}

// function to select a random attack from the five options and return it
std::string SelectAttack() {
    std::array<std::string, 5> attacks = {"attack1", "attack2", "attack3", "attack4", "attack5"};
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<> dis(0, 4);

    return attacks[dis(gen)];
}

// entry point function that starts the attack and network data update threads
void StartGame() {
    std::thread t1(Attack);
    std::thread t2(UpdatePlayerStats);

    t1.join();
    t2.join();
}
```
