};

void free_all(struct DataStructures* data) {
    if (data != NULL) {
        if (data->offsets != NULL) {
            free(data->offsets);
        }
        if (data->keys != NULL) {
            free(data->keys);
        }
        if (data->records != NULL) {
            free(data->records);
        }
    }
}

struct DataStructures* initialize_data_structures(offset_t max_offset, key_t max_key, size_t max_records) {
    struct DataStructures *data = malloc(sizeof(*data));

    if (data == NULL || (data->offsets = malloc(max_offset* sizeof(*data->offsets))) == NULL 
        || (data->keys = malloc(max_key * sizeof(*data->keys))) == NULL 
        || (data->records = calloc(max_records, sizeof(*data->records))) == NULL) {
        // Handle memory allocation error
        free_all(data);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (offset_t i = 0; i < max_offset; ++i) {
        data->offsets[i] = i;
