```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct sensor_data {
    int deviceID;
    int networkID;
    float temperature;
    char status[10]; // status can be 'OK', 'FAIL', etc.
} SensorData;

typedef struct node {
    struct node *next;
    SensorData data;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL; // linked list, where each node contains sensor data.
float maxTemp = 0;
float minTemp = 100;
int count = 0;
const int windowSize = 5; 

void *update(void *arg) {
    float temperature;
    SensorData new_data;

    while (scanf("%f", &temperature) != EOF) { // read from standard input.
        pthread_mutex_lock(&lock);

        count++;
        if(count > windowSize) {
            Node* temp = head;
            head = head->next;

            maxTemp = (temp->data.temperature > maxTemp)? temp->data.temperature : maxTemp; 
            minTemp = (temp->data.temperature < minTemp)? temp->data.temperature : minTemp; 

            free(temp);
        } else {
            Node* new_node = malloc(sizeof(Node)); // dynamic memory allocation for sensor data.
            new_node->next = head;
            new_node->data.temperature = temperature;
            head = new_node;

            if (count == 1) {
                maxTemp = minTemp = temperature;
            } else {
                maxTemp = (temperature > maxTemp)? temperature : maxTemp; 
                minTemp = (temperature < minTemp)? temperature : minTemp; 
            }
        }

        pthread_mutex_unlock(&lock);
    }

    return NULL;
}
