["Here's a high-level code example in C to satisfy your requirements:

```C
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    float sensor_reading;
    char quality_label;
} SensorData;

typedef struct Node {
    SensorData data;
    int priority;
    struct Node* next;
} PriorityQueueNode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
PriorityQueueNode *queueHead = NULL;
int queueSize = 0;

void push(SensorData data, int priority) {
    pthread_mutex_lock(&lock);
    ++queueSize;
    PriorityQueueNode* node = malloc(sizeof(PriorityQueueNode));
    assert(node != NULL); // check if memory allocation was successful
    node->data = data;
    node->priority = priority;
    node->next = NULL;

    if (queueHead == NULL || queueHead->priority < priority) {
        node->next = queueHead;
        queueHead = node;
    } else {
        PriorityQueueNode* temp = queueHead;
        while (temp->next != NULL && temp->next->priority >= priority) {
            temp = temp->next;
        }
        node->next = temp->next;
        temp->next = node;
    }

    pthread_mutex_unlock(&lock);
}

SensorData pop() {
    assert(queueHead != NULL); // check if queue is not empty
    --queueSize;
    SensorData data = queueHead->data;
    PriorityQueueNode* temp = queueHead;
    queueHead = queueHead->next;
    free(temp);
    return data;
}

SensorData peek() {
    assert(queueHead != NULL); // check if queue is not empty
    return queueHead->data;
}
``` 
This code provides a basic priority queue implementation. The `push` function inserts elements into the queue based on their priorities, while the `pop` and `peek` functions remove and retrieve, respectively, the highest priority element from the queue. All these operations are guarded by a mutex to ensure thread-safe access. 

The logging functionality is not included in this basic code example as it can become quite complex depending on the specific requirements of your project. You might want to consider using an established library or framework for logging, like log4c, log4cpp, glog, spdlog, etc., which provide various levels of logging verbosity and integrate well with existing systems.
