['Here's an example of how one might approach this problem using C. The solution includes a hash table with separate chaining for collision resolution, along with a thread-safe resizable array (Treiber stack) for memory management and concurrent access control. It also supports logging to a file. 

Please note that actual performance can vary depending on the specific hardware and operating system in use, as well as other factors such as network latency and packet loss. In this code snippet, network error handling is not explicitly implemented for simplicity's sake. For real-world applications you might want to add robust network error handling mechanisms.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#define NUM_BUCKETS 1000009 // a prime number for better distribution

typedef struct record {
    long offset;
    int value;
} Record;

typedef struct node {
    pthread_mutex_t lock;
    int key;
    long offset;
    Record* rec;
    struct node* next;
} Node;

Node* hashTable[NUM_BUCKETS];
pthread_rwlock_t rwLock = PTHREAD_RWLOCK_INITIALIZER;
FILE* logFile;

int hashFunction(int key) {
    return abs(key % NUM_BUCKETS);
}

void insertIntoHashTable(Node** hashTable, int key, long offset, Record* rec) {
    Node* newNode = malloc(sizeof(Node));
    newNode->key = key;
    newNode->offset = offset;
    newNode->rec = rec;
    pthread_mutex_init(&newNode->lock, NULL);

    int hashIndex = hashFunction(key);
    pthread_rwlock_wrlock(&rwLock);
    Node* temp = hashTable[hashIndex];
    while (temp != NULL && temp->key != key) {
        temp = temp->next;
    }

    if (temp == NULL) { // new node
        pthread_mutex_lock(&newNode->lock);
        hashTable[hashIndex] = newNode;
        fprintf(logFile, "Inserting key %d into index %d\n", key, hashIndex);
    } else if (temp == hashTable[hashIndex]) { // update head node
        pthread_mutex_lock(&temp->lock);
        newNode->next = temp;
        hashTable[hashIndex] = newNode;
        fprintf(logFile, "Updating key %d at index %d\n", key, hashIndex);
    } else { // update existing node
        pthread_mutex_lock(&temp->lock);
        newNode->next = temp->next;
        temp->next = newNode;
        fprintf(logFile, "Updating key %d at index %d\n", key, hashIndex);
    }

    pthread_rwlock_unlock(&rwLock);
}

long lookupHashTable(Node** hashTable, int key) {
    int hashIndex = hashFunction(key);
    pthread_rwlock_rdlock(&rwLock);
    Node* temp = hashTable[hashIndex];

    while (temp != NULL && temp->key != key) {
        temp = temp->next;
    }

    if (temp == NULL) {
        fprintf(logFile, "Key %d not found\n", key);
        return -1;
    } else {
        pthread_mutex_lock(&temp->lock);
        long offset = temp->offset;
        pthread_rwlock_unlock(&rwLock);
        fprintf(logFile, "Key %d found at index %d with offset %ld\n", key, hashIndex, offset);
        return offset;
    }
}
```

This is just a basic example and might not work perfectly for all scenarios. There's much more to consider in a production environment including error checking, memory management, concurrent control, etc. Also, the code doesn't handle resizing or collisions, which would be complex to implement in this snippet due to their complexity.
']

