```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Record structure
typedef struct record {
    int value;
    char *identifier;
} record;

// Hash table entry
typedef struct hash_entry {
    int key;
    long offset;
    record *data;
    struct hash_entry *next;
} hash_entry;

hash_entry **table;
int table_size = 1024; // initial size of the hash table
pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;

// Hash function, simple modulus operation
long hash(int key) {
    return key % table_size;
}

record *create_record() {
    record *r = malloc(sizeof(record));

    // Random value generation
    srand((unsigned int) time(NULL));
    r->value = rand();

    // Identifier generation, assume seed and length are provided
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJK...";
    size_t stringLen = 10;
    r->identifier = malloc(stringLen + 1);

    for (size_t n = 0; n < stringLen; ++n) {
        int key = rand() % (int)(sizeof charset - 1);
        r->identifier[n] = charset[key];
    }

    r->identifier[stringLen] = '\0';

    return r;
}

// Dynamically allocate space for hash table and initialize it with NULL
void init_table() {
    table = malloc(sizeof(hash_entry *) * table_size);

    if (pthread_rwlock_init(&lock, NULL) != 0){
        printf("Failed to initialize rw lock\n");
        exit(-1);
    }

    for (int i = 0; i < table_size; ++i) {
        table[i] = NULL;
    }
}

// Function to insert a record into the hash table with concurrency control
void put(int key, long offset, record *data){
    pthread_rwlock_wrlock(&lock);

    // Create new entry
    hash_entry *new_entry = malloc(sizeof(hash_entry));
    new_entry->key = key;
    new_entry->offset = offset;
    new_entry->data = data;
    new_entry->next = NULL;

    long hash_value = hash(key);
    if (table[hash_value] == NULL) {
        table[hash_value] = new_entry;
    } else {
        // Handle collisions by chaining
        hash_entry *current_entry = table[hash_value];

        while (current_entry->next != NULL){
            current_entry = current_entry->next;
        }

        current_entry->next = new_entry;
    }

    pthread_rwlock_unlock(&lock);
}

// Function to search for a record by key, with concurrency control
record *get(int key){
    pthread_rwlock_rdlock(&lock);

    long hash_value = hash(key);
    hash_entry *current_entry = table[hash_value];

    while (current_entry != NULL) {
        if (current_entry->key == key){
            pthread_rwlock_unlock(&lock);
            return current_entry->data;
        }

        current_entry = current_entry->next;
    }

    pthread_rwlock_unlock(&lock);
    return NULL; // Not found
}
```
The above code is a simplified demonstration and doesn't cover all the points mentioned in your question. You will have to extend this solution with more features like: dynamic resizing of hash table, collision resolution strategies, handling variable-sized datasets, efficient serialization/deserialization, etc. It's also important to remember that while C provides low-level control over memory management, it does not inherently support automatic garbage collection or thread safety. Therefore, you must manually manage memory and deal with potential concurrency issues yourself when working in a multi-threaded environment.
