    size_t index = hash(key) % table->capacity;
    for (int i = 0; i < table->capacity; ++i) {
        if (!table->records[(index + i * i) % table->capacity]) {
            table->records[(index + i * i) % table->capacity] = newRecord;
            ++(table->count);
            break;
        }
    }

    pthread_mutex_unlock(&table->mutex);
}
