#include <pthread.h>

typedef struct {
    long offset;
    double element;
    int value;
} Record1;

typedef struct {
    int value;
} Record2;

typedef struct HashNode {
    int key;
    long offset;
    pthread_mutex_t mutex; // for concurrent access control
    struct HashNode *next;
} HashNode;

HashNode **hashTable = NULL;
int hashSize = 0;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

void* allocateMemory(size_t size, int count) {
    void *ptr = calloc(count, size);
    if (ptr == NULL) {
        printf("Failed to allocate memory.\n");
        exit(1);
    }
    return ptr;
}

void initializeArraysAndHashTable(int offsetCount, int lengthCount, int keyCount, 
                                 int record1Count, int record2Count) {
    // Allocate memory for arrays.
    long *offsets = allocateMemory(sizeof(long), offsetCount);
    int *lengths = allocateMemory(sizeof(int), lengthCount);
    int *keys = allocateMemory(sizeof(int), keyCount);
    Record1 *records1 = allocateMemory(sizeof(Record1), record1Count);
    Record2 *records2 = allocateMemory(sizeof(Record2), record2Count);

    // Initialize hash table.
    hashSize = 1000; // Choose a prime number for better distribution.
    hashTable = (HashNode**) calloc(hashSize, sizeof(HashNode*));
}

void addToHashTable(int key, long offset) {
    int index = abs(key % hashSize);

    pthread_rwlock_wrlock(&rwlock); // Acquire write lock.
    HashNode *node = (HashNode*) malloc(sizeof(HashNode));
    node->key = key;
    node->offset = offset;
    node->next = hashTable[index];

    pthread_mutex_init(&node->mutex, NULL); // Initialize mutex for concurrent access control.
    hashTable[index] = node;
    pthread_rwlock_unlock(&rwlock); // Release write lock.
}

long getOffsetFromHashTable(int key) {
    int index = abs(key % hashSize);

    pthread_rwlock_rdlock(&rwlock); // Acquire read lock.
    HashNode *node = hashTable[index];
    while (node != NULL && node->key != key) {
        node = node->next;
    }
    long offset = 0;
    if (node != NULL) {
        pthread_mutex_lock(&node->mutex); // Acquire mutex for concurrent access control.
        offset = node->offset;
        pthread_mutex_unlock(&node->mutex); // Release mutex.
    }
    pthread_rwlock_unlock(&rwlock); // Release read lock.

    return offset;
}
```
