    struct device *next;
} Device;

typedef struct PriorityQueue {
    pthread_mutex_t lock;
    Device *head;
} PriorityQueue;

PriorityQueue* initQueue() {
    PriorityQueue *queue = malloc(sizeof(PriorityQueue));
    if (pthread_mutex_init(&queue->lock, NULL) != 0) {
        free(queue);
        return NULL; 
    }
    queue->head = NULL;
    return queue;
}

void destroyQueue(PriorityQueue *queue) {
    pthread_mutex_destroy(&queue->lock);
    Device *current, *nextNode;
    for (current = queue->head; current != NULL;) {
        nextNode = current->next;
        free(current);
        current = nextNode;
    }
    free(queue);
}

void addDevice(PriorityQueue *queue, int id) {
    pthread_mutex_lock(&queue->lock);  // Locking before critical section starts

    Device *newDevice = malloc(sizeof(Device));
    newDevice->id = id;
    time(&newDevice->timestamp);
    newDevice->next = NULL;

    /* insertion logic here, e.g., ordered by timestamp */
    if (queue->head == NULL || queue->head->timestamp < newDevice->timestamp) {
        newDevice->next = queue->head;
        queue->head = newDevice;
    } else {
        Device *current;
        for (current = queue->head; current->next != NULL; current = current->next) 
            if (current->next->timestamp < newDevice->timestamp) break;

        newDevice->next = current->next;
        current->next = newDevice;
    }

    pthread_mutex_unlock(&queue->lock);  // Unlocking after critical section ends
}
```
