["Here's an example of how to implement such a function in C. Note that the `record` structure is defined with four fields: a key (int), a value (int*), a short field, and a mutex for synchronization:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int key;
    int *value;
    short field;
    pthread_mutex_t mutex;
} Record;

typedef struct array {
    long *offsets;
    int *keys;
    Record **records;
} Array;

Array* initialize(size_t offsetSize, size_t keySize, size_t recordSize, int seed) {
    srand(seed); // set the random seed for consistent values across multiple invocations with same seed.

    // allocate memory for arrays
    Array *array = malloc(sizeof(Array));
    if (!array) return NULL;  // handle allocation failure
    array->offsets = calloc(offsetSize, sizeof(long));
    if (!array->offsets) {
        free(array);
        return NULL;  // handle allocation failure
    }
    array->keys = malloc(keySize * sizeof(int));
    if (!array->keys) {
        free(array->offsets);
        free(array);
        return NULL;  // handle allocation failure
    }
    array->records = calloc(recordSize, sizeof(Record*));
    if (!array->records) {
        free(array->keys);
        free(array->offsets);
        free(array);
        return NULL;  // handle allocation failure
    }

    // Initialize records with random values.
    for (size_t i = 0; i < recordSize; i++) {
        Record *record = malloc(sizeof(Record));
        if (!record) continue; // handle allocation failure, continue initialization where possible

        pthread_mutex_init(&record->mutex, NULL);  // initialize mutex for thread safety
        record->value = malloc(sizeof(int));
        *record->value = rand();  // set random value within a specified range
        array->records[i] = record;
    }

    return array;
}
```

This function initializes three separate arrays and returns them in a structure. It uses `calloc` for the offsets array, because the contents will be all zeros, while it uses `malloc` for the keys array and the records array, to allow dynamic scaling of these arrays without reusing memory blocks or allocating too much unnecessary memory.

To manage the initialization process in case of external data source failures, the function handles allocation errors by returning NULL immediately after a failed allocation, leaving no resources allocated before that point. It also uses `pthread_mutex_init` to ensure thread safety when accessing records.
