void* alignedAlloc(size_t size, size_t alignment) {
    void *p1 = NULL; // original block
    void **p2 = NULL; // new pointer to the new memory block
    int offset = alignment - 1 + sizeof(void*);
    if ((p1 = (void *)malloc(size + offset)) == NULL) {
        return NULL;
    }
    p2 = (void **)(((size_t)(p1)+offset)&~(alignment-1));
    p2[-1] = p1;
    return p2;
}

int allocateArrays(size_t offsetSize, size_t keySize, size_t recordSize, size_t metadataSize, int *overflow) {
    long* offsets = alignedAlloc(offsetSize * sizeof(long), 8); // align to a 64-bit boundary
    if (offsets == NULL) {
        return -1;
