Node* create_list(size_t list_size, size_t tasks_per_node) {
    // Create the linked list
    Node *head = NULL;
    Node *tail = NULL;
    for (size_t i = 0; i < list_size; ++i) {
        Task *new_task = malloc(sizeof(Task));
        new_task->num_objects = tasks_per_node;
        new_task->objects = calloc(tasks_per_node, sizeof(Object*));  // Allocate objects in one go.
        pthread_mutex_init(&new_task->lock, NULL);
        for (size_t j = 0; j < tasks_per_node; ++j) {
            new_task->objects[j] = malloc(sizeof(Object));  // Allocate each object separately.
            new_task->objects[j]->string = NULL;  // Initialize string to NULL for later allocation.
        }

        Node *new_node = malloc(sizeof(Node));
        new_node->task = new_task;
        if (head == NULL) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    return head;
}
```
