["Here's a partial implementation in C using OpenMP for parallel processing and pthreads for thread synchronisation. Note that this is a significant undertaking and would need to be expanded significantly based on the specific requirements.

```c
#include <stdlib.h>
#include <omp.h>
#include <pthread.h>

typedef struct {
    int value;
} record_t;

// Global variables for shared data structures
long *offsets = NULL;
int *keys = NULL;
record_t *records = NULL;
size_t size = 0;

pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;

void allocate_memory(size_t new_size) {
    long* new_offsets = (long*)realloc(offsets, sizeof(long)*new_size);
    if (!new_offsets) exit(1); // Handle memory allocation failure

    int* new_keys = (int*)realloc(keys, sizeof(int)*new_size);
    if (!new_keys) { free(new_offsets); exit(1); } // Handle memory allocation failure

    record_t* new_records = (record_t*)realloc(records, sizeof(record_t)*new_size);
    if (!new_records) { free(new_keys); free(new_offsets); exit(1); } // Handle memory allocation failure

    offsets = new_offsets;
    keys = new_keys;
    records = new_records;
    size = new_size;
}

void initialize() {
    #pragma omp parallel for schedule(dynamic)
    for (size_t i = 0; i < size; ++i) {
        pthread_rwlock_wrlock(&lock); // Lock for concurrent write access
        offsets[i] = rand(); // Set a random value
        keys[i] = rand(); // Set a random key
        records[i].value = rand(); // Set a random record value
        pthread_rwlock_unlock(&lock); // Unlock after write access
    }
}

void deallocate() {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    allocate_memory(1000000); // Allocate memory for 1 million records

    initialize(); // Initialize values and keys in parallel

    deallocate(); // Deallocate all resources

    return 0;
}
```
This code allocates memory for arrays of offsets, keys and records using realloc(). Initialization is performed concurrently in a loop using OpenMP. Readers/writers locks (pthread_rwlock_t) are used to ensure that multiple threads can read the array simultaneously, but only one thread can write to it at a time. This ensures data integrity without requiring significant lock contention or global synchronization primitives. When done processing, all memory allocated is deallocated.

