typedef struct point {
    float x;
    float y;
} Point;

typedef enum shapeType { CIRCLE, RECTANGLE } ShapeType;

typedef struct shape {
    ShapeType type;
    Point* location;
} Shape;

// Our memory pool will be an array of void pointers.
void** memoryPool = NULL; 
size_t poolSize = 0; // current size of the pool.
pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;

// For persistent storage we'll just append to a log file.
char* logFilePath = "memory.log"; 
FILE* logFile = NULL;
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void check_error(int result, const char* message) {
    if (result != 0) {
        fprintf(stderr, "%s\n", message);
        exit(-1);
    }
}

// Allocate memory from the pool. Thread safe.
void* alloc_from_pool(size_t size) {
    pthread_mutex_lock(&poolMutex);

    if (memoryPool == NULL || poolSize < size) {
        // Reallocate the pool to a bigger size.
        size_t newSize = size > poolSize * 2 ? size : poolSize * 2;
        void* newMemoryPool = realloc(memoryPool, newSize * sizeof(void*));
        check_error(newMemoryPool == NULL, "Failed to re-allocate memory");
        memoryPool = newMemoryPool;
    }

    // Return the next available location in the pool.
    void* allocation = malloc(size);
    check_error(allocation == NULL, "Failed to allocate memory");
    memoryPool[poolSize++] = allocation;

    pthread_mutex_unlock(&poolMutex);
    return allocation;
}

// Free all allocated memory when exiting. Thread safe.
void free_all() {
    pthread_mutex_lock(&poolMutex);

    // Free every item in the pool.
    for (size_t i = 0; i < poolSize; ++i) {
        free(memoryPool[i]);
    }

    // Also free the array holding them and reset its size.
    free(memoryPool);
    memoryPool = NULL;
    poolSize = 0;

    pthread_mutex_unlock(&poolMutex);
}

// Log an event to our log file. Thread safe.
void log_event(const char* message) {
    pthread_mutex_lock(&logMutex);

    if (logFile == NULL) {
        // Open the log file for appending.
        logFile = fopen(logFilePath, "a");
        check_error(logFile == NULL, "Failed to open log file");
    }

    // Write the message to the log file.
    int result = fprintf(logFile, "%s\n", message);
    check_error(result < 0, "Failed to write to log file");

    pthread_mutex_unlock(&logMutex);
}
```

This is a simplistic approach and doesn't fully fulfill all requirements. For instance, managing the rotation of log files or implementing a user-provided transformation function would require more advanced code. Similarly, handling the `shape` array with varying workloads and avoiding bottlenecks requires additional considerations.
