['Here is a simplified version of how you might code this in C language using open addressing (double hashing) for collision resolution. Note that this code does not contain all the optimizations mentioned in your requirements, such as separate chaining or dynamic memory management strategies for large datasets, and does not handle concurrency control at the thread level.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
} record;

typedef struct {
    int key;
    long offset;
} hash_entry;

typedef struct {
    hash_entry* entries;
    size_t capacity, count;
} hash_table;

hash_table* create_hash_table(size_t initial_capacity) {
    hash_table* table = malloc(sizeof(hash_table));

    if (table == NULL) return NULL;

    table->entries = calloc(initial_capacity, sizeof(hash_entry));

    if (table->entries == NULL) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->count = 0;

    return table;
}

size_t hash1(int key, size_t capacity) {
    return (size_t)key % capacity;
}

size_t hash2(int key) {
    return 1 + ((size_t)key % (capacity - 1));
}

void insert(hash_table* table, int key, long offset) {
    if (table->count == table->capacity) {
        // Handle resizing here...
    }

    size_t index = hash1(key, table->capacity);
    size_t step = hash2(key);

    while (table->entries[index].key != 0) {
        index = (index + step) % table->capacity;
    }

    table->entries[index].key = key;
    table->entries[index].offset = offset;
    ++table->count;
}

long find(hash_table* table, int key) {
    size_t index = hash1(key, table->capacity);
    size_t step = hash2(key);

    while (table->entries[index].key != 0) {
        if (table->entries[index].key == key) return table->entries[index].offset;

        index = (index + step) % table->capacity;
    }

    return -1L; // Key not found
}

void destroy_hash_table(hash_table* table) {
    free(table->entries);
    free(table);
}
``` 

Please note that this is a simplified example and does not handle many aspects of your requirements, such as collision resolution strategies, memory management optimizations, thread safety or validation. Also, C language does not have built-in support for concurrency which would require use of platform-specific features like mutexes (pthreads in Unix/Linux based systems) and critical sections (CRITICAL_SECTION on Windows).
