pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

BSTNode* newNode(double item) {
    BSTNode* temp = (BSTNode*)malloc(sizeof(BSTNode));
    temp->key = item;
    temp->left = temp->right = NULL;
    return temp;
}

// A utility function to do inorder traversal of BST
void inorder(BSTNode* root) {
   if (root != NULL) {
      inorder(root->left);
      printf("%f ", root->key);
      inorder(root->right);
   }
}

// A utility function to insert a new node with given key in BST
BSTNode* insert(BstNode* node, double key) {
    if (node == NULL) return newNode(key);

    pthread_mutex_lock(&lock);

    // If the tree is balanced after every insertion, AVL or Red-Black tree insertions would be more efficient.
    if (key < node->key)
        node->left  = insert(node->left, key);
    else if (key > node->key)
        node->right = insert(node->right, key);   

    pthread_mutex_unlock(&lock);

    return node;
}

// Function to search a given key in a given BST
BstNode* search(BstNode* root, double key) {
    // Base Cases: root is null or key is present at root
    if (root == NULL || root->key == key)
       return root;

    pthread_mutex_lock(&lock);

    // Key is greater than root's key
    if (root->key < key)
       return search(root->right, key);

    // Key is smaller than root's key
    return search(root->left, key);

    pthread_mutex_unlock(&lock);
}

// Function to free memory
void destroy(BstNode* node) {
    if (node == NULL) return;

    // first delete both subtrees
    destroy(node->left);
    destroy(node->right);

    // then delete the node
    printf("\n Deleting node: %f", node->key);
    free(node);
}
```
The above code demonstrates how you can create a Binary Search Tree in C, and insertion and search operations are thread safe. For memory management it uses `malloc` to dynamically allocate memory and `free` for releasing the allocated memory when done with the data. The `pthread_mutex_t lock` ensures that multiple threads do not interfere while accessing/modifying the shared BST data structure. 

Please note, this is a simplified version of how to implement a thread-safe Binary Search Tree in C, you would need additional features such as rotating the tree for balance, checking memory allocation failures etc., and these are omitted here for simplicity. Also, you may want to use custom allocator for more efficient memory management rather than `malloc` and `free`.
']

