#define MAX_SIZE 1024 // max size of the arrays

typedef struct {
    long offset;
} OffsetArray;

typedef struct {
    int key;
} KeyArray;

typedef struct {
    int value;
} Record;

OffsetArray* offset_array = NULL;
KeyArray* key_array = NULL;
Record** record_array = NULL;
int array_size = 0; // initial size of the arrays
atomic_uint current_index = ATOMIC_VAR_INIT(0);
pthread_mutex_t lock;

void allocateMemory(int size) {
    assert(size > 0 && size <= MAX_SIZE);
    offset_array = malloc(sizeof(OffsetArray) * size);
    key_array = malloc(sizeof(KeyArray) * size);
    record_array = malloc(sizeof(Record*) * size);

    for (int i = 0; i < size; ++i) {
        offset_array[i].offset = 0;
        key_array[i].key = 0;
        record_array[i] = NULL;
    }
}

void* allocateRecord(_Atomic(uint)* index, int value) {
    Record* record = malloc(sizeof(Record));
    assert(record != NULL); // check if the allocation was successful

    record->value = value;
    atomic_store(index, (*index + 1) % array_size); // thread safe increment
    return (void*)record;
}

// Thread-safe reallocation of memory
Record* reallocateMemory(int newSize) {
    assert(newSize > 0 && newSize <= MAX_SIZE);

    pthread_mutex_lock(&lock); // lock the mutex to prevent race conditions

    Record** newArray = realloc(record_array, sizeof(Record*) * newSize);
    if (newArray == NULL) {
        perror("realloc() failed");
        exit(EXIT_FAILURE);
    }

    record_array = newArray;

    // Fill in the newly allocated memory with null pointers
    for (int i = array_size; i < newSize; ++i) {
        record_array[i] = NULL;
    }

    pthread_mutex_unlock(&lock); // unlock the mutex after reallocation

    return newArray;
}
``` 
