typedef struct {
    int key;
    long offset;
    int value;
} Record;

typedef struct Bucket {
    pthread_mutex_t lock;
    Record* record; 
    struct Bucket *next; 
} Bucket;

Bucket** hashTable = NULL;
int tableSize = 1024;
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;
FILE* storageFile;

unsigned long hash(int key) {
    return key % tableSize;  // Simple hashing for this example. Replace with a better one in production
}

void insertRecord(int key, long offset, int value) {
    unsigned long index = hash(key);
    pthread_mutex_lock(&globalLock);

    Bucket* bucket = hashTable[index];
    while (bucket != NULL && bucket->record != NULL && bucket->record->key != key) {
        bucket = bucket->next;
    }

    if (bucket == NULL || bucket->record == NULL) {
        pthread_mutex_lock(&bucket->lock);
        Record* newRecord = malloc(sizeof(Record));
        newRecord->key = key;
        newRecord->offset = offset;
        newRecord->value = value;
        bucket->record = newRecord;
        fwrite(&newRecord, sizeof(Record), 1, storageFile);
        pthread_mutex_unlock(&bucket->lock);
    } else {
        // Update the existing record
        pthread_mutex_lock(&bucket->lock);
        bucket->record->offset = offset;
        bucket->record->value = value;
        fseek(storageFile, -sizeof(Record), SEEK_CUR);
        fwrite(&bucket->record, sizeof(Record), 1, storageFile);
        pthread_mutex_unlock(&bucket->lock);
    }

    pthread_mutex_unlock(&globalLock);
}

void deleteRecord(int key) {
    unsigned long index = hash(key);
    pthread_mutex_lock(&globalLock);

    Bucket* bucket = hashTable[index];
    while (bucket != NULL && bucket->record != NULL && bucket->record->key != key) {
        bucket = bucket->next;
    }

    if (bucket != NULL && bucket->record != NULL) {
        pthread_mutex_lock(&bucket->lock);
        free(bucket->record);
        bucket->record = NULL;
        fseek(storageFile, -sizeof(Record), SEEK_CUR);
        Record nullRecord = {0};
        fwrite(&nullRecord, sizeof(Record), 1, storageFile);
        pthread_mutex_unlock(&bucket->lock);
    }

    pthread_mutex_unlock(&globalLock);
}

Record* getRecord(int key) {
    unsigned long index = hash(key);
    pthread_mutex_lock(&globalLock);

    Bucket* bucket = hashTable[index];
    while (bucket != NULL && bucket->record != NULL && bucket->record->key != key) {
        bucket = bucket->next;
    }

