    size_t charsetLen = strlen(charset);
    char* buffer = malloc((length + 1)* sizeof(char)); 

    if (buffer == NULL) {
        // Handle error condition - not enough memory.
        return NULL; 
    }

    for (size_t i = 0; i < length; ++i) {
        buffer[i] = charset[rand() % charsetLen]; // pick a random character from the charset
    }

    buffer[length] = '\0';
    return buffer; 
}

int generateRandomNumber(void) {
    unsigned char byteBuffer[4];

    if (RAND_bytes(byteBuffer, sizeof(byteBuffer)) != 1) {
        // Handle error condition - RAND_bytes failed.
        return -1; 
    }

    int number = 0;

    for (size_t i = 0; i < sizeof(int); ++i) {
