Please note that actual implementation would involve more sophisticated techniques like lock-free programming for better concurrent performance, memory pooling to reduce fragmentation and cache-friendly data layout, as well as a much more sophisticated hash function. Also it is assumed here that 'pthread' library will be used for threads and mutexes:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    float value;
    char tag[10];
    int timestamp;
} SensorData;

typedef struct HashNode {
    SensorData* data;
    struct HashNode* next;
} HashNode;

#define TABLE_SIZE 10007 // a prime number for better distribution
HashNode* hashTable[TABLE_SIZE];
pthread_mutex_t tableLock = PTHREAD_MUTEX_INITIALIZER;

unsigned int hash(char* tag) {
    unsigned long hash = 5381;
    int c;

    while ((c = *tag++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % TABLE_SIZE;
}

void insert(SensorData* data) {
    unsigned int index = hash(data->tag);

    pthread_mutex_lock(&tableLock);
    HashNode* node = malloc(sizeof(HashNode));
    node->data = data;
    node->next = hashTable[index];
    hashTable[index] = node;
    pthread_mutex_unlock(&tableLock);
}

SensorData* lookup(char* tag) {
    unsigned int index = hash(tag);

    pthread_mutex_lock(&tableLock);
    HashNode* node;
    for (node = hashTable[index]; node != NULL; node = node->next) {
        if (strcmp(node->data->tag, tag) == 0) {
            pthread_mutex_unlock(&tableLock);
            return node->data;
        }
    }
    pthread_mutex_unlock(&tableLock);

    return NULL; // data not found
}
``` 

