#define MAX_RECORDS 10000000 // Maximum records size (10 million)
typedef struct Record {
    int value;
    long* offset;
}Record;

typedef struct Metadata{
    int size;
    int flags;
}Metadata;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Initialize a mutex for thread-safety.
long* offsetArray[MAX_RECORDS];
int keyArray[MAX_RECORDS];
Record* recordArray[MAX_RECORDS];
Metadata metadata; 

// A simple custom hash function.
unsigned int hash(int key){
    unsigned int result = 0;
    for (size_t i = 0; i < sizeof(key); ++i) {
        result = result * 31 + ((unsigned char*)&key)[i];
    }
    return result % MAX_RECORDS; // Ensure it fits into our array size.
}

// Insert function to insert a record into the hash table. 
void insert(int key, Record* value){
    pthread_mutex_lock(&lock); // Lock before modifying data.
    unsigned int index = hash(key);
    while (offsetArray[index] != NULL && keyArray[index] != key) {
        index = (index + 1) % MAX_RECORDS; // Handle collision by linear probing.
    }
    keyArray[index] = key;
    recordArray[index] = value;
    pthread_mutex_unlock(&lock); // Unlock after modifying data.
}

// Random number generator, could be improved with a more complex function.
int randomInRange(int minVal, int maxVal){
    return rand() % (maxVal - minVal + 1) + minVal;
}

void initialize(){
    // Initialize records array with random values within the specified range. 
    for (size_t i = 0; i < MAX_RECORDS; ++i){
        int value = randomInRange(metadata.flags, metadata.size);
        long* offset = malloc(sizeof(long)); // Dynamically allocate memory for 'offset'.
        *offset = (long)(value % 1000); // Assign a placeholder value for testing purposes.

        Record* record = malloc(sizeof(Record));
        record->value = value;
        record->offset = offset;

        insert(i, record);
    }
}

void freeMemory(){
    // Free all dynamically allocated memory before program exit. 
    for (size_t i = 0; i < MAX_RECORDS; ++i){
        if(recordArray[i] != NULL) {
            free(recordArray[i]->offset);
            free(recordArray[i]);
        }
    }
}
