#include "external_library.h"  // Assume an external library that provides hash table operations

typedef struct Record {
    int key;
    int value;
    struct Record* next;
} Record;

// Define a custom hash table data structure using the external library
struct HashTable {
    _Atomic(Record*) records[MAX_RECORDS];  // Atomic operations for thread safety
    pthread_rwlock_t locks[MAX_RECORDS];   // Reader/Writer lock for managing concurrency access
};

// Initialize the hash table
void initHashTable(_Atomic(Record*) records[], pthread_rwlock_t locks[]) {
    int i;
    for (i = 0; i < MAX_RECORDS; i++) {
        atomic_init(&records[i], NULL);  // Initialize each record as NULL initially
        pthread_rwlock_init(&locks[i], NULL);  // Initialize lock for each record
    }
}

// Insertion in the hash table
void insertHashTable(_Atomic(Record*) records[], pthread_rwlock_t locks[], int key, int value) {
    int index = external_library_hash_function(key);  // Assume the hash function is defined by an external library

    pthread_rwlock_wrlock(&locks[index]);   // Acquire write lock for the record

    Record* newRecord = malloc(sizeof(Record));
    if (newRecord == NULL) {  // Error handling for memory allocation failure
        // Handle error, e.g., log and exit or retry with exponential backoff
    } else {
        newRecord->key = key;
        newRecord->value = value;
        newRecord->next = atomic_load(&records[index]);  // Set the next pointer of new record to current head of list

        while (!atomic_compare_exchange_weak(&records[index], &newRecord->next, newRecord)) {
            // If compare_exchange fails (another thread has changed the head), retry
        }
    }

    pthread_rwlock_unlock(&locks[index]);  // Release write lock for the record
}

// Lookup in the hash table
int lookupHashTable(_Atomic(Record*) records[], pthread_rwlock_t locks[], int key) {
    int index = external_library_hash_function(key);

    pthread_rwlock_rdlock(&locks[index]);   // Acquire read lock for the record (multiple readers can acquire concurrently)

    Record* currentRecord = atomic_load(&records[index]);  // Load head of list atomically
    while (currentRecord != NULL) {
        if (currentRecord->key == key) {
            pthread_rwlock_unlock(&locks[index]);  // Release read lock for the record
            return currentRecord->value;
        }

        currentRecord = currentRecord->next;  // Move to next record in list
