            throw new Exception("Logging failed");
        }
    }

    private async Task<T> RetryOnExceptionAsync<T>(Func<Task<T>> action, int maxAttempts) {
        var currentAttempt = 0; 

        while (true) {
            try {
                // Attempt to execute the function
                return await action();
            } catch (Exception ex) {
                ++currentAttempt;

                if (currentAttempt > maxAttempts || !IsTransient(ex)) {
                    throw;
                }

                Console.WriteLine($"{DateTime.Now} - Log operation failed, retrying... Error: {ex.Message}");
            }
        }
    }

    private bool IsTransient(Exception ex) {
        // Check if exception is transient and should be retried
        return false;
    }
}
