#include <unistd.h>

typedef struct {
    int id;
    time_t start_time;
    int priority;
} Item;

Item* items = NULL;
size_t capacity = 0;
size_t size = 0;
FILE *logfile = NULL;
int seed;
int min_priority, max_priority;
time_t expiration_duration;

void add_item(int id) {
    if (((double) size / capacity) > 1.2) {
        capacity = capacity ? capacity * 2 : 1;
        Item* temp = realloc(items, capacity * sizeof(Item));
        if (!temp) {
            fprintf(logfile, "%ld ERROR: Failed to resize array\n", time(NULL));
            free(items);
            exit(-1);
        }
        items = temp;
    }
    srand(seed + id);
    int priority = 0;
    while (priority == 0 || priority < min_priority || priority > max_priority) {
        priority = rand();
    }
    time_t start_time = time(NULL) - expiration_duration;
    if (start_time < time(NULL) - 86400) {
        fprintf(logfile, "%ld ERROR: Invalid start time\n", time(NULL));
        exit(-1);
    }
    items[size++] = (Item){.id=id, .start_time=start_time, .priority=priority};
}
```
This code defines a data structure for the items and initializes global variables that are used throughout the program to manage memory and perform operations on the array of items. The `add_item` function manages dynamic memory by resizing the array when needed, sets the priority for each item using a random number generator seeded with the item's id, verifies the start time is not more than 24 hours in the past, and handles allocation failures by exiting with an error code.

