#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/sha.h>

typedef struct {
    int value;
} record;

void* safe_malloc(size_t size) {
    void *p = malloc(size);
    if (p == NULL) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return p;
}

void initialize_data() {
    long* offsets = safe_malloc(10000 * sizeof(*offsets));
    int* keys = safe_malloc(10000 * sizeof(*keys));
    record* records = safe_malloc(10000 * sizeof(*records));

    srand(time(NULL)); // use current time as seed for random generator

    for (int i = 0; i < 10000; ++i) {
        offsets[i] = rand();
        keys[i] = rand();

        records[i].value = rand() % 2000001 - 1000000; // random integer in [-1,000,000, 1,000,000] range
    }

    free(offsets);
    free(keys);
    free(records);
}

AES_KEY* initialize_aes_cipher(const char* password) {
    AES_KEY *enc_key = malloc(sizeof(*enc_key));

    unsigned char key[SHA_DIGEST_LENGTH]; // SHA-1 produces 20 bytes hash

    SHA1((unsigned char*)password, strlen(password), key);

    for (int i = 0; i < AES_BLOCK_SIZE; ++i) {
        if (AES_set_encrypt_key(key, 8*SHA_DIGEST_LENGTH, enc_key) < 0) { // returns 0 on success
            fprintf(stderr, "Error: Cannot set encryption key\n");
            free(enc_key);
            return NULL;
        }
    }

    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE); // generate random IV
    AES_cbc_encrypt((unsigned char*)password, (unsigned char*)password, strlen(password), enc_key, iv, AES_ENCRYPT);

    return enc_key;
}

void cleanup_aes_cipher(AES_KEY *enc_key) {
    free(enc_key);
}
```
In the above code:
- The `safe_malloc` function will handle memory allocation and checks for out of memory errors.
- In `initialize_data`, we are allocating memory for 10,000 elements each for offsets, keys and records. And then we populate these arrays with random values.
- `initialize_aes_cipher` initializes AES-256 cipher using given password. It uses SHA-1 to derive the encryption key from the password, generates a random IV, encrypts the password, and returns the encryption key.
- `cleanup_aes_cipher` disables the cipher by freeing the encryption key memory allocated in `initialize_aes_cipher`.

Please note that you need to include error handling in your actual code for real-world use cases. This is just a basic skeleton and does not take into account many factors like logging, thread safety, potential NULL pointers etc. You will also have to handle OpenSSL related errors as well.
