pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int counter = 0;

void incrementCounter() {
    pthread_mutex_lock(&lock);
    ++counter;
    pthread_mutex_unlock(&lock);
}

void decrementCounter() {
    pthread_mutex_lock(&lock);
    --counter;
    pthread_mutex_unlock(&lock);
}

int generateRandomInt(int lower, int upper) {
