// Structure for storing log configuration data in tree form
typedef struct LogConfigNode {
    char* category;
    int logLevel;
    char* timestampFormat;
    unsigned int loggingFlags;
    struct LogConfigNode** children;
    size_t numChildren;
    pthread_mutex_t lock;
} LogConfigNode;

// Global pointer to the root of the configuration tree
LogConfigNode* configTreeRoot = NULL;

void addCategoryToTree(LogConfigNode* parent, char* category) {
    // Create new node for the category
    LogConfigNode* node = malloc(sizeof(LogConfigNode));
    node->category = strdup(category);
    node->logLevel = 0;  // default log level
    node->timestampFormat = NULL;  // no timestamp format by default
    node->loggingFlags = 0;  // no logging flags by default
    node->children = NULL;
    node->numChildren = 0;

    pthread_mutex_init(&node->lock, NULL);  // initialize lock for concurrency control

    // Add new child to parent's list of children
    if (parent) {
        pthread_mutex_lock(&parent->lock);
        ++(parent->numChildren);
        parent->children = realloc(parent->children, sizeof(LogConfigNode*) * parent->numChildren);
        parent->children[parent->numChildren - 1] = node;
        pthread_mutex_unlock(&parent->lock);
    } else {
        configTreeRoot = node;  // if no parent, this is the root of the tree
    }
}

