    long timestamp;
    int operationalStatus;
    Measurement measurement;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;

int initLogging() {
    /* Initialize logging */
    return 0; // Return value indicating success or failure
}

void insert(long timestamp, int operationalStatus, Measurement measurement) {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        initLogging("Failed to allocate memory");
        return;
    }

    pthread_mutex_lock(&lock); // Lock for thread-safe access

    newNode->timestamp = timestamp;
    newNode->operationalStatus = operationalStatus;
    newNode->measurement = measurement;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock); // Unlock after access
}

int delete(int key) {
    if (head == NULL) return -1;

    Node* prevNode = NULL;
    Node* currNode = head;

    while (currNode != NULL) {
        pthread_mutex_lock(&lock); // Lock for thread-safe access

        if(currNode->measurement.key == key){
            if(prevNode != NULL){
                prevNode->next = currNode->next; 
            }else{
                head = currNode->next;
            }

            free(currNode); // Deallocate memory
            pthread_mutex_unlock(&lock); // Unlock after access
            return 0;
        }

        prevNode = currNode;
        currNode = currNode->next;
        pthread_mutex_unlock(&lock); // Unlock after access
    }

    return -1;
}
```
Remember to handle error cases and edge conditions appropriately. This is a basic example of how you can create a linked list with thread-safe insertion and deletion operations in C.
