#include <string.h>

typedef struct {
    int value;
} Record;

void generate_arrays(long* offsets, int* keys, Record* records, size_t limit) {
    srand((unsigned int) time(NULL)); // Initial seed for random numbers

    long* tempOffsets = (long*) malloc(limit * sizeof(long)); // Temporary buffer for offset values
    if (tempOffsets == NULL) exit(1); // Checking if allocation was successful
    for (size_t i = 0; i < limit; ++i) {
        tempOffsets[i] = i; 
    }

    int* tempKeys = (int*) malloc(limit * sizeof(int)); // Temporary buffer for key values
    if (tempKeys == NULL) exit(1); // Checking if allocation was successful

    bool* usedValues = (bool*) calloc(RAND_MAX, sizeof(bool)); // Boolean array to check if value has been already used
    if (usedValues == NULL) exit(1); 

    for (size_t i = 0; i < limit; ++i) {
        int randVal;

        do {
            randVal = rand(); // Generating a random value
        } while (usedValues[randVal]); // Checking if value has already been used

        usedValues[randVal] = true; 
        tempKeys[i] = randVal; 
    }

    free(usedValues); // Releasing memory for boolean array

    Record* tempRecords = (Record*) malloc(limit * sizeof(Record)); // Temporary buffer for record structures
    if (tempRecords == NULL) exit(1); 

    for (size_t i = 0; i < limit; ++i) {
        int combinedVal = tempOffsets[i] + tempKeys[i];

        tempRecords[i].value = combinedVal;
    }

    // If allocation was successful, copy data from temporary buffers to final arrays
    memcpy(offsets, tempOffsets, limit * sizeof(long)); 
    free(tempOffsets); // Releasing memory for offset buffer

    memcpy(keys, tempKeys, limit * sizeof(int)); 
    free(tempKeys); // Releasing memory for key buffer

    memcpy(records, tempRecords, limit * sizeof(Record)); 
    free(tempRecords); // Releasing memory for record buffer
}
```
