```csharp
using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;
using System.Collections.Concurrent;
using System.Threading.Tasks;
using System.Linq;
using System.Globalization;

public class CSVProcessor 
{
    private readonly BlockingCollection<string> filesToProcess = new BlockingCollection<string>();

    public ConcurrentDictionary<int, List<string>> ProcessedEntries { get; private set; } = new ConcurrentDictionary<int, List<string>>();

    private int TotalFiles = 0;
    private int SuccessfulEntries = 0;
    private int FailedEntries = 0;
    private TimeSpan TotalProcessingTime = TimeSpan.Zero;

    public void Start(CancellationToken cancellationToken, string directoryPath) 
    {
        var files = Directory.EnumerateFiles(directoryPath, "*.csv");

        foreach (var file in files)
            filesToProcess.Add(file);

        // Signal that no more items will be added to the queue
        filesToProcess.CompleteAdding(); 

        var options = new ParallelOptions { CancellationToken = cancellationToken };
        Parallel.ForEach(files, options, ProcessFile); 
    }

    private void ProcessFile(string file)
    {
        Interlocked.Increment(ref TotalFiles);

        var stopwatch = Stopwatch.StartNew();
        try
        {
            using (var reader = new StreamReader(file, true)) 
            {
                string line;

                while ((line = reader.ReadLine()) != null) 
                {
                    var fields = ParseCSVLine(line);

                    if (!IsValidEntry(fields)) 
                    {
                        Interlocked.Increment(ref FailedEntries);
                        continue;
                    }

                    var hashedFields = fields.Select(field => SHA256HashStringForUTF8String(field)).ToList();

                    ProcessedEntries.TryAdd(int.Parse(fields[0]), hashedFields);

                    Interlocked.Increment(ref SuccessfulEntries);
                }
            }
        } 
        catch (Exception ex) 
        {
            // Log error info
            Console.WriteLine($"Error processing file: {file}, Exception: {ex}");
        } 

        stopwatch.Stop();
        TotalProcessingTime += stopwatch.Elapsed;
    }

    private string[] ParseCSVLine(string line) 
    {
        // Implement your CSV parsing here
        return new string[0];
    }

    private bool IsValidEntry(string[] fields) 
    {
        // Implement validation logic for the fields here
        return true;
    }

    private string SHA256HashStringForUTF8String(string input)
    {
        byte[] bytes = Encoding.Default.GetBytes(input);

        var hashstring = new StringBuilder();
        using (var sha = new SHA256Managed()) 
        {
            byte[] hash = sha.ComputeHash(bytes);
            foreach (byte b in hash) 
                hashstring.AppendFormat(CultureInfo.InvariantCulture, "{0:x2}", b);
        }

        return hashstring.ToString();
    }

    public void PrintSummary()
    {
        Console.WriteLine($"Total files processed: {TotalFiles}");
        Console.WriteLine($"Successful entries: {SuccessfulEntries}");
        Console.WriteLine($"Failed entries: {FailedEntries}");

        var averageTimePerEntry = TimeSpan.FromTicks(TotalProcessingTime.Ticks / SuccessfulEntries);
        Console.WriteLine($"Average processing time per entry: {averageTimePerEntry}");
    }
}
```

