    // Allocate memory for an array of `long` integers
    long* values = malloc(array_size * sizeof(long));
    if (values == NULL) return -1; 

    for (int i = 0; i < array_size; ++i) {
        // Initialize each value to a unique value calculated as the product of its index and a constant factor, plus a base offset.
        values[i] = i * factor + offset;
    }

    // Allocate memory for an array of `int` integers
    int* keys = malloc(array_size * 2 * sizeof(int));
    if (keys == NULL) { 
      free(values);
      return -1; 
    }

    // Allocate memory for an array of `Record` pointers
    Record** records = malloc(array_size * sizeof(Record*));
    if (records == NULL) { 
      free(keys);
      free(values);
      return -1; 
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < array_size; ++i) {
        // Initialize each `Record` structure’s `int` field to a random value within a specified range. 
        Record* r = malloc(sizeof(Record));
        if (r == NULL) {
          free(records);
          free(keys);
          free(values);
          return -1;
        }

        // Ensure no two `Record` structures point to the same `long` integer.
        r->lvalue = &values[i]; 
        r->ivalue = min_value + rand() % (max_value - min_value + 1);
        records[i] = r;
    }

    // Iterate over the `Record` array, modifying the `int` field of each `Record` to a new random value.
    for (int i = 0; i < array_size; ++i) {
      pthread_mutex_lock(&mutex);
      records[i]->ivalue = min_value + rand() % (max_value - min_value + 1);
      pthread_mutex_unlock(&mutex);
    }

    // Cleanup
    free(records);
    free(keys);
    free(values);
    return 0;
}
```
Please note that this is a very basic implementation. It lacks important features such as thread pool management, error reporting mechanism and many other production-grade software would have to consider. Also it doesn't handle cases where `min_value` or `max_value` might cause integer overflow during calculations, you may want to add appropriate checks for these situations in your actual code.
"]

