enum EventType {
    /* Define your event types here */
};

int log_event(int fd, int level, struct timeval *timestamp, enum EventType type, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Calculate the size needed for the formatted string
    int size = vsnprintf(NULL, 0, format, args);
    if (size < 0) {
        return -1; // Error during formatting
    }

    // Allocate memory for the log entry with additional metadata
    char* buffer = malloc(size + 1 + sizeof(*timestamp));
    if (!buffer) {
        return -2; // Memory allocation failed
    }

    // Format the log entry into the allocated buffer
    vsprintf(buffer, format, args);

    // Ensure there's enough space for timestamp and null character
    char* timestamp_buf = buffer + size + 1;
    sprintf(timestamp_buf, "Timestamp: %ld.%06ld", timestamp->tv_sec, timestamp->tv_usec);

    // Write the log entry to the file descriptor
    write(fd, buffer, strlen(buffer));

    // Clean up memory and close the file descriptor
    free(buffer);
    close(fd);

    return 0; // Success
}
```

