['Here is an example using NodeJS, Express, Axios and Redis for caching. 

Please replace `YOUR_API_KEY` with your actual API key from the weather provider.

```jsx
const express = require('express');
const axios = require('axios');
const redis = require('redis');
const asyncRedis = require("async-redis");

// Setting up Redis client
let client = redis.createClient();
client.on("error", function(err) {
  console.log("Error " + err);
});

// Create an async version of the client
const asyncClient = asyncRedis.decorate(client);

const app = express();
app.use(express.json());

let unitsMap = {
  'metric': ['°C', 'm/s', '%'],
  'imperial': ['°F', 'mph', '%']
}

// Fetch weather data for a location
async function fetchWeatherData(location, unit) {
  let cacheKey = `${location}_${unit}`;

  // Check if the data is in cache
  const cachedValue = await asyncClient.get(cacheKey);
  if (cachedValue) {
    return JSON.parse(cachedValue);
  } else {
    try {
      let response = await axios.get(`http://api.openweathermap.org/data/2.5/weather?q=${location}&appid=YOUR_API_KEY&units=${unit}`);

      // Cache the data for 1 hour
      asyncClient.setex(cacheKey, 3600, JSON.stringify(response.data));

      return response.data;
    } catch (error) {
      console.log('Error fetching weather data:', error);
      return null;
    }
  }
}

// Get weather data for a location with unit support
app.get('/weather/:location/:unit?', async (req, res) => {
  let location = req.params.location;
  let unit = req.params.unit || 'metric'; // Default to metric if not specified

  if (!unitsMap[unit]) {
    return res.status(400).send('Invalid units');
  }

  try {
    const weatherData = await fetchWeatherData(location, unit);

    // Format output for display in a web application
    let formattedOutput = `Location: ${weatherData.name}\n`;
    formattedOutput += `Temperature: ${weatherData.main.temp}${unitsMap[unit][0]}\n`;
    formattedOutput += `Humidity: ${weatherData.main.humidity}%\n`;

    res.send(formattedOutput);
  } catch (error) {
    console.log('Error fetching weather data:', error);
    res.status(500).send('An error occurred while fetching weather data');
  }
});

app.listen(3000, () => console.log('Server is running on port 3000'));
```

This code uses the OpenWeatherMap API and Redis for caching. Please make sure to replace `YOUR_API_KEY` with your actual API key from OpenWeatherMap. The server listens on port 3000, and you can get weather data by making a GET request to `http://localhost:3000/weather/<location>?unit=<metric|imperial>`.
']

