public class StateLoader {
    private static final String FILE_NAME = "state.ser";

    private static ReentrantLock lock = new ReentrantLock();

    public MoSTState loadState() {
        FileInputStream fileInputStream = null;
        ObjectInputStream objectInputStream = null;

        try {
            fileInputStream = new FileInputStream(FILE_NAME);
            objectInputStream = new ObjectInputStream(fileInputStream);

            lock.lock();  // synchronize block to prevent concurrent writes

            MoSTState mostState = (MoSTState) objectInputStream.readObject();

            return mostState;
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        } finally {
            if(objectInputStream != null){
                try {
                    objectInputStream.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }

            if(fileInputStream != null){
                try {
                    fileInputStream.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }

            lock.unlock(); // unlock after reading from the object stream
        }

        return null;
    }
}
