int numSensors = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initSensor(long offsetValue, int key, Record record) {
    pthread_mutex_lock(&lock);

    SensorReading **temp = realloc(sensorReadings, sizeof(*sensorReadings) * (numSensors + 1));
    if (temp == NULL) {
        fprintf(stderr, "Error allocating memory: %d\n", errno);
        pthread_mutex_unlock(&lock);
        return;
    }

    sensorReadings = temp;

    SensorReading *sensorReading = malloc(sizeof(*sensorReading));
    if (sensorReading == NULL) {
        fprintf(stderr, "Error allocating memory: %d\n", errno);
        pthread_mutex_unlock(&lock);
        return;
    }

    sensorReading->offsetValue = offsetValue;
    sensorReading->key = key;
    sensorReading->record = record;

    sensorReadings[numSensors++] = sensorReading;

    pthread_mutex_unlock(&lock);
}
