char *fileTypes[] = {".txt", ".log", ".csv", ".json"};
int fileTypeCount = 4;

char* renameFile(const char *filename) {
    int filenameLen = strlen(filename);

    if (filenameLen > 256) {
        errno = EINVAL;
        return NULL;
    }

    srand(time(NULL));  // For generating random numbers.

    char *newFilename = malloc(sizeof(char) * 257);  // +1 for null terminator.
    if (newFilename == NULL) {
        errno = ENOMEM;
        return NULL;
    }

    strcpy(newFilename, filename);

    int randLen = rand() % ((filenameLen+1)/3 - 2 + 1) + 2;
    for (int i = 0; i < randLen; ++i) {
        char digit = '0' + rand() % 10;
        strncat(newFilename, &digit, 1);
    }

    int typeIndex = rand() % fileTypeCount;
    strcat(newFilename, fileTypes[typeIndex]);

    if (strlen(newFilename) > 256) {
        errno = EINVAL;
        free(newFilename);
        return NULL;
    }

    return newFilename;
}
``` 

