```c
#include <stdlib.h>
#include <string.h>

typedef struct entry {
    double value;
    size_t index;
} entry;

typedef struct dependency {
    size_t dependentIndex;
    size_t dependeeIndex;
} dependency;

void init(size_t n, float* floats, char* chars, entry** entries, dependency*** dependencies) {
    *floats = malloc(n * sizeof(float));
    if (*floats == NULL) exit(-1);  // handle memory allocation failure gracefully

    *chars = malloc(n * sizeof(char));
    if (*chars == NULL) {
        free(*floats);
        exit(-1);
    }

    *entries = malloc(n * sizeof(entry));
    if (*entries == NULL) {
        free(*floats);
        free(*chars);
        exit(-1);
    }

    // initialize arrays
    memset(*floats, 0, n * sizeof(float));
    for (size_t i = 0; i < n; ++i) {
        (*entries)[i].index = i;
        (*entries)[i].value = 0.0;
    }

    // allocate and initialize dependencies
    *dependencies = malloc(n * sizeof(dependency*));
    if (*dependencies == NULL) {
        free(*floats);
        free(*chars);
        free(*entries);
        exit(-1);
    }

    for (size_t i = 0; i < n; ++i) {
        (*dependencies)[i] = malloc(n * sizeof(dependency));  // assuming max dependencies is n
        if ((*dependencies)[i] == NULL) {
            free(*floats);
            free(*chars);
            free(*entries);

