// Define a transaction structure
typedef struct {
    double* amounts; // array of doubles for multiple financial amounts
    char statusFlag; 
    char* id;        // dynamically allocated string identifier
} Transaction;

Transaction* createTransaction(double amounts[], int amountCount, char flag, char* id) {
    Transaction* transaction = (Transaction*) malloc(sizeof(Transaction));
    if(!transaction) exit(-1);

    // allocate memory for double array and copy values
    transaction->amounts = (double*) malloc(amountCount * sizeof(double));
    memcpy(transaction->amounts, amounts, amountCount * sizeof(double));

    transaction->statusFlag = flag;

    // allocate memory for string and copy value
    int len = strlen(id);
    transaction->id = (char*) malloc((len + 1) * sizeof(char));
    strncpy(transaction->id, id, len);
    transaction->id[len] = '\0';

    return transaction;
}

void destroyTransaction(Transaction* transaction) {
    free(transaction->amounts);
    free(transaction->id);
    free(transaction);
}

// Define a node in hashmap
typedef struct Node{
    char key; 
    double value;
    struct Node *next;
}Node;

// Define Hashmap structure
typedef struct {
    int size, count;
    Node **list;
    pthread_mutex_t lock; // for synchronization
}HashMap;

// Create a hashmap
HashMap* createMap(int size) {
    HashMap *hashMap = (HashMap*) malloc(sizeof(HashMap)); 
    if(!hashMap) exit(-1);

    hashMap->size = size;
    hashMap->count = 0;
    hashMap->list = (Node**)calloc(size, sizeof(Node*));
    if(!hashMap->list) exit(-1); 

    pthread_mutex_init(&hashMap->lock, NULL); // Initialize the lock

    return hashMap;
}

// Destroy hashmap
void destroyMap(HashMap *hashMap) {
    for(int i=0;i<hashMap->size;++i) {
        Node* node = hashMap->list[i]; 
        while(node){ 
            Node* tempNode = node; 
            node = node->next; 
            free(tempNode); 
        } 
    } 

    pthread_mutex_destroy(&hashMap->lock); // destroy the lock
    free(hashMap->list);
    free(hashMap);
}

// Hash function
int hashCode(HashMap *hashMap, char key) {
    return (key%hashMap->size); 
} 

// Put an element in hashmap
void put(HashMap *hashMap, char key, double value){  
    pthread_mutex_lock(&hashMap->lock); // lock for synchronization

    int position = hashCode(hashMap, key);
    Node* list = hashMap->list[position]; 
    Node* newNode= createNode(key, value);  

    if(!list){  
        hashMap->list[position] = newNode; 
        ++hashMap->count; 
    } 
    else{ 
        // Open Addressing collision resolution strategy: Linear probing
        while(list->next) list=list->next; 

        list->next = newNode;
    } 

    pthread_mutex_unlock(&hashMap->lock); // unlock
}

// Get an element from hashmap
double get(HashMap *hashMap, char key){ 
    int position = hashCode(hashMap, key);
    Node* list = hashMap->list[position]; 

    while(list) { 
        if (list->key == key){  
            return list->value; 
        }
        list=list->next;
    } 

    // If not found, return -1 as error code
    return -1; 
}
```
