#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    int value;
} Record;

// Hash table entry
typedef struct Entry {
    long offset;
    int key;
    Record record;
    struct Entry* next;
} Entry;

typedef struct {
    pthread_mutex_t lock;
    size_t size;  // hash table size
    size_t capacity;  // max entries
    size_t loadFactor;  // load factor before resizing
    Entry** buckets;  // array of linked lists
} HashTable;

// Function to create and initialize the hash table
HashTable* createHashTable(size_t capacity, size_t loadFactor) {
    HashTable* ht = malloc(sizeof(HashTable));
    assert(ht != NULL);

    ht->capacity = capacity;
    ht->loadFactor = loadFactor;
    ht->size = 0;

    ht->buckets = malloc(capacity * sizeof(Entry*));
    assert(ht->buckets != NULL);

    for (size_t i = 0; i < capacity; ++i) {
        ht->buckets[i] = NULL;
    }

    pthread_mutex_init(&ht->lock, NULL);

    return ht;
}

// Hash function (simplified for brevity)
size_t hash(int key, size_t capacity) {
    return key % capacity;
}

// Function to insert a new entry into the hash table
void put(HashTable* ht, int key, Record record) {
    pthread_mutex_lock(&ht->lock);  // acquire lock

    if ((ht->size / (double) ht->capacity) > ht->loadFactor) {
        resize(ht);
    }

    size_t index = hash(key, ht->capacity);

    Entry* entry = malloc(sizeof(Entry));
    assert(entry != NULL);

    entry->key = key;
    entry->record = record;
    entry->next = ht->buckets[index];  // insert at the head of the list

    ht->buckets[index] = entry;
    ht->size++;

    pthread_mutex_unlock(&ht->lock);  // release lock
}

// Function to retrieve an entry from the hash table by key
Record* get(HashTable* ht, int key) {
    size_t index = hash(key, ht->capacity);

    pthread_mutex_lock(&ht->lock);  // acquire lock

    for (Entry* entry = ht->buckets[index]; entry != NULL; entry = entry->next) {
        if (entry->key == key) {
            Record* record = &(entry->record);

            pthread_mutex_unlock(&ht->lock);  // release lock

            return record;
        }
    }

    pthread_mutex_unlock(&ht->lock);  // release lock

    return NULL;
}
```
