            continue;
        }
        else if (sscanf(line, "num_threads = %d", &num_threads) == 1){
            continue;
        }
    }

    fclose(fp);

    // Open input file and process in batches
    FILE* input = fopen(input_file, "r");
    if (input == NULL) {
        perror("Error opening input file");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[num_threads];
    atomic_int processed_batches = 0;

    while (!feof(input)) {
        batch_t* batch = malloc(sizeof(batch_t));

        // Allocate memory for arrays and process data here...

        if (processed_batches < num_threads){
            pthread_create(&threads[processed_batches], NULL, &process_batch, batch);
        }
        else{
            pthread_join(threads[processed_batches % num_threads], NULL);
            free(batch);

            // Save processed records here...
        }

        atomic_fetch_add(&processed_batches, 1);
    }

    fclose(input);

    // Wait for all threads to finish and clean up resources
    for (int i = 0; i < num_threads; ++i){
        pthread_join(threads[i], NULL);
    }

    return 0;
}
