```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <string.h>
#include <time.h>

#define BLOCK_SIZE 4096
typedef struct record {
    int value;
} record;

// Memory pool block structure, each memory pool is a linked list of these blocks
typedef struct mempool_block {
    void* data;
    size_t size;
    struct mempool_block *next;
} mempool_block;

mempool_block* create_memory_pool(size_t size) {
    // Allocate a new block from the pool
    mempool_block* block = malloc(sizeof(mempool_block));
    if (block == NULL) return NULL;

    block->data = malloc(size);
    if (block->data == NULL) {
        free(block);
        return NULL;
    }

    // Initialize the pool block with size and pointer to next block
    block->size = size;
    block->next = NULL;

    return block;
}

void destroy_memory_pool(mempool_block* head) {
    mempool_block* current = head;
    while (current != NULL) {
        mempool_block* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
}

void* allocate_from_memory_pool(mempool_block* head, size_t size) {
    mempool_block* current = head;
    while (current != NULL) {
        // Check if the block has enough space for requested allocation
        if ((size_t)(current->data + current->size - current->next) >= size) {
            void* address = current->data;
            current->data += size;
            current->size -= size;
            return address;
        }
        current = current->next;
    }

    // If no space, create a new block and allocate from it
    mempool_block* block = create_memory_pool(BLOCK_SIZE);
    if (block == NULL) return NULL;

    current->next = block;
    void* address = block->data;
    block->data += size;
    block->size -= size;
    return address;
}

void free_from_memory_pool(mempool_block* head, void* address) {
    // Free memory from the pool
    mempool_block* current = head;
    while (current != NULL) {
        if ((char*)address >= current->data && (char*)address < current->data + current->size) {
            free(address);
            return;
        }
        current = current->next;
    }
}

// Other implementations...

int main() {
    // Your code here
}
``` 

This is a basic memory pool implementation that you can extend and adapt to your needs. It uses a linked list of blocks, each block allocating a fixed size (BLOCK_SIZE). When space runs out in the current block, it creates a new block for future allocations. The free operation only frees memory from within its own blocks, not across blocks.

