["This task is quite complex, so here's an example implementation based on POSIX threads and a simple linked list data structure:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#define MAX_RECORDS 1000000 // Adjust as per requirement

typedef struct Record {
    int value;
    struct Record* next;
} Record;

Record *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int recordCount = 0;
long memory[MAX_RECORDS];

void* insertRecord(void* arg) {
    int key = *((int*)arg);
    if (key < MAX_RECORDS && memory[key] == 0) {
        pthread_mutex_lock(&lock);
        recordCount++;
        Record* newNode = malloc(sizeof(Record));
        if (newNode == NULL) exit(1); // Handle allocation failure
        srand(time(NULL)); 
        newNode->value = rand() % ((int)(key + 1)); // Assign a random value within the specified range
        newNode->next = head;
        head = newNode;
        memory[key] = 1;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void* deleteRecord(void* arg) {
    int key = *((int*)arg);
    if (key < MAX_RECORDS && memory[key] == 1) {
        pthread_mutex_lock(&lock);
        Record** indir = &head;
        while ((*indir)->value != key) indir = &((*indir)->next); // Find the node to be deleted
        Record* tempNode = *indir;
        *indir = (*indir)->next;
        free(tempNode);
        memory[key] = 0;
        recordCount--;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void* retrieveRecord(void* arg) {
    int key = *((int*)arg);
    if (key < MAX_RECORDS && memory[key] == 1) {
        pthread_mutex_lock(&lock);
        Record* currNode = head;
        while (currNode != NULL) {
            if (currNode->value == key) break; // Found the node to be retrieved
            currNode = currNode->next; 
        }
        pthread_mutex_unlock(&lock);
        return currNode;
    }
    return NULL;
}

void* resetSystem() {
    while (head != NULL) deleteRecord((void*)&(head->value)); // Delete all records
    return NULL;
}
```
