using System;
using System.Collections.Concurrent;
using UnityEngine;
using System.Diagnostics;
using System.Threading;

public class ValueRecord
{
    public int Key { get; set; }
    public float Value { get; set; }
}

public class DynamicValueProcessor
{
    private ConcurrentDictionary<int, ValueRecord> _records = new ConcurrentDictionary<int, ValueRecord>();
    private PerformanceCounter _performanceCounter = new PerformanceCounter();

    public void AddRecord(int key)
    {
        var record = new ValueRecord()
        {
            Key = key,
            // adjust the range as needed 
            Value = UnityEngine.Random.Range(0f, 1f)
        };

        _records[key] = record;
    }

    public float GetValue(int key)
    {
        var watch = Stopwatch.StartNew();
        if (_records.TryGetValue(key, out ValueRecord value))
        {
            // log a hit
            _performanceCounter.LogHit();

            watch.Stop();
            _performanceCounter.LogTimeTaken(watch.ElapsedMilliseconds);

            return value.Value;
        }
        else
        {
            // log a miss
            _performanceCounter.LogMiss();

            throw new Exception("Record not found");
        }
    }

    public void RemoveRecord(int key)
    {
        _records.TryRemove(key, out ValueRecord value);
    }
}
```

