["Here is a sample code in C using pthreads and mutexes to create a simple connection pool that can be extended/modified according to requirements:

```C
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000
#define INITIAL_CAPACITY 50

typedef struct Connection {
    char srcIP[20];
    char dstIP[20];
    int port;
    unsigned flags:4;
} Connection;

typedef struct ConnectionPool {
    pthread_mutex_t lock;
    Connection* connections;
    size_t capacity;
    size_t length;
} ConnectionPool;

void resize(ConnectionPool *pool, size_t newSize) {
    if (newSize > MAX_CONNECTIONS || newSize < INITIAL_CAPACITY) return; // Out of range

    pthread_mutex_lock(&pool->lock);

    Connection* oldConnections = pool->connections;
    size_t oldCapacity = pool->capacity;

    pool->connections = (Connection*) malloc(sizeof(Connection) * newSize);
    if (oldConnections != NULL) {
        memcpy(pool->connections, oldConnections, sizeof(Connection) * ((newSize < oldCapacity) ? newSize : oldCapacity));
        free(oldConnections);
    }

    pool->capacity = newSize;
    if (pool->length > pool->capacity) {
        pool->length = pool->capacity; // Reduce length to fit in new capacity
    }

    pthread_mutex_unlock(&pool->lock);
}

ConnectionPool* createConnectionPool() {
    ConnectionPool *pool = (ConnectionPool*) malloc(sizeof(ConnectionPool));
    pool->connections = NULL;
    pthread_mutex_init(&pool->lock, NULL);

    resize(pool, INITIAL_CAPACITY);

    return pool;
}
```
