```python
import concurrent.futures
from collections import deque

def parallelTaskExecutor(tasks, maxConcurrency=10, taskPoolSize=1000):
    results = {}
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=maxConcurrency) as executor:
            futureToTask = {executor.submit(task): task for task in deque(tasks, maxlen=taskPoolSize)}
            for future in concurrent.futures.as_completed(futureToTask):
                task = futureToTask[future]
                try:
                    result = future.result()
                    results[task] = result
                except Exception as exc:
                    results[task] = f'Exception occurred: {exc}'
    except concurrent.futures.TimeoutError as e:
        print(f"Task timeout error: {e}")

    return results
``` 

