public class DynamicAudioStreamProcessor
{
    private readonly IHttpClientFactory _httpClientFactory;
    private string minValue;  // Private field for the minimum value

    public DynamicAudioStreamProcessor(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    public async Task<string> GetAsync(Uri uri, IConfiguration config)
    {
        var client = _httpClientFactory.CreateClient();

        foreach (var header in config.GetSection("Headers").GetChildren())
            client.DefaultRequestHeaders.Add(header.Key, header.Value);

        return await client.GetStringAsync(uri).ConfigureAwait(false);
