    private int _seed;
    private long[] _offsetValues;
    private int[] _keys;
    private List<Record> _records;
    private double _min;
    private double _max;

    public DynamicRandomValueGenerator()
    {
        SetRange(0, 1);
        ResetSeed();
        InitializeMemory();
    }

    public void SetRange(double min = 0.0, double max = 1.0)
    {
        if (min > max)
            throw new ArgumentException("Minimum value cannot be greater than maximum value");

        _min = min;
        _max = max;
    }

    public void SetSeed(int seed = 0)
    {
        _seed = seed == 0 ? Environment.TickCount : seed;
        _random = new Random(_seed);
    }

    public void ResetSeed() => SetSeed();

    public int GenerateRandomInteger(bool inclusive = false)
    {
        lock (_random) 
        {
            return inclusive ? _random.Next((int)_min, (int)_max + 1) : _random.Next((int)_min, (int)_max);
        }
    }

    public double GenerateRandomFloat(bool inclusive = false)
    {
        lock (_random) 
        {
            return inclusive ? _random.NextDouble() * (_max - _min) + _min : _random.NextDouble() * (_max - _min);
        }
    }

