    Record record;
    struct node *next;
} Node;

void* allocateAndInitialize(int count, int range) {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);

    for (int i = 0; i < count; ++i) {
        long offset = random() % range;  // Random value within specified range.
        int key = random();  // Random key.

        Record record;
        record.value = random();  // Random integer value.
        strncpy(record.string, "randomlowercaseword", sizeof(record.string) - 1);  // Random lowercase English word.

        Node *node = (Node*)malloc(sizeof(Node));
        if (!node) return NULL;

        node->offset = offset;
        node->key = key;
        node->record = record;
        pthread_mutex_init(&node->next->mutex, NULL);

        // Insertion into linked list. Assuming insertions at the head for simplicity.
        pthread_mutex_lock(&list->mutex);
        node->next = list->head;
        list->head = node;
        pthread_mutex_unlock(&list->mutex);
    }

    return list;
}
