#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
} Record;

typedef struct HashTableNode {
    int key;
    Record* record;
    struct HashTableNode* next;
} HashTableNode;

static pthread_mutex_t *hashMutexes;
static HashTableNode **hashTable;
static size_t tableSize = 1000000;  // Initial capacity, can grow dynamically
static int numThreads = sysconf(_SC_NPROCESSORS_ONLN);

// Dynamically allocate memory for and initialize three arrays: one for 'long' offset values, another for 'int' keys, and a third for 'record' structures.
void init() {
    srand(time(NULL));
    hashTable = calloc(tableSize, sizeof(HashTableNode *));
    if (hashTable == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }
    hashMutexes = malloc(numThreads * sizeof(pthread_mutex_t));
    for (int i = 0; i < numThreads; ++i) {
        pthread_mutex_init(&hashMutexes[i], NULL);
    }
}

// Hash function
size_t hashCode(int key) {
    return key % tableSize;
}

// Insert key-value pair into the hash table.
void insert(int key, Record* record) {
    size_t slot = hashCode(key);

    pthread_mutex_lock(&hashMutexes[slot]);
    HashTableNode *node = malloc(sizeof(HashTableNode));
    if (node == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }
    node->key = key;
    node->record = record;
    node->next = hashTable[slot];
    hashTable[slot] = node;
    pthread_mutex_unlock(&hashMutexes[slot]);
}

// Lookup 'long' offset value given the key. Return NULL if not found.
Record* lookup(int key) {
    size_t slot = hashCode(key);

    pthread_mutex_lock(&hashMutexes[slot]);
    HashTableNode *node;
    for (node = hashTable[slot]; node != NULL; node = node->next) {
        if (node->key == key) break;
    }
    pthread_mutex_unlock(&hashMutexes[slot]);

    return (node == NULL) ? NULL : node->record;
}
```
