// Initialize the memory manager struct
void initMemoryManager(struct MemoryManager *mgr, size_t initialSize) {
    srand(time(NULL)); // seed random number generator
    mgr->offsets = (long*)calloc(initialSize, sizeof(long));
    mgr->keys = (int*)calloc(initialSize, sizeof(int));
    mgr->records = (Record*)calloc(initialSize, sizeof(Record));
    mgr->capacity = initialSize;
    mgr->count = 0;
