// Free the memory allocated to arrays when done
void freeMemoryManager(struct MemoryManager *mgr) {
    free(mgr->offsets);
    free(mgr->keys);
    free(mgr->records);
    mgr->capacity = 0;
    mgr->count = 0;
}

// Add a new record with unique key and random value in the specified range, resizing if necessary
void addRecord(struct MemoryManager *mgr, int minVal, int maxVal) {
    // Resize if full
    if (mgr->count == mgr->capacity) {
        mgr->offsets = realloc(mgr->offsets, 2*mgr->capacity * sizeof(long));
        mgr->keys = realloc(mgr->keys, 2*mgr->capacity * sizeof(int));
        mgr->records = realloc(mgr->records, 2*mgr->capacity * sizeof(Record));
        mgr->capacity *= 2;
    }

    // Generate a unique key and add it to the array
    int newKey;
    do {
        newKey = rand() % (maxVal - minVal + 1) + minVal;
    } while(containsKey(mgr, newKey));

    mgr->keys[mgr->count] = newKey;
    mgr->records[mgr->count].key = newKey;
    mgr->records[mgr->count].offset = rand() % (maxVal - minVal + 1) + minVal; // random value
    ++(mgr->count);
}

// Check if a key is already in the array
int containsKey(struct MemoryManager *mgr, int key){
    for (size_t i = 0; i < mgr->count; ++i) {
        if (mgr->keys[i] == key) return 1;
    }
    return 0;
}
