    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for 'offsets' array.\n");
        return;
    }

    int *keys = malloc(sizeof(int) * keysCount);
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for 'keys' array.\n");
        free(offsets); // Cleanup before returning
        return;
    }

    srand(seed); // Set seed for random number generation

    // Initialize offsets and keys with random values within the provided range
    for (int i = 0; i < offsetsCount; ++i) {
        offsets[i] = rand() % (maxOffset - minOffset + 1) + minOffset;
    }

    for (int i = 0; i < keysCount; ++i) {
        keys[i] = rand() % (maxKey - minKey + 1) + minKey;
    }

    // Allocate memory for array of record pointers
    record_t **records = malloc(sizeof(record_t*) * offsetsCount);
    if (records == NULL) {
        printf("Error: Failed to allocate memory for 'records' array.\n");
        free(offsets); // Cleanup before returning
        free(keys);   // Cleanup before returning
        return;
    }

    // Initialize records with random values within the provided range
    for (int i = 0; i < offsetsCount; ++i) {
        record_t *record = malloc(sizeof(record_t));
        if (record == NULL) {
            printf("Error: Failed to allocate memory for a 'record'.\n");
            // Cleanup before returning, freeing all previously allocated records
            while(--i >= 0) {
                free(records[i]);
            }
            free(records);
            free(offsets);
            free(keys);
            return;
        }

        record->value = rand() % (maxKey - minKey + 1) + minKey; // Initialize value with random number within the provided range
        records[i] = record;
    }

    // Use offsets, keys and records here...

    // Free memory after usage
    for(int i = 0; i < offsetsCount; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}
