typedef struct {
    int value;
    const char* string;
} Record;

typedef struct Entry {
    atomic_int key;
    _Atomic(Record*) record;
    struct Entry* next;
} Entry;

atomic_ullong offset = ATOMIC_VAR_INIT(0);
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
char sharedStringPool[1 << 20]; // 1MB for string pool
Entry** hashTable;
size_t tableSize;

void insert(_Atomic(Record*) record, int key) {
    pthread_mutex_lock(&mutex);
    size_t index = key % tableSize;
    Entry* entry = malloc(sizeof(Entry));
    entry->key = ATOMIC_VAR_INIT(key);
    atomic_store_explicit(&entry->record, record, memory_order_relaxed);
    entry->next = hashTable[index];
    hashTable[index] = entry;
    pthread_mutex_unlock(&mutex);
}

Record* find(int key) {
    size_t index = key % tableSize;
    Entry* curr = atomic_load_explicit(&hashTable[index], memory_order_relaxed);
    while (curr != NULL && atomic_load_explicit(&curr->key, memory_order_relaxed) != key) {
        curr = curr->next;
    }
    return curr ? atomic_load_explicit(&curr->record, memory_order_relaxed) : NULL;
}

void remove(int key) {
    pthread_mutex_lock(&mutex);
    size_t index = key % tableSize;
    Entry* curr = hashTable[index];
    Entry* prev = NULL;
    while (curr != NULL && atomic_load_explicit(&curr->key, memory_order_relaxed) != key) {
        prev = curr;
        curr = curr->next;
    }
    if (curr != NULL) {
        if (prev == NULL) hashTable[index] = curr->next;
        else prev->next = curr->next;
        free(curr);
    }
    pthread_mutex_unlock(&mutex);
}
