["Here is an example of how you could implement this functionality in C:

```C
#include <stdlib.h>
#include <time.h>
#include <assert.h>
#include <stdbool.h>

typedef struct {
    int key;
    int value;
} Record;

// A dynamic array of Records
typedef struct {
    Record* data;  // Pointer to the actual record data
    size_t capacity;  // Total capacity of the allocated memory (in number of records)
    size_t size;      // Current size of the used portion (also in number of records)
} DynamicRecordArray;

// Allocates and initializes a dynamic array with the given initial capacity.
DynamicRecordArray* createDynamicRecordArray(size_t initialCapacity) {
    DynamicRecordArray* arr = malloc(sizeof(DynamicRecordArray));
    if (arr == NULL) return NULL;  // Failed to allocate memory for the array itself.

    // Allocate memory for records themselves, initially null as no records are there yet.
    arr->data = calloc(initialCapacity, sizeof(Record));
    if (arr->data == NULL) {
        free(arr);  // Failed to allocate memory for the records. Free up array struct and return NULL.
        return NULL;
    }

    arr->capacity = initialCapacity;
    arr->size = 0;
    return arr;
}

// Reallocates the array with increased capacity, doubling it each time to amortize cost of allocation.
bool growDynamicRecordArray(DynamicRecordArray* arr) {
    assert(arr != NULL);  // Ensure we're not being passed a null pointer.

    size_t newCapacity = (arr->capacity == 0 ? 1 : arr->capacity * 2);
    Record* newData = realloc(arr->data, sizeof(Record) * newCapacity);
    if (newData == NULL) {
        return false;  // Failed to allocate more memory for the records.
    }

    arr->capacity = newCapacity;
    arr->data = newData;
    return true;
}

// Adds a new record with specified key and value range to the array, possibly growing it if necessary.
bool addRecord(DynamicRecordArray* arr, int key, int minValueInclusive, int maxValueExclusive) {
    assert(minValueInclusive < maxValueExclusive);  // Ensure valid range is provided.

    if (arr->size == arr->capacity && !growDynamicRecordArray(arr)) return false;  // Failed to allocate more memory.

    Record* newRecord = &arr->data[arr->size];
    newRecord->key = key;
    newRecord->value = minValueInclusive + rand() % (maxValueExclusive - minValueInclusive);  // Random value within range.
    ++(arr->size);
    return true;
}

// Frees the memory used by a dynamic array and its records.
void freeDynamicRecordArray(DynamicRecordArray* arr) {
    if (arr == NULL) return;  // Nothing to do for null pointer.

    free(arr->data);  // Free record data first, as it's inside the allocated memory block.
    free(arr);        // Then free the struct itself.
}
```

This is a simplified example and doesn't cover all aspects of your task, but should give you a good starting point for further development. For instance, this code does not handle adding or reading records in parallel without synchronization, which might be needed if multiple threads access the data structure concurrently. It also doesn't include mechanisms for validating the allocated memory structures. This could be done by introducing a simple checksum for each record that would allow detecting corruption of the data when reading it back from memory.
